#[derive(Clone, Debug, Eq, PartialEq)]
pub enum GoalContinuationAdmission {
    Admit {
        reason: orca_core::goal_runtime::GoalContinuationReason,
    },
    Reject {
        code: GoalContinuationRejectCode,
        message: String,
    },
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum GoalContinuationRejectCode {
    GoalInactive,
    Cancelled,
    NonSuccessfulTurn,
    QueuedUserInput,
    PendingInteraction,
    ActiveWorkflow,
    PlanMode,
    DuplicateAdmission,
    PendingVerification,
    BudgetLimited,
    RuntimeUnavailable,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum GoalTurnDisposition {
    /// The outer turn completed normally and advanced the goal.
    Advanced,
    /// The outer turn stopped at a resumable runtime wall.
    Interrupted {
        reason: crate::lifecycle::TurnEndReason,
    },
    /// Continuation needs user, budget, verifier, or infrastructure intervention.
    Blocked {
        status: RunStatus,
        reason: crate::lifecycle::TurnEndReason,
    },
}

/// Classifies an outer turn for goal continuation from the typed terminal
/// (when present) plus the legacy status/reason projection.
fn goal_turn_disposition(
    status: RunStatus,
    reason: crate::lifecycle::TurnEndReason,
    terminal: Option<&orca_core::budget::OperationTerminal>,
) -> GoalTurnDisposition {
    match terminal {
        Some(orca_core::budget::OperationTerminal::Stopped {
            resumable: true, ..
        }) => GoalTurnDisposition::Interrupted { reason },
        Some(orca_core::budget::OperationTerminal::Stopped {
            resumable: false, ..
        }) => GoalTurnDisposition::Blocked { status, reason },
        _ => match status {
            RunStatus::Success => GoalTurnDisposition::Advanced,
            _ => GoalTurnDisposition::Blocked { status, reason },
        },
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct GoalContinuationPreflight {
    cancelled: bool,
    disposition: GoalTurnDisposition,
    queued_user_input: bool,
    active_workflow: bool,
    plan_mode: bool,
    duplicate_admission: bool,
}

fn goal_continuation_preflight(
    input: GoalContinuationPreflight,
) -> Option<GoalContinuationAdmission> {
    let reject = |code, message: &str| GoalContinuationAdmission::Reject {
        code,
        message: message.to_string(),
    };
    if input.cancelled {
        return Some(reject(
            GoalContinuationRejectCode::Cancelled,
            "goal continuation rejected because the operation was cancelled",
        ));
    }
    if matches!(input.disposition, GoalTurnDisposition::Blocked { .. }) {
        return Some(reject(
            GoalContinuationRejectCode::NonSuccessfulTurn,
            "goal continuation rejected because the outer turn is blocked",
        ));
    }
    if input.queued_user_input {
        return Some(reject(
            GoalContinuationRejectCode::QueuedUserInput,
            "goal continuation yielded to queued user input",
        ));
    }
    if input.active_workflow {
        return Some(reject(
            GoalContinuationRejectCode::ActiveWorkflow,
            "goal continuation waits for active workflow ownership",
        ));
    }
    if input.plan_mode {
        return Some(reject(
            GoalContinuationRejectCode::PlanMode,
            "goal continuation is disabled while the runtime is in plan mode",
        ));
    }
    if input.duplicate_admission {
        return Some(reject(
            GoalContinuationRejectCode::DuplicateAdmission,
            "goal continuation was already admitted for this generation fence",
        ));
    }
    None
}

