pub struct RuntimeThreadStartRequest {
    config: RunConfig,
    title: String,
    preloaded: Option<SessionTranscript>,
    inherited_conversation: Option<Conversation>,
    parent_thread_id: Option<String>,
    mcp_registry: Option<McpRegistry>,
    prepared_record_meta: Option<SessionMeta>,
    prepared_runtime_thread_id: Option<String>,
    ephemeral_one_shot: Option<surface::FirstOperationCompletionPolicy>,
    ephemeral_reservation_timeout: Duration,
    #[cfg(test)]
    ephemeral_close_commit_failures: usize,
    replace_resume_scope: bool,
}

impl RuntimeThreadStartRequest {
    pub fn new(config: RunConfig, title: impl Into<String>) -> Self {
        Self {
            config,
            title: title.into(),
            preloaded: None,
            inherited_conversation: None,
            parent_thread_id: None,
            mcp_registry: None,
            prepared_record_meta: None,
            prepared_runtime_thread_id: None,
            ephemeral_one_shot: None,
            ephemeral_reservation_timeout: Duration::from_millis(
                surface::SURFACE_RESERVATION_LEASE_MS,
            ),
            #[cfg(test)]
            ephemeral_close_commit_failures: 0,
            replace_resume_scope: false,
        }
    }

    pub fn with_preloaded(mut self, preloaded: SessionTranscript) -> Self {
        self.preloaded = Some(preloaded);
        self
    }

    fn with_attached_side_context(
        mut self,
        parent_thread_id: impl Into<String>,
        conversation: Conversation,
    ) -> Self {
        self.config.history_mode = HistoryMode::Disabled;
        self.config.auto_memory = false;
        self.config.approval_mode = ApprovalMode::Plan;
        self.inherited_conversation = Some(conversation);
        self.parent_thread_id = Some(parent_thread_id.into());
        self
    }

    pub fn with_mcp_registry(mut self, mcp_registry: McpRegistry) -> Self {
        self.mcp_registry = Some(mcp_registry);
        self
    }

    pub fn with_ephemeral_non_catalogued_one_shot(
        mut self,
        close_after: surface::FirstOperationCompletionPolicy,
    ) -> Self {
        self.ephemeral_one_shot = Some(close_after);
        self
    }

    pub(crate) fn with_resume_scope_replacement(mut self) -> Self {
        self.replace_resume_scope = true;
        self
    }

    fn start(self) -> io::Result<RuntimeThread> {
        let inherited_conversation = self.inherited_conversation;
        let mcp_registry = self
            .mcp_registry
            .unwrap_or_else(|| orca_mcp::initialize_registry(&self.config.mcp_servers));
        let mut thread = RuntimeThread::start_with_prepared_history_and_runtime_id(
            &self.config,
            self.title,
            self.preloaded,
            mcp_registry,
            self.prepared_record_meta,
            self.prepared_runtime_thread_id,
        )?;
        if let Some(mut conversation) = inherited_conversation {
            conversation.internal_context = Default::default();
            conversation.add_system_pinned(SIDE_CONVERSATION_BOUNDARY.to_string());
            *thread.session_mut().conversation_mut() = conversation;
        }
        Ok(thread)
    }

    fn prepare(mut self) -> Result<PreparedRuntimeThreadStart, RuntimeHostError> {
        if self.inherited_conversation.is_some() {
            if !matches!(self.config.history_mode, HistoryMode::Disabled) {
                return Err(RuntimeHostError::ThreadStartFailed {
                    message: "attached side conversation requires disabled history".to_string(),
                });
            }
            self.parent_thread_id.as_deref().ok_or_else(|| {
                RuntimeHostError::ThreadStartFailed {
                    message: "attached side conversation requires a parent thread".to_string(),
                }
            })?;
            let raw_thread_id = uuid::Uuid::now_v7();
            let thread_id = raw_thread_id.to_string();
            let surface_thread_id = surface::SurfaceThreadId::try_from_bytes(
                *raw_thread_id.as_bytes(),
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("invalid attached surface thread identity: {error:?}"),
            })?;
            let owner_lease = surface::ExclusiveOwnerLease::acquire_process_local_thread(
                surface_thread_id.clone(),
                &HostSurfaceClock::now(),
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("failed to acquire attached surface owner lease: {error:?}"),
            })?;
            self.config.subagents.max_depth = 0;
            self.config.subagents.max_parallel = 1;
            self.prepared_runtime_thread_id = Some(thread_id.clone());
            return Ok(PreparedRuntimeThreadStart {
                request: self,
                surface_owner: Some(PreparedSurfaceOwner {
                    thread_id,
                    surface_thread_id,
                    owner_lease,
                    persistence: PreparedSurfacePersistence::EphemeralAttached,
                }),
                resume_scope_replacement: None,
            });
        }
        if let Some(close_after) = self.ephemeral_one_shot {
            if !matches!(self.config.history_mode, HistoryMode::Disabled) {
                return Err(RuntimeHostError::ThreadStartFailed {
                    message: "ephemeral one-shot surface requires disabled history".to_string(),
                });
            }
            self.config.auto_memory = false;
            let raw_thread_id = uuid::Uuid::now_v7();
            let thread_id = raw_thread_id.to_string();
            let surface_thread_id = surface::SurfaceThreadId::try_from_bytes(
                *raw_thread_id.as_bytes(),
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("invalid ephemeral surface thread identity: {error:?}"),
            })?;
            let owner_lease = surface::ExclusiveOwnerLease::acquire_process_local_thread(
                surface_thread_id.clone(),
                &HostSurfaceClock::now(),
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("failed to acquire ephemeral surface owner lease: {error:?}"),
            })?;
            self.prepared_runtime_thread_id = Some(thread_id.clone());
            return Ok(PreparedRuntimeThreadStart {
                request: self,
                surface_owner: Some(PreparedSurfaceOwner {
                    thread_id,
                    surface_thread_id,
                    owner_lease,
                    persistence: PreparedSurfacePersistence::EphemeralNonCataloguedOneShot {
                        close_after,
                    },
                }),
                resume_scope_replacement: None,
            });
        }
        let (thread_id, path) = match self.config.history_mode.clone() {
            HistoryMode::Record => {
                let cwd = self.config.cwd.clone().unwrap_or_else(|| {
                    std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("/"))
                });
                let meta = SessionStore::new().create_meta_with_permissions(
                    &cwd,
                    self.config.provider.as_str(),
                    self.config.model.as_history_value(),
                    &self.title,
                    self.config.active_permission_profile.clone(),
                    self.config.approval_mode,
                    self.config.permission_rules.clone(),
                    self.config.additional_working_directories.clone(),
                );
                let path =
                    crate::history::prospective_session_path(&meta.session_id, meta.created_at);
                let thread_id = meta.session_id.clone();
                self.prepared_record_meta = Some(meta);
                (thread_id, path)
            }
            HistoryMode::Resume(selector) | HistoryMode::ResumeAt { selector, .. } => {
                let transcript = match self.preloaded.take() {
                    Some(transcript) => transcript,
                    None => SessionStore::new()
                        .load_session(&selector)
                        .map_err(|error| RuntimeHostError::ThreadStartFailed {
                            message: error.to_string(),
                        })?,
                };
                let thread_id = transcript.meta.session_id.clone();
                let path = transcript.path.clone();
                self.preloaded = Some(transcript);
                (thread_id, path)
            }
            HistoryMode::Fork(selector) => {
                let transcript = match self.preloaded.take() {
                    Some(transcript) => transcript,
                    None => SessionStore::new()
                        .load_session(&selector)
                        .map_err(|error| RuntimeHostError::ThreadStartFailed {
                            message: error.to_string(),
                        })?,
                };
                let cwd = self.config.cwd.clone().unwrap_or_else(|| {
                    std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("/"))
                });
                let store = SessionStore::new();
                let mut meta = store.create_fork_meta(
                    &cwd,
                    self.config.provider.as_str(),
                    self.config.model.as_history_value(),
                    &self.title,
                    transcript.meta.session_id.clone(),
                );
                meta.active_permission_profile = self.config.active_permission_profile.clone();
                meta.approval_mode = Some(self.config.approval_mode);
                meta.permission_rules = self.config.permission_rules.clone();
                meta.additional_working_directories =
                    self.config.additional_working_directories.clone();
                let path =
                    crate::history::prospective_session_path(&meta.session_id, meta.created_at);
                let thread_id = meta.session_id.clone();
                self.prepared_record_meta = Some(meta);
                self.preloaded = Some(transcript);
                (thread_id, path)
            }
            _ => {
                return Ok(PreparedRuntimeThreadStart {
                    request: self,
                    surface_owner: None,
                    resume_scope_replacement: None,
                });
            }
        };
        let Ok(raw_thread_id) = uuid::Uuid::parse_str(&thread_id) else {
            return Ok(PreparedRuntimeThreadStart {
                request: self,
                surface_owner: None,
                resume_scope_replacement: None,
            });
        };
        let surface_thread_id = surface::SurfaceThreadId::try_from_bytes(*raw_thread_id.as_bytes())
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("invalid surface thread identity: {error:?}"),
            })?;
        let owner_lease = surface::ExclusiveOwnerLease::acquire_thread(
            path.with_extension("surface-owner.lock"),
            path.with_extension("surface-owner.epoch"),
            surface_thread_id.clone(),
            &HostSurfaceClock::now(),
        )
        .map_err(|error| RuntimeHostError::ThreadStartFailed {
            message: format!("failed to acquire typed surface owner lease: {error:?}"),
        })?;
        let resume_scope_replacement = (self.replace_resume_scope
            && matches!(
                self.config.history_mode,
                HistoryMode::Resume(_) | HistoryMode::ResumeAt { .. }
            ))
        .then(|| ResumeScopeReplacement {
            runtime_workspace_roots: self
                .config
                .runtime_workspace_roots
                .clone()
                .unwrap_or_else(|| self.config.cwd.clone().into_iter().collect::<Vec<_>>()),
            additional_working_directories: self.config.additional_working_directories.clone(),
        });
        Ok(PreparedRuntimeThreadStart {
            request: self,
            surface_owner: Some(PreparedSurfaceOwner {
                thread_id,
                surface_thread_id,
                owner_lease,
                persistence: PreparedSurfacePersistence::Recorded { path },
            }),
            resume_scope_replacement,
        })
    }
}

struct PreparedRuntimeThreadStart {
    request: RuntimeThreadStartRequest,
    surface_owner: Option<PreparedSurfaceOwner>,
    resume_scope_replacement: Option<ResumeScopeReplacement>,
}

struct ResumeScopeReplacement {
    runtime_workspace_roots: Vec<std::path::PathBuf>,
    additional_working_directories: Vec<orca_core::config::AdditionalWorkingDirectory>,
}

struct PreparedSurfaceOwner {
    thread_id: String,
    surface_thread_id: surface::SurfaceThreadId,
    owner_lease: surface::ExclusiveOwnerLease,
    persistence: PreparedSurfacePersistence,
}

enum PreparedSurfacePersistence {
    Recorded {
        path: std::path::PathBuf,
    },
    EphemeralNonCataloguedOneShot {
        close_after: surface::FirstOperationCompletionPolicy,
    },
    EphemeralAttached,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum RuntimeThreadMutation {
    SetModel(Option<String>),
    AddPinnedContext(String),
    ReplaceSkillContext(Option<String>),
}

impl RuntimeThreadMutation {
    fn apply(self, thread: &mut RuntimeThread) {
        match self {
            Self::SetModel(model) => thread.session_mut().set_model(model.as_deref()),
            Self::AddPinnedContext(content) => thread.session_mut().add_pinned_context(content),
            Self::ReplaceSkillContext(content) => {
                thread.session_mut().replace_skill_context(content);
            }
        }
    }
}

