fn unavailable_surface_handle(
    host_incarnation: surface::HostIncarnation,
) -> surface::RuntimeSurfaceHandle {
    let thread_id = surface::SurfaceThreadId::try_from_bytes(*uuid::Uuid::new_v4().as_bytes())
        .expect("generated UUID is valid");
    let authority = surface::SurfaceAttachAuthority::new(
        host_incarnation.clone(),
        thread_id.clone(),
        surface::SurfaceAttachmentRole::Tui,
        surface::NonEmptySet::try_new(BTreeSet::from([surface::SurfaceCapability::ReadSnapshot]))
            .expect("unavailable surface grant is non-empty"),
        surface::NonEmptySet::try_new(BTreeSet::from([surface::SurfaceCapability::ReadSnapshot]))
            .expect("unavailable surface required grant is non-empty"),
        BTreeSet::new(),
    );
    surface::RuntimeSurfaceHandle::new(host_incarnation, thread_id, authority)
}

fn settle_goal_surface_mutation_on_start<L: surface::SurfaceCommitLedger>(
    coordinator: &mut surface::RuntimeCommitCoordinator<'static, L>,
    runtime: &GoalRuntimeHandle,
    mutation: &GoalSurfaceMutationRecord,
) -> Result<(), RuntimeHostError> {
    let thread_id = coordinator.state().snapshot().thread.thread_id.clone();
    let (goal_fence, receipt_digest, commit_id, scope, event) =
        surface_goal_mutation_event(mutation, thread_id)?;
    if !coordinator
        .state()
        .has_goal_store_receipt(&commit_id, &receipt_digest)
    {
        let mut events = vec![(scope, event)];
        let operation = goal_surface_operation(mutation);
        if let Some(operation) = operation {
            events.push((
                surface::SurfaceScope::Operation {
                    operation_id: operation.operation_id.clone(),
                },
                surface::SurfaceEvent::Operation(surface::OperationPatch::Requested {
                    operation: operation.clone(),
                }),
            ));
        }
        let batch =
            runtime_surface_event_batch(coordinator.state().snapshot(), events, Some(commit_id));
        let mut committed = false;
        for attempt in 0..SURFACE_SEMANTIC_COMMIT_RETRY_ATTEMPTS {
            let result = if operation.is_some() {
                coordinator.commit_actor_goal_batch(
                    goal_fence.clone(),
                    receipt_digest.clone(),
                    &batch,
                )
            } else {
                coordinator.commit_goal_batch(goal_fence.clone(), receipt_digest.clone(), &batch)
            };
            match result {
                Ok(_) => {
                    committed = true;
                    break;
                }
                Err(surface::SurfaceCommitError::Ledger(error))
                    if attempt + 1 < SURFACE_SEMANTIC_COMMIT_RETRY_ATTEMPTS
                        && matches!(
                            error,
                            surface::SurfaceLedgerError::AppendFailed
                                | surface::SurfaceLedgerError::PartialAppend
                                | surface::SurfaceLedgerError::CheckpointFailed
                        ) => {}
                Err(error) => {
                    return Err(RuntimeHostError::ThreadStartFailed {
                        message: format!(
                            "failed to recover durable Goal surface mutation: {error:?}"
                        ),
                    });
                }
            }
        }
        if !committed {
            return Err(RuntimeHostError::ThreadStartFailed {
                message: "durable Goal surface mutation did not recover after bounded retries"
                    .to_string(),
            });
        }
    }
    let acknowledged = runtime
        .acknowledge_surface_mutation(
            &mutation.receipt.store_commit_id,
            &mutation.receipt.receipt_digest,
        )
        .map_err(|error| RuntimeHostError::ThreadStartFailed {
            message: format!("failed to settle recovered Goal surface outbox: {error}"),
        })?;
    if !acknowledged {
        return Err(RuntimeHostError::ThreadStartFailed {
            message: "recovered Goal surface outbox rejected its exact receipt".to_string(),
        });
    }
    Ok(())
}

fn replace_interrupted_goal_continuation_on_start<L: surface::SurfaceCommitLedger>(
    coordinator: &mut surface::RuntimeCommitCoordinator<'static, L>,
    runtime: &GoalRuntimeHandle,
    pending: &[GoalSurfaceMutationRecord],
) -> Result<BTreeSet<String>, RuntimeHostError> {
    let interrupted = pending.iter().rev().find(|mutation| {
        matches!(
            mutation.mutation,
            GoalSurfaceMutation::ContinuationStopped { .. }
                | GoalSurfaceMutation::ContinuationAdmitted { .. }
        ) && surface_goal_mutation_event(
            mutation,
            coordinator.state().snapshot().thread.thread_id.clone(),
        )
        .is_ok_and(|(_, receipt_digest, commit_id, _, _)| {
            !coordinator
                .state()
                .has_goal_store_receipt(&commit_id, &receipt_digest)
        })
    });
    let Some(interrupted) = interrupted else {
        return Ok(BTreeSet::new());
    };
    let predecessor = match &interrupted.mutation {
        GoalSurfaceMutation::ContinuationStopped { predecessor, .. }
        | GoalSurfaceMutation::ContinuationAdmitted { predecessor, .. } => predecessor.as_ref(),
        _ => unreachable!("interrupted mutation was filtered"),
    };
    let snapshot = coordinator.state().snapshot();
    let goal = snapshot
        .goal
        .as_ref()
        .ok_or_else(|| RuntimeHostError::ThreadStartFailed {
            message: "interrupted Goal continuation has no typed Goal snapshot".to_string(),
        })?;
    let run = goal
        .current_run
        .as_ref()
        .ok_or_else(|| RuntimeHostError::ThreadStartFailed {
            message: "interrupted Goal continuation has no current typed run".to_string(),
        })?;
    if goal.goal_id.as_str() != predecessor.goal_id.as_str()
        || run.goal_run_id.as_str() != predecessor.goal_run_id.as_str()
        || run.operation_id != predecessor.operation_fence.operation_id
    {
        return Err(RuntimeHostError::ThreadStartFailed {
            message: "interrupted Goal continuation disagrees with the typed run".to_string(),
        });
    }
    let stale_run_settled = match &run.phase {
        surface::SurfaceGoalRunPhase::InFlight { outer_turn }
            if outer_turn.outer_turn_id == predecessor.goal_outer_turn_id =>
        {
            false
        }
        surface::SurfaceGoalRunPhase::Settled {
            last_outer_turn: Some(outer_turn),
        } if outer_turn.outer_turn_id == predecessor.goal_outer_turn_id => true,
        _ => {
            return Err(RuntimeHostError::ThreadStartFailed {
                message: "interrupted Goal continuation cannot close a different outer turn"
                    .to_string(),
            });
        }
    };
    let surface_previous_revision = u32::try_from(goal.goal_revision.get()).map_err(|_| {
        RuntimeHostError::ThreadStartFailed {
            message: "Goal revision exceeds durable store range".to_string(),
        }
    })?;
    let recovery_message =
        "recovered a committed Goal settlement whose continuation batch was interrupted";
    let command_digest = *surface_sha256(
        &serde_json::to_vec(&(
            "replace_interrupted_goal_continuation",
            &interrupted.receipt.store_commit_id,
            &interrupted.receipt.receipt_digest,
            surface_previous_revision,
            stale_run_settled,
        ))
        .expect("Goal continuation recovery digest input is serializable"),
    )
    .as_bytes();
    let recovery = runtime
        .replace_continuation_with_recovery_for_surface(
            ReplaceGoalContinuationForSurfaceInput {
                interrupted: interrupted.clone(),
                surface_previous_revision,
                stale_run_settled,
                recovery_message: recovery_message.to_string(),
                recovered_at: chrono::Utc::now().timestamp(),
            },
            GoalSurfaceMutationContext {
                store_commit_id: uuid::Uuid::now_v7().to_string(),
                command_digest,
                goal_owner_epoch: snapshot.thread.owner_epoch.get(),
            },
        )
        .map_err(|error| RuntimeHostError::ThreadStartFailed {
            message: format!(
                "failed to create a durable Goal continuation recovery receipt: {error}"
            ),
        })?;
    settle_goal_surface_mutation_on_start(coordinator, runtime, &recovery)?;

    let mut superseded = BTreeSet::new();
    for mutation in pending {
        let same_predecessor = match &mutation.mutation {
            GoalSurfaceMutation::OuterTurnFinished { identity, .. }
            | GoalSurfaceMutation::VerificationCompleted { identity, .. } => {
                identity.as_ref() == predecessor
            }
            GoalSurfaceMutation::ContinuationStopped {
                predecessor: candidate,
                ..
            }
            | GoalSurfaceMutation::ContinuationAdmitted {
                predecessor: candidate,
                ..
            } => candidate.as_ref() == predecessor,
            _ => false,
        };
        if !same_predecessor {
            continue;
        }
        superseded.insert(mutation.receipt.store_commit_id.clone());
    }
    Ok(superseded)
}

fn reconcile_goal_surface_outbox_on_start(
    thread: &mut RuntimeThread,
    coordinator: &mut surface::RuntimeCommitCoordinator<'static, surface::JsonlSurfaceCommitLedger>,
) -> Result<(), RuntimeHostError> {
    let Some(session_id) = thread.session().session_id().map(str::to_string) else {
        return Ok(());
    };
    let store = GoalStore::load_default().map_err(|error| RuntimeHostError::ThreadStartFailed {
        message: format!("failed to inspect Goal store for surface recovery: {error}"),
    })?;
    let has_pending = !store
        .pending_surface_mutations(&session_id)
        .map_err(|error| RuntimeHostError::ThreadStartFailed {
            message: format!("failed to inspect durable Goal surface outbox: {error}"),
        })?
        .is_empty();
    let has_goal = store
        .get_by_session(&session_id)
        .map_err(|error| RuntimeHostError::ThreadStartFailed {
            message: format!("failed to inspect durable Goal for surface recovery: {error}"),
        })?
        .is_some();
    if !has_pending && !has_goal {
        return Ok(());
    }
    drop(store);
    let runtime =
        thread
            .goal_runtime_handle()
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("failed to open Goal runtime for surface recovery: {error}"),
            })?;
    let pending = runtime
        .pending_surface_mutations(&session_id)
        .map_err(|error| RuntimeHostError::ThreadStartFailed {
            message: format!("failed to read durable Goal surface outbox: {error}"),
        })?;
    let superseded =
        replace_interrupted_goal_continuation_on_start(coordinator, &runtime, &pending)?;
    for mutation in pending {
        if superseded.contains(&mutation.receipt.store_commit_id) {
            continue;
        }
        settle_goal_surface_mutation_on_start(coordinator, &runtime, &mutation)?;
    }
    let stored =
        runtime
            .read(&session_id)
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("failed to inspect durable Goal during surface recovery: {error}"),
            })?;
    let Some(stored) = stored else {
        return Ok(());
    };
    let surface_goal = coordinator.state().snapshot().goal.clone();
    match surface_goal {
        None => {
            let owner_epoch = coordinator.state().snapshot().thread.owner_epoch.get();
            let command_digest = *surface_sha256(
                &serde_json::to_vec(&("adopt_goal", &session_id, &stored))
                    .expect("Goal adoption digest input is serializable"),
            )
            .as_bytes();
            let mutation = runtime
                .adopt_for_surface(
                    &session_id,
                    GoalSurfaceMutationContext {
                        store_commit_id: uuid::Uuid::now_v7().to_string(),
                        command_digest,
                        goal_owner_epoch: owner_epoch,
                    },
                )
                .map_err(|error| RuntimeHostError::ThreadStartFailed {
                    message: format!("failed to adopt legacy Goal into typed surface: {error}"),
                })?;
            settle_goal_surface_mutation_on_start(coordinator, &runtime, &mutation)?;
        }
        Some(goal) => {
            if stored.goal_id.as_str() != goal.goal_id.as_str() {
                return Err(RuntimeHostError::ThreadStartFailed {
                    message: "Goal store identity disagrees with recovered typed surface"
                        .to_string(),
                });
            }
            if let (Some(stored_run), Some(surface_run)) =
                (stored.current_run.as_ref(), goal.current_run.as_ref())
            {
                if stored_run.goal_run_id.as_str() != surface_run.goal_run_id.as_str() {
                    return Err(RuntimeHostError::ThreadStartFailed {
                        message: "Goal store run identity disagrees with recovered typed surface"
                            .to_string(),
                    });
                }
                let operation_terminal = coordinator
                    .state()
                    .snapshot()
                    .operation_history
                    .iter()
                    .any(|operation| {
                        operation.operation_id == surface_run.operation_id
                            && operation.terminal.is_some()
                    });
                if operation_terminal {
                    let stale_identity = match &surface_run.phase {
                        surface::SurfaceGoalRunPhase::Preparing => None,
                        surface::SurfaceGoalRunPhase::InFlight { .. } => Some(
                            coordinator
                                .state()
                                .snapshot()
                                .operation_history
                                .iter()
                                .find(|operation| {
                                    operation.operation_id == surface_run.operation_id
                                })
                                .and_then(|operation| {
                                    operation
                                        .generations
                                        .iter()
                                        .rev()
                                        .find_map(|generation| generation.goal_identity.clone())
                                })
                                .ok_or_else(|| RuntimeHostError::ThreadStartFailed {
                                    message: "in-flight Goal recovery lacks its exact generation identity"
                                        .to_string(),
                                })?,
                        ),
                        surface::SurfaceGoalRunPhase::Settled { .. } => {
                            return Err(RuntimeHostError::ThreadStartFailed {
                                message:
                                    "terminal operation cannot recover an already-settled Goal run"
                                        .to_string(),
                            });
                        }
                    };
                    let expected_goal_revision =
                        u32::try_from(goal.goal_revision.get()).map_err(|_| {
                            RuntimeHostError::ThreadStartFailed {
                                message: "Goal revision exceeds durable store range".to_string(),
                            }
                        })?;
                    let recovery_message =
                        "recovered a Goal run whose runtime operation ended during restart"
                            .to_string();
                    let command_digest = *surface_sha256(
                        &serde_json::to_vec(&(
                            "recover_goal_run",
                            &session_id,
                            goal.goal_id.as_str(),
                            goal.goal_revision.get(),
                            surface_run.operation_id.as_bytes(),
                            &stale_identity,
                        ))
                        .expect("Goal recovery digest input is serializable"),
                    )
                    .as_bytes();
                    let mutation = runtime
                        .recover_run_for_surface(
                            RecoverGoalRunForSurfaceInput {
                                session_id: session_id.clone(),
                                expected_goal_id: stored.goal_id,
                                expected_goal_revision,
                                stale_identity: stale_identity.map(Box::new),
                                recovery_message,
                                recovered_at: chrono::Utc::now().timestamp(),
                            },
                            GoalSurfaceMutationContext {
                                store_commit_id: uuid::Uuid::now_v7().to_string(),
                                command_digest,
                                goal_owner_epoch: coordinator
                                    .state()
                                    .snapshot()
                                    .thread
                                    .owner_epoch
                                    .get(),
                            },
                        )
                        .map_err(|error| RuntimeHostError::ThreadStartFailed {
                            message: format!("failed to recover durable Goal run: {error}"),
                        })?;
                    settle_goal_surface_mutation_on_start(coordinator, &runtime, &mutation)?;
                }
            }
        }
    }
    Ok(())
}

fn reconcile_interrupted_workflow_surfaces_on_start(
    coordinator: &mut surface::RuntimeCommitCoordinator<'static, surface::JsonlSurfaceCommitLedger>,
) -> Result<(), RuntimeHostError> {
    loop {
        let snapshot = coordinator.state().snapshot().clone();
        let Some((task, workflow)) = snapshot.tasks.iter().find_map(|task| {
            let background_fence = task.background_fence.as_ref()?;
            let operation_terminal = snapshot.operation_history.iter().any(|operation| {
                operation.operation_id == background_fence.operation_fence.operation_id
                    && operation.terminal.is_some()
            });
            if !operation_terminal
                || !matches!(
                    task.status,
                    surface::SurfaceTaskStatus::Queued
                        | surface::SurfaceTaskStatus::Running
                        | surface::SurfaceTaskStatus::Paused
                        | surface::SurfaceTaskStatus::Stopping
                        | surface::SurfaceTaskStatus::ApprovalRequired
                )
            {
                return None;
            }
            let workflow = snapshot.workflows.iter().find(|workflow| {
                workflow.task_id == task.task_id
                    && matches!(
                        workflow.status,
                        surface::SurfaceWorkflowStatus::Queued
                            | surface::SurfaceWorkflowStatus::Running
                            | surface::SurfaceWorkflowStatus::Paused
                            | surface::SurfaceWorkflowStatus::Stopping
                            | surface::SurfaceWorkflowStatus::AsyncLaunched
                    )
            })?;
            Some((task.clone(), workflow.clone()))
        }) else {
            return Ok(());
        };

        let next_task_revision =
            surface::TaskRevision::try_new(task.revision.get().checked_add(1).ok_or_else(
                || RuntimeHostError::ThreadStartFailed {
                    message: "recovered workflow task revision exhausted".to_string(),
                },
            )?)
            .map_err(|_| RuntimeHostError::ThreadStartFailed {
                message: "recovered workflow task revision is invalid".to_string(),
            })?;
        let stopping_revision = if workflow.status == surface::SurfaceWorkflowStatus::Stopping {
            workflow.revision
        } else {
            surface::WorkflowRevision::try_new(workflow.revision.get().checked_add(1).ok_or_else(
                || RuntimeHostError::ThreadStartFailed {
                    message: "recovered workflow stopping revision exhausted".to_string(),
                },
            )?)
            .map_err(|_| RuntimeHostError::ThreadStartFailed {
                message: "recovered workflow stopping revision is invalid".to_string(),
            })?
        };
        let stopped_revision =
            surface::WorkflowRevision::try_new(stopping_revision.get().checked_add(1).ok_or_else(
                || RuntimeHostError::ThreadStartFailed {
                    message: "recovered workflow stopped revision exhausted".to_string(),
                },
            )?)
            .map_err(|_| RuntimeHostError::ThreadStartFailed {
                message: "recovered workflow stopped revision is invalid".to_string(),
            })?;
        let result_revision =
            surface::WorkflowRevision::try_new(stopped_revision.get().checked_add(1).ok_or_else(
                || RuntimeHostError::ThreadStartFailed {
                    message: "recovered workflow result revision exhausted".to_string(),
                },
            )?)
            .map_err(|_| RuntimeHostError::ThreadStartFailed {
                message: "recovered workflow result revision is invalid".to_string(),
            })?;
        let reason =
            surface::DisplayText::new("Workflow interrupted by runtime owner restart".to_string());
        let mut events = vec![(
            surface::SurfaceScope::Thread,
            surface::SurfaceEvent::Task(surface::TaskPatch::StatusChanged {
                task_id: task.task_id,
                expected_revision: task.revision,
                next_revision: next_task_revision,
                status: surface::SurfaceTaskStatus::Stopped,
                completed_at: Some(surface::UnixMillis::new(
                    chrono::Utc::now().timestamp_millis(),
                )),
                result: Some(reason.clone()),
                error: None,
            }),
        )];
        if workflow.status != surface::SurfaceWorkflowStatus::Stopping {
            events.push((
                surface::SurfaceScope::Thread,
                surface::SurfaceEvent::Workflow(surface::WorkflowPatch::Stopping {
                    fence: surface::SurfaceWorkflowFence {
                        workflow_run_id: workflow.workflow_run_id.clone(),
                        workflow_revision: workflow.revision,
                        parent: workflow.parent.clone(),
                    },
                    next_revision: stopping_revision,
                    reason: reason.clone(),
                }),
            ));
        }
        events.extend([
            (
                surface::SurfaceScope::Thread,
                surface::SurfaceEvent::Workflow(surface::WorkflowPatch::Stopped {
                    fence: surface::SurfaceWorkflowFence {
                        workflow_run_id: workflow.workflow_run_id.clone(),
                        workflow_revision: stopping_revision,
                        parent: workflow.parent.clone(),
                    },
                    next_revision: stopped_revision,
                    reason: reason.clone(),
                }),
            ),
            (
                surface::SurfaceScope::Thread,
                surface::SurfaceEvent::Workflow(surface::WorkflowPatch::ResultReady {
                    fence: surface::SurfaceWorkflowFence {
                        workflow_run_id: workflow.workflow_run_id.clone(),
                        workflow_revision: stopped_revision,
                        parent: workflow.parent,
                    },
                    next_revision: result_revision,
                    result: surface::SurfaceWorkflowResult {
                        result_id: surface::SurfaceWorkflowResultId::try_new(format!(
                            "workflow-result-{}",
                            workflow.workflow_run_id.as_str()
                        ))
                        .map_err(|_| {
                            RuntimeHostError::ThreadStartFailed {
                                message: "recovered workflow result identity is invalid"
                                    .to_string(),
                            }
                        })?,
                        tool_use_id: None,
                        status: surface::SurfaceWorkflowResultStatus::Failed,
                        content: reason,
                        acknowledged_by_operation: None,
                    },
                }),
            ),
        ]);
        let batch = runtime_surface_event_batch(&snapshot, events, None);
        coordinator.commit_actor_batch(&batch).map_err(|error| {
            RuntimeHostError::ThreadStartFailed {
                message: format!(
                    "failed to reconcile interrupted typed workflow surface: {error:?}"
                ),
            }
        })?;
    }
}

fn reconcile_durable_workflow_outcomes_on_start(
    thread: &RuntimeThread,
    config: &RunConfig,
    coordinator: &mut surface::RuntimeCommitCoordinator<'static, surface::JsonlSurfaceCommitLedger>,
) -> Result<(), RuntimeHostError> {
    let cwd = config
        .cwd
        .clone()
        .or_else(|| std::env::current_dir().ok())
        .ok_or_else(|| RuntimeHostError::ThreadStartFailed {
            message: "workflow recovery requires a working directory".to_string(),
        })?;
    let task_registry = thread.session().task_registry().clone();
    let session_dir = task_registry.workflow_session_dir(&cwd).map_err(|error| {
        RuntimeHostError::ThreadStartFailed {
            message: format!("failed to resolve workflow runtime storage: {error}"),
        }
    })?;
    let runner = WorkflowRunner::new(config.clone(), task_registry, session_dir);
    loop {
        let snapshot = coordinator.state().snapshot().clone();
        let mut durable_outcome = None;
        for task in &snapshot.tasks {
            let Some(background_fence) = task.background_fence.as_ref() else {
                continue;
            };
            if snapshot.operation_history.iter().any(|operation| {
                operation.operation_id == background_fence.operation_fence.operation_id
                    && operation.terminal.is_some()
            }) || !matches!(
                task.status,
                surface::SurfaceTaskStatus::Queued
                    | surface::SurfaceTaskStatus::Running
                    | surface::SurfaceTaskStatus::Paused
                    | surface::SurfaceTaskStatus::Stopping
                    | surface::SurfaceTaskStatus::ApprovalRequired
            ) {
                continue;
            }
            let Some(workflow) = snapshot.workflows.iter().find(|workflow| {
                workflow.task_id == task.task_id
                    && matches!(
                        workflow.status,
                        surface::SurfaceWorkflowStatus::Running
                            | surface::SurfaceWorkflowStatus::Stopping
                            | surface::SurfaceWorkflowStatus::AsyncLaunched
                    )
            }) else {
                continue;
            };
            let record = runner
                .reconcile_durable_terminal_outcome(
                    task.task_id.as_str(),
                    workflow.workflow_run_id.as_str(),
                )
                .map_err(|error| RuntimeHostError::ThreadStartFailed {
                    message: format!(
                        "failed to reconcile durable workflow outcome stores: {error}"
                    ),
                })?;
            if let Some(record) = record {
                durable_outcome = Some((task.clone(), workflow.clone(), record));
                break;
            }
            runner
                .settle_runtime_restart_without_durable_outcome(
                    task.task_id.as_str(),
                    workflow.workflow_run_id.as_str(),
                )
                .map_err(|error| RuntimeHostError::ThreadStartFailed {
                    message: format!("failed to settle interrupted workflow persistence: {error}"),
                })?;
        }
        let Some((task, workflow, record)) = durable_outcome else {
            return Ok(());
        };

        let background_fence = task
            .background_fence
            .clone()
            .expect("typed workflow task owns a background fence");
        let operation_id = background_fence.operation_fence.operation_id.clone();
        let next_task_revision =
            surface::TaskRevision::try_new(task.revision.get().checked_add(1).ok_or_else(
                || RuntimeHostError::ThreadStartFailed {
                    message: "durable workflow task revision exhausted".to_string(),
                },
            )?)
            .map_err(|_| RuntimeHostError::ThreadStartFailed {
                message: "durable workflow task revision is invalid".to_string(),
            })?;
        let next_workflow_revision =
            surface::WorkflowRevision::try_new(workflow.revision.get().checked_add(1).ok_or_else(
                || RuntimeHostError::ThreadStartFailed {
                    message: "durable workflow revision exhausted".to_string(),
                },
            )?)
            .map_err(|_| RuntimeHostError::ThreadStartFailed {
                message: "durable workflow revision is invalid".to_string(),
            })?;
        let second_workflow_revision = surface::WorkflowRevision::try_new(
            next_workflow_revision.get().checked_add(1).ok_or_else(|| {
                RuntimeHostError::ThreadStartFailed {
                    message: "durable workflow second revision exhausted".to_string(),
                }
            })?,
        )
        .map_err(|_| RuntimeHostError::ThreadStartFailed {
            message: "durable workflow second revision is invalid".to_string(),
        })?;
        let workflow_fence = surface::SurfaceWorkflowFence {
            workflow_run_id: workflow.workflow_run_id.clone(),
            workflow_revision: workflow.revision,
            parent: workflow.parent.clone(),
        };
        let content = surface::DisplayText::new(
            record
                .result
                .clone()
                .or_else(|| record.error.clone())
                .unwrap_or_else(|| "Workflow stopped".to_string()),
        );
        let usage = surface_usage_totals(record.usage.clone().unwrap_or_default());
        let diagnostic =
            surface::SafeDiagnosticText::try_new("background workflow failed before projection")
                .expect("fixed diagnostic is bounded");
        let projected_status = if workflow.status == surface::SurfaceWorkflowStatus::Stopping {
            TaskStatus::Stopped
        } else {
            record.status
        };
        let (
            task_status,
            workflow_patches,
            terminal_workflow_revision,
            result_status,
            stop_reason,
            terminal,
        ) = match projected_status {
            TaskStatus::Completed => (
                surface::SurfaceTaskStatus::Completed,
                vec![surface::WorkflowPatch::Completed {
                    fence: workflow_fence,
                    next_revision: next_workflow_revision,
                }],
                next_workflow_revision,
                surface::SurfaceWorkflowResultStatus::Success,
                surface::GenerationStopReason::Completed {
                    status: surface::GenerationCompletionStatus::Success,
                },
                surface::OperationTerminal::Succeeded {
                    usage: usage.clone(),
                },
            ),
            TaskStatus::Stopped => {
                let (patches, terminal_revision) =
                    if workflow.status == surface::SurfaceWorkflowStatus::Stopping {
                        (
                            vec![surface::WorkflowPatch::Stopped {
                                fence: workflow_fence,
                                next_revision: next_workflow_revision,
                                reason: content.clone(),
                            }],
                            next_workflow_revision,
                        )
                    } else {
                        (
                            vec![
                                surface::WorkflowPatch::Stopping {
                                    fence: workflow_fence,
                                    next_revision: next_workflow_revision,
                                    reason: content.clone(),
                                },
                                surface::WorkflowPatch::Stopped {
                                    fence: surface::SurfaceWorkflowFence {
                                        workflow_run_id: workflow.workflow_run_id.clone(),
                                        workflow_revision: next_workflow_revision,
                                        parent: workflow.parent.clone(),
                                    },
                                    next_revision: second_workflow_revision,
                                    reason: content.clone(),
                                },
                            ],
                            second_workflow_revision,
                        )
                    };
                (
                    surface::SurfaceTaskStatus::Stopped,
                    patches,
                    terminal_revision,
                    surface::SurfaceWorkflowResultStatus::Failed,
                    surface::GenerationStopReason::Cancelled {
                        cause: surface::TerminalizationCause::UserCancel,
                    },
                    surface::OperationTerminal::Cancelled {
                        reason: surface::CancelReason::User,
                    },
                )
            }
            TaskStatus::Cancelled => (
                surface::SurfaceTaskStatus::Cancelled,
                vec![surface::WorkflowPatch::Cancelled {
                    fence: workflow_fence,
                    next_revision: next_workflow_revision,
                    reason: content.clone(),
                }],
                next_workflow_revision,
                surface::SurfaceWorkflowResultStatus::Failed,
                surface::GenerationStopReason::Cancelled {
                    cause: surface::TerminalizationCause::UserCancel,
                },
                surface::OperationTerminal::Cancelled {
                    reason: surface::CancelReason::User,
                },
            ),
            TaskStatus::Failed => (
                surface::SurfaceTaskStatus::Failed,
                vec![surface::WorkflowPatch::Failed {
                    fence: workflow_fence,
                    next_revision: next_workflow_revision,
                    error: content.clone(),
                }],
                next_workflow_revision,
                surface::SurfaceWorkflowResultStatus::Failed,
                surface::GenerationStopReason::ExecutionFailed {
                    class: surface::GenerationExecutionFailureClass::Workflow,
                    message: diagnostic.clone(),
                },
                surface::OperationTerminal::Failed {
                    class: surface::FailureClass::Workflow,
                    message: diagnostic,
                },
            ),
            _ => unreachable!("candidate durable workflow outcome is terminal"),
        };
        let result_revision = surface::WorkflowRevision::try_new(
            terminal_workflow_revision
                .get()
                .checked_add(1)
                .ok_or_else(|| RuntimeHostError::ThreadStartFailed {
                    message: "durable workflow result revision exhausted".to_string(),
                })?,
        )
        .map_err(|_| RuntimeHostError::ThreadStartFailed {
            message: "durable workflow result revision is invalid".to_string(),
        })?;
        let finalize_intent_id =
            surface::SurfaceFinalizeIntentId::try_from_bytes(*uuid::Uuid::now_v7().as_bytes())
                .expect("generated UUID is v7");
        let terminal_commit_id =
            surface::SurfaceCommitId::try_from_bytes(*uuid::Uuid::now_v7().as_bytes())
                .expect("generated UUID is v7");
        let mut completion_events = vec![(
            surface::SurfaceScope::Thread,
            surface::SurfaceEvent::Task(surface::TaskPatch::StatusChanged {
                task_id: task.task_id,
                expected_revision: task.revision,
                next_revision: next_task_revision,
                status: task_status,
                completed_at: record.completed_at_ms.map(surface::UnixMillis::new),
                result: record.result.map(surface::DisplayText::new),
                error: record.error.map(surface::DisplayText::new),
            }),
        )];
        completion_events.extend(workflow_patches.into_iter().map(|patch| {
            (
                surface::SurfaceScope::Thread,
                surface::SurfaceEvent::Workflow(patch),
            )
        }));
        completion_events.extend([
            (
                surface::SurfaceScope::Thread,
                surface::SurfaceEvent::Workflow(surface::WorkflowPatch::ResultReady {
                    fence: surface::SurfaceWorkflowFence {
                        workflow_run_id: workflow.workflow_run_id.clone(),
                        workflow_revision: terminal_workflow_revision,
                        parent: workflow.parent.clone(),
                    },
                    next_revision: result_revision,
                    result: surface::SurfaceWorkflowResult {
                        result_id: surface::SurfaceWorkflowResultId::try_new(format!(
                            "workflow-result-{}",
                            workflow.workflow_run_id.as_str()
                        ))
                        .map_err(|_| {
                            RuntimeHostError::ThreadStartFailed {
                                message: "durable workflow result identity is invalid".to_string(),
                            }
                        })?,
                        tool_use_id: None,
                        status: result_status,
                        content,
                        acknowledged_by_operation: None,
                    },
                }),
            ),
            (
                surface::SurfaceScope::Background {
                    fence: background_fence.clone(),
                },
                surface::SurfaceEvent::Operation(surface::OperationPatch::GenerationStopped {
                    fence: background_fence.operation_fence.clone(),
                    reason: stop_reason.clone(),
                    usage_delta: usage.clone(),
                }),
            ),
            (
                surface::SurfaceScope::Background {
                    fence: background_fence.clone(),
                },
                surface::SurfaceEvent::Operation(surface::OperationPatch::FinalizationStarted {
                    operation_id: operation_id.clone(),
                    finalize_intent_id: finalize_intent_id.clone(),
                    terminal_commit_id: terminal_commit_id.clone(),
                    selected_cause: surface::OperationFinalizationCause::GenerationStop(
                        stop_reason,
                    ),
                    suspended_cause: None,
                    expected_settlements: Vec::new(),
                }),
            ),
        ]);
        let completion_batch = runtime_surface_event_batch(&snapshot, completion_events, None);
        coordinator
            .commit_workflow_background_stop_batch(
                background_fence.clone(),
                operation_id.clone(),
                finalize_intent_id.clone(),
                &completion_batch,
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!(
                    "failed to project durable workflow completion during recovery: {error:?}"
                ),
            })?;
        let terminal_batch = runtime_surface_event_batch(
            coordinator.state().snapshot(),
            vec![(
                surface::SurfaceScope::Background {
                    fence: background_fence,
                },
                surface::SurfaceEvent::Operation(surface::OperationPatch::Terminal {
                    record: surface::OperationTerminalRecord {
                        operation_id: operation_id.clone(),
                        finalize_intent_id: finalize_intent_id.clone(),
                        terminal,
                        usage,
                        source_diagnostic_digest: None,
                        settlement_receipts: Vec::new(),
                        committed_at: surface::UnixMillis::new(
                            chrono::Utc::now().timestamp_millis(),
                        ),
                    },
                }),
            )],
            Some(terminal_commit_id.clone()),
        );
        coordinator
            .commit_finalizer_batch(operation_id, finalize_intent_id, &terminal_batch)
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!(
                    "failed to terminalize durable workflow completion during recovery: {error:?}"
                ),
            })?;
    }
}

fn reconcile_durable_provider_outcomes_on_start(
    thread: &RuntimeThread,
    coordinator: &mut surface::RuntimeCommitCoordinator<'static, surface::JsonlSurfaceCommitLedger>,
    host_incarnation: &surface::HostIncarnation,
) -> Result<(), RuntimeHostError> {
    let task_registry = thread.session().task_registry();
    loop {
        let snapshot = coordinator.state().snapshot().clone();
        let durable = snapshot.tasks.iter().find_map(|task| {
            if task.task_type != surface::SurfaceTaskType::MainSession
                || !matches!(
                    task.status,
                    surface::SurfaceTaskStatus::Queued
                        | surface::SurfaceTaskStatus::Running
                        | surface::SurfaceTaskStatus::Paused
                        | surface::SurfaceTaskStatus::Stopping
                        | surface::SurfaceTaskStatus::ApprovalRequired
                )
                || snapshot
                    .workflows
                    .iter()
                    .any(|workflow| workflow.task_id == task.task_id)
            {
                return None;
            }
            let parent_operation = task.parent_operation.as_ref()?;
            let background = snapshot.background_operations.iter().find(|background| {
                &background.operation_id == parent_operation
                    && background.task_id.as_ref() == Some(&task.task_id)
            })?;
            let background_fence = &background.fence;
            let operation = snapshot.operation_history.iter().find(|operation| {
                operation.operation_id == *parent_operation
                    && operation.terminal.is_none()
                    && operation.finalization.is_none()
            })?;
            let outcome = task_registry.typed_provider_outcome(task.task_id.as_str())?;
            if !matches!(
                outcome.status,
                TaskStatus::Completed
                    | TaskStatus::ApprovalRequired
                    | TaskStatus::Failed
                    | TaskStatus::Stopped
                    | TaskStatus::Cancelled
            ) {
                return None;
            }
            Some((
                task.clone(),
                background_fence.clone(),
                operation.clone(),
                outcome,
            ))
        });
        let Some((task, background_fence, operation, outcome)) = durable else {
            return Ok(());
        };
        let operation_id = operation.operation_id.clone();
        if outcome.status == TaskStatus::ApprovalRequired {
            if matches!(
                operation.phase,
                surface::OperationPhase::Suspended {
                    cause: surface::SuspensionCause::ProviderSuspended { .. }
                }
            ) {
                mirror_recovered_typed_provider_outcome(
                    &task_registry,
                    task.task_id.as_str(),
                    &outcome,
                    false,
                );
                task_registry
                    .clear_typed_provider_outcome(task.task_id.as_str())
                    .map_err(|error| RuntimeHostError::ThreadStartFailed {
                        message: format!(
                            "failed to clear recovered background approval outcome for {}: {error}",
                            task.task_id.as_str()
                        ),
                    })?;
                continue;
            }
            let response =
                outcome
                    .response
                    .as_ref()
                    .ok_or_else(|| RuntimeHostError::ThreadStartFailed {
                        message: "recovered background approval lost its provider response"
                            .to_string(),
                    })?;
            let next_task_revision =
                surface::TaskRevision::try_new(task.revision.get().checked_add(1).ok_or_else(
                    || RuntimeHostError::ThreadStartFailed {
                        message:
                            "recovered background approval task revision exhausted".to_string(),
                    },
                )?)
                .map_err(|_| RuntimeHostError::ThreadStartFailed {
                    message: "recovered background approval task revision is invalid".to_string(),
                })?;
            let mut suspension_events = ThreadActor::background_provider_response_events(
                &snapshot,
                &background_fence,
                response,
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!(
                    "failed to rebuild recovered background approval response: {error}"
                ),
            })?;
            let tool = suspension_events
                .iter()
                .find_map(|(_, event)| match event {
                    surface::SurfaceEvent::Tool(surface::ToolPatch::Requested { request }) => {
                        Some(request.clone())
                    }
                    _ => None,
                })
                .ok_or_else(|| RuntimeHostError::ThreadStartFailed {
                    message: "recovered background approval has no tool request".to_string(),
                })?;
            let authority = ThreadActor::surface_authority_for_tool(
                &snapshot,
                &background_fence.operation_fence,
                &tool,
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("recovered background approval authority is invalid: {error}"),
            })?;
            let interaction_id =
                surface::SurfaceInteractionId::try_from_bytes(*uuid::Uuid::now_v7().as_bytes())
                    .expect("generated UUID is v7");
            let revision = surface::InteractionRevision::try_new(1).expect("one is valid");
            let route_epoch = surface::ResponseRouteEpoch::try_new(1).expect("one is valid");
            let request = surface::SurfaceInteractionRequest::BackgroundApproval {
                task: surface::SurfaceTaskFence {
                    task_id: task.task_id.clone(),
                    task_revision: next_task_revision,
                    background_owner: Some(background_fence.clone()),
                },
                tool,
                authority,
            };
            let recovery_disposition =
                surface::InteractionUnavailableDisposition::AwaitCapableAttachment {
                    deadline: surface::InteractionExpiryDeadline {
                        issuing_host_incarnation: host_incarnation.clone(),
                        expires_at: surface::MonotonicInstant {
                            clock_id: surface::HostMonotonicClockId::try_from_bytes(
                                *uuid::Uuid::now_v7().as_bytes(),
                            )
                            .expect("generated UUID is v7"),
                            tick: surface::MonotonicTick::new(u64::MAX),
                        },
                        observed_expires_at: None,
                    },
                };
            suspension_events.extend([
                (
                    surface::SurfaceScope::Thread,
                    surface::SurfaceEvent::Task(surface::TaskPatch::StatusChanged {
                        task_id: task.task_id.clone(),
                        expected_revision: task.revision,
                        next_revision: next_task_revision,
                        status: surface::SurfaceTaskStatus::ApprovalRequired,
                        completed_at: None,
                        result: None,
                        error: None,
                    }),
                ),
                (
                    surface::SurfaceScope::Background {
                        fence: background_fence.clone(),
                    },
                    surface::SurfaceEvent::Operation(surface::OperationPatch::GenerationStopped {
                        fence: background_fence.operation_fence.clone(),
                        reason: surface::GenerationStopReason::ProviderSuspended,
                        usage_delta: surface_usage_totals(outcome.usage.unwrap_or_default()),
                    }),
                ),
                (
                    surface::SurfaceScope::Background {
                        fence: background_fence.clone(),
                    },
                    surface::SurfaceEvent::Interaction(surface::InteractionPatch::Requested {
                        interaction: surface::SurfaceInteractionView {
                            interaction_id,
                            revision,
                            fence: background_fence.operation_fence.clone(),
                            kind: surface::SurfaceInteractionKind::BackgroundApproval,
                            request,
                            route: surface::SurfaceInteractionRoute::Unassigned {
                                epoch: route_epoch,
                            },
                            lifecycle: surface::SurfaceInteractionLifecycle::Requested,
                            recovery_disposition,
                        },
                    }),
                ),
                (
                    surface::SurfaceScope::Background {
                        fence: background_fence.clone(),
                    },
                    surface::SurfaceEvent::Operation(surface::OperationPatch::Suspended {
                        operation_id: operation_id.clone(),
                        cause: surface::SuspensionCause::ProviderSuspended {
                            generation_id: background_fence.operation_fence.generation_id,
                        },
                    }),
                ),
            ]);
            let suspension_batch = runtime_surface_event_batch(&snapshot, suspension_events, None);
            coordinator
                .commit_provider_background_suspend_batch(background_fence, &suspension_batch)
                .map_err(|error| RuntimeHostError::ThreadStartFailed {
                    message: format!(
                        "failed to recover durable background approval suspension: {error:?}"
                    ),
                })?;
            mirror_recovered_typed_provider_outcome(
                &task_registry,
                task.task_id.as_str(),
                &outcome,
                false,
            );
            task_registry
                .clear_typed_provider_outcome(task.task_id.as_str())
                .map_err(|error| RuntimeHostError::ThreadStartFailed {
                    message: format!(
                        "failed to clear recovered background approval outcome for {}: {error}",
                        task.task_id.as_str()
                    ),
                })?;
            continue;
        }
        let committed_user_cancel = matches!(
            &operation.pending_control,
            Some(surface::PendingControlIntent::Terminalize {
                operation_id: control_operation,
                cause: surface::TerminalizationCause::UserCancel,
            }) if control_operation == &operation_id
        );
        let usage = surface_usage_totals(outcome.usage.unwrap_or_default());
        let failure_message =
            surface::SafeDiagnosticText::try_new("background provider failed before projection")
                .expect("fixed diagnostic is bounded");
        let approval_message =
            surface::SafeDiagnosticText::try_new("background provider requires approval")
                .expect("fixed diagnostic is bounded");
        let (task_status, stop_reason, terminal) = if committed_user_cancel {
            (
                surface::SurfaceTaskStatus::Cancelled,
                surface::GenerationStopReason::Cancelled {
                    cause: surface::TerminalizationCause::UserCancel,
                },
                surface::OperationTerminal::Cancelled {
                    reason: surface::CancelReason::User,
                },
            )
        } else {
            match outcome.status {
                TaskStatus::Completed => (
                    surface::SurfaceTaskStatus::Completed,
                    surface::GenerationStopReason::Completed {
                        status: surface::GenerationCompletionStatus::Success,
                    },
                    surface::OperationTerminal::Succeeded {
                        usage: usage.clone(),
                    },
                ),
                TaskStatus::ApprovalRequired => (
                    surface::SurfaceTaskStatus::ApprovalRequired,
                    surface::GenerationStopReason::ExecutionFailed {
                        class: surface::GenerationExecutionFailureClass::LegacyApprovalRequired,
                        message: approval_message.clone(),
                    },
                    surface::OperationTerminal::Failed {
                        class: surface::FailureClass::LegacyApprovalRequired,
                        message: approval_message,
                    },
                ),
                TaskStatus::Stopped | TaskStatus::Cancelled => (
                    if outcome.status == TaskStatus::Stopped {
                        surface::SurfaceTaskStatus::Stopped
                    } else {
                        surface::SurfaceTaskStatus::Cancelled
                    },
                    surface::GenerationStopReason::Cancelled {
                        cause: surface::TerminalizationCause::UserCancel,
                    },
                    surface::OperationTerminal::Cancelled {
                        reason: surface::CancelReason::User,
                    },
                ),
                TaskStatus::Failed => (
                    surface::SurfaceTaskStatus::Failed,
                    surface::GenerationStopReason::ExecutionFailed {
                        class: surface::GenerationExecutionFailureClass::RuntimeInvariant,
                        message: failure_message.clone(),
                    },
                    surface::OperationTerminal::Failed {
                        class: surface::FailureClass::RuntimeInvariant,
                        message: failure_message,
                    },
                ),
                _ => unreachable!("candidate durable provider outcome is terminal"),
            }
        };
        let next_task_revision =
            surface::TaskRevision::try_new(task.revision.get().checked_add(1).ok_or_else(
                || RuntimeHostError::ThreadStartFailed {
                    message: "durable provider task revision exhausted".to_string(),
                },
            )?)
            .map_err(|_| RuntimeHostError::ThreadStartFailed {
                message: "durable provider task revision is invalid".to_string(),
            })?;
        let finalize_intent_id =
            surface::SurfaceFinalizeIntentId::try_from_bytes(*uuid::Uuid::now_v7().as_bytes())
                .expect("generated UUID is v7");
        let terminal_commit_id =
            surface::SurfaceCommitId::try_from_bytes(*uuid::Uuid::now_v7().as_bytes())
                .expect("generated UUID is v7");
        let mut completion_events = outcome
            .response
            .as_ref()
            .map(|response| {
                ThreadActor::background_provider_response_events(
                    &snapshot,
                    &background_fence,
                    response,
                )
            })
            .transpose()
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!(
                    "failed to rebuild durable provider response during recovery: {error}"
                ),
            })?
            .unwrap_or_default();
        completion_events.extend([
            (
                surface::SurfaceScope::Thread,
                surface::SurfaceEvent::Task(surface::TaskPatch::StatusChanged {
                    task_id: task.task_id.clone(),
                    expected_revision: task.revision,
                    next_revision: next_task_revision,
                    status: task_status,
                    completed_at: Some(surface::UnixMillis::new(outcome.completed_at_ms)),
                    result: if committed_user_cancel {
                        Some(surface::DisplayText::new("Background turn cancelled"))
                    } else if outcome.status == TaskStatus::Completed {
                        Some(surface::DisplayText::new("success"))
                    } else {
                        None
                    },
                    error: if committed_user_cancel {
                        None
                    } else {
                        outcome.error.clone().map(surface::DisplayText::new)
                    },
                }),
            ),
            (
                surface::SurfaceScope::Background {
                    fence: background_fence.clone(),
                },
                surface::SurfaceEvent::Operation(surface::OperationPatch::GenerationStopped {
                    fence: background_fence.operation_fence.clone(),
                    reason: stop_reason.clone(),
                    usage_delta: usage.clone(),
                }),
            ),
            (
                surface::SurfaceScope::Background {
                    fence: background_fence.clone(),
                },
                surface::SurfaceEvent::Operation(surface::OperationPatch::FinalizationStarted {
                    operation_id: operation_id.clone(),
                    finalize_intent_id: finalize_intent_id.clone(),
                    terminal_commit_id: terminal_commit_id.clone(),
                    selected_cause: surface::OperationFinalizationCause::GenerationStop(
                        stop_reason,
                    ),
                    suspended_cause: None,
                    expected_settlements: Vec::new(),
                }),
            ),
        ]);
        let completion_batch = runtime_surface_event_batch(&snapshot, completion_events, None);
        coordinator
            .commit_provider_background_stop_batch(
                background_fence.clone(),
                operation_id.clone(),
                finalize_intent_id.clone(),
                &completion_batch,
            )
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!(
                    "failed to project durable provider completion during recovery: {error:?}"
                ),
            })?;
        let terminal_batch = runtime_surface_event_batch(
            coordinator.state().snapshot(),
            vec![(
                surface::SurfaceScope::Background {
                    fence: background_fence,
                },
                surface::SurfaceEvent::Operation(surface::OperationPatch::Terminal {
                    record: surface::OperationTerminalRecord {
                        operation_id: operation_id.clone(),
                        finalize_intent_id: finalize_intent_id.clone(),
                        terminal,
                        usage,
                        source_diagnostic_digest: None,
                        settlement_receipts: Vec::new(),
                        committed_at: surface::UnixMillis::new(
                            chrono::Utc::now().timestamp_millis(),
                        ),
                    },
                }),
            )],
            Some(terminal_commit_id),
        );
        coordinator
            .commit_finalizer_batch(operation_id, finalize_intent_id, &terminal_batch)
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!(
                    "failed to terminalize durable provider completion during recovery: {error:?}"
                ),
            })?;
        mirror_recovered_typed_provider_outcome(
            &task_registry,
            task.task_id.as_str(),
            &outcome,
            committed_user_cancel,
        );
        task_registry
            .clear_typed_provider_outcome(task.task_id.as_str())
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!(
                    "failed to clear recovered typed provider outcome for {}: {error}",
                    task.task_id.as_str()
                ),
            })?;
    }
}

fn mirror_recovered_typed_provider_outcome(
    task_registry: &TaskRegistry,
    task_id: &str,
    outcome: &DurableTypedProviderOutcome,
    committed_user_cancel: bool,
) {
    let result = if committed_user_cancel {
        task_registry.stop_with_usage(task_id, "cancelled".to_string(), outcome.usage)
    } else {
        match outcome.status {
            TaskStatus::Completed => task_registry
                .apply_main_session_terminal_update(
                    task_id,
                    MainSessionTerminalUpdate::Completed {
                        result: "success".to_string(),
                    },
                    outcome.usage,
                )
                .map(|_| ()),
            TaskStatus::ApprovalRequired => match outcome.response.clone() {
                Some(response) => task_registry
                    .approval_required_for_pending_provider_response_with_usage(
                        task_id,
                        "approval_required".to_string(),
                        response,
                        outcome.usage,
                    ),
                None => Err("recovered approval outcome lost its provider response".to_string()),
            },
            TaskStatus::Stopped | TaskStatus::Cancelled => {
                task_registry.stop_with_usage(task_id, "cancelled".to_string(), outcome.usage)
            }
            TaskStatus::Failed => task_registry
                .apply_main_session_terminal_update(
                    task_id,
                    MainSessionTerminalUpdate::Failed {
                        error: outcome
                            .error
                            .clone()
                            .unwrap_or_else(|| "background provider failed".to_string()),
                    },
                    outcome.usage,
                )
                .map(|_| ()),
            TaskStatus::Queued
            | TaskStatus::Running
            | TaskStatus::Paused
            | TaskStatus::Stopping => Err("recovered provider outcome is not terminal".to_string()),
        }
    };
    if let Err(error) = result {
        eprintln!("orca: recovered typed provider outcome could not refresh task mirror: {error}");
    }
}

fn reconcile_terminal_main_session_tasks(
    task_registry: &TaskRegistry,
    coordinator: &mut surface::RuntimeCommitCoordinator<'static, surface::JsonlSurfaceCommitLedger>,
) -> Result<(), RuntimeHostError> {
    loop {
        let snapshot = coordinator.state().snapshot().clone();
        let Some((task, terminal)) = snapshot.tasks.iter().find_map(|task| {
            if task.task_type != surface::SurfaceTaskType::MainSession
                || !matches!(
                    task.status,
                    surface::SurfaceTaskStatus::Queued
                        | surface::SurfaceTaskStatus::Running
                        | surface::SurfaceTaskStatus::Paused
                        | surface::SurfaceTaskStatus::Stopping
                        | surface::SurfaceTaskStatus::ApprovalRequired
                )
            {
                return None;
            }
            let operation_id = task.parent_operation.as_ref()?;
            let terminal = snapshot
                .operation_history
                .iter()
                .find(|operation| &operation.operation_id == operation_id)?
                .terminal
                .as_ref()?;
            if task.status == surface::SurfaceTaskStatus::ApprovalRequired
                && matches!(
                    terminal.terminal,
                    surface::OperationTerminal::Failed {
                        class: surface::FailureClass::LegacyApprovalRequired,
                        ..
                    }
                )
            {
                return None;
            }
            Some((task.clone(), terminal.clone()))
        }) else {
            return Ok(());
        };
        let next_revision =
            surface::TaskRevision::try_new(task.revision.get().checked_add(1).ok_or_else(
                || RuntimeHostError::ThreadStartFailed {
                    message: "recovered main-session task revision exhausted".to_string(),
                },
            )?)
            .map_err(|_| RuntimeHostError::ThreadStartFailed {
                message: "recovered main-session task revision is invalid".to_string(),
            })?;
        let (status, result, error) = match &terminal.terminal {
            surface::OperationTerminal::Succeeded { .. } => (
                surface::SurfaceTaskStatus::Completed,
                Some(surface::DisplayText::new("Background turn completed")),
                None,
            ),
            surface::OperationTerminal::Cancelled { .. }
            | surface::OperationTerminal::NotAdmitted { .. } => (
                surface::SurfaceTaskStatus::Cancelled,
                Some(surface::DisplayText::new("Background turn cancelled")),
                None,
            ),
            surface::OperationTerminal::Shutdown { .. } => (
                surface::SurfaceTaskStatus::Stopped,
                Some(surface::DisplayText::new(
                    "Background turn stopped during runtime recovery",
                )),
                None,
            ),
            surface::OperationTerminal::Failed { message, .. } => (
                surface::SurfaceTaskStatus::Failed,
                None,
                Some(surface::DisplayText::new(message.as_str())),
            ),
            surface::OperationTerminal::BudgetExhausted { .. } => (
                surface::SurfaceTaskStatus::Failed,
                None,
                Some(surface::DisplayText::new(
                    "Background turn exhausted its runtime budget",
                )),
            ),
            surface::OperationTerminal::Panicked { message }
            | surface::OperationTerminal::JoinFailed { message } => (
                surface::SurfaceTaskStatus::Failed,
                None,
                Some(surface::DisplayText::new(message.as_str())),
            ),
            surface::OperationTerminal::AbortedByRuntimeRestart { .. } => (
                surface::SurfaceTaskStatus::Stopped,
                Some(surface::DisplayText::new(
                    "Background turn stopped during runtime recovery",
                )),
                None,
            ),
        };
        let batch = runtime_surface_event_batch(
            &snapshot,
            vec![(
                surface::SurfaceScope::Thread,
                surface::SurfaceEvent::Task(surface::TaskPatch::StatusChanged {
                    task_id: task.task_id.clone(),
                    expected_revision: task.revision,
                    next_revision,
                    status,
                    completed_at: Some(surface::UnixMillis::new(
                        chrono::Utc::now().timestamp_millis(),
                    )),
                    result: result.clone(),
                    error: error.clone(),
                }),
            )],
            None,
        );
        let mut committed = None;
        for attempt in 0..SURFACE_SEMANTIC_COMMIT_RETRY_ATTEMPTS {
            match coordinator.commit_actor_batch(&batch) {
                Ok(_) => {
                    committed = Some(Ok(()));
                    break;
                }
                Err(surface::SurfaceCommitError::Ledger(error))
                    if attempt + 1 < SURFACE_SEMANTIC_COMMIT_RETRY_ATTEMPTS
                        && matches!(
                            error,
                            surface::SurfaceLedgerError::AppendFailed
                                | surface::SurfaceLedgerError::PartialAppend
                                | surface::SurfaceLedgerError::CheckpointFailed
                        ) => {}
                Err(error) => {
                    committed = Some(Err(error));
                    break;
                }
            }
        }
        match committed {
            Some(Ok(())) => {}
            Some(Err(error)) => {
                return Err(RuntimeHostError::ThreadStartFailed {
                    message: format!("failed to reconcile terminal main-session task: {error:?}"),
                });
            }
            None => {
                return Err(RuntimeHostError::ThreadStartFailed {
                    message: "terminal main-session task reconciliation exhausted bounded retries"
                        .to_string(),
                });
            }
        }

        let legacy_usage = UsageTotals {
            input_tokens: terminal.usage.input_tokens,
            output_tokens: terminal.usage.output_tokens,
            cache_tokens: terminal.usage.cache_tokens,
            estimated_cost_usd: terminal.usage.estimated_cost_usd_micros as f64 / 1_000_000.0,
        };
        match status {
            surface::SurfaceTaskStatus::Completed => {
                let _ = task_registry.apply_main_session_terminal_update(
                    task.task_id.as_str(),
                    MainSessionTerminalUpdate::Completed {
                        result: result
                            .as_ref()
                            .map(|value| value.as_str().to_string())
                            .unwrap_or_default(),
                    },
                    Some(legacy_usage),
                );
            }
            surface::SurfaceTaskStatus::Failed => {
                let _ = task_registry.apply_main_session_terminal_update(
                    task.task_id.as_str(),
                    MainSessionTerminalUpdate::Failed {
                        error: error
                            .as_ref()
                            .map(|value| value.as_str().to_string())
                            .unwrap_or_else(|| "Background turn failed".to_string()),
                    },
                    Some(legacy_usage),
                );
            }
            surface::SurfaceTaskStatus::Stopped | surface::SurfaceTaskStatus::Cancelled => {
                let _ = task_registry.stop(
                    task.task_id.as_str(),
                    result
                        .as_ref()
                        .map(|value| value.as_str().to_string())
                        .unwrap_or_else(|| "Background turn stopped".to_string()),
                );
            }
            _ => unreachable!("recovery maps only terminal main-session task states"),
        }
    }
}

#[derive(Clone)]
struct PreparedMainSessionTaskTerminalProjection {
    event: (surface::SurfaceScope, surface::SurfaceEvent),
    task_id: surface::SurfaceTaskId,
    status: surface::SurfaceTaskStatus,
    result: Option<surface::DisplayText>,
    error: Option<surface::DisplayText>,
}

fn prepare_main_session_task_terminal_projection(
    snapshot: &surface::SurfaceSnapshot,
    operation_id: &surface::SurfaceOperationId,
    terminal: &surface::OperationTerminalRecord,
) -> Result<Option<PreparedMainSessionTaskTerminalProjection>, RuntimeHostError> {
    let Some(task) = snapshot
        .tasks
        .iter()
        .find(|task| {
            task.task_type == surface::SurfaceTaskType::MainSession
                && task.parent_operation.as_ref() == Some(operation_id)
                && matches!(
                    task.status,
                    surface::SurfaceTaskStatus::Queued
                        | surface::SurfaceTaskStatus::Running
                        | surface::SurfaceTaskStatus::Paused
                        | surface::SurfaceTaskStatus::Stopping
                        | surface::SurfaceTaskStatus::ApprovalRequired
                )
        })
        .cloned()
    else {
        return Ok(None);
    };
    let next_revision =
        surface::TaskRevision::try_new(task.revision.get().checked_add(1).ok_or_else(|| {
            RuntimeHostError::ThreadStartFailed {
                message: "main-session task terminal revision exhausted".to_string(),
            }
        })?)
        .map_err(|_| RuntimeHostError::ThreadStartFailed {
            message: "main-session task terminal revision is invalid".to_string(),
        })?;
    let (status, result, error) = match &terminal.terminal {
        surface::OperationTerminal::Succeeded { .. } => (
            surface::SurfaceTaskStatus::Completed,
            Some(surface::DisplayText::new("Background turn completed")),
            None,
        ),
        surface::OperationTerminal::Cancelled { .. }
        | surface::OperationTerminal::NotAdmitted { .. } => (
            surface::SurfaceTaskStatus::Cancelled,
            Some(surface::DisplayText::new("Background turn cancelled")),
            None,
        ),
        surface::OperationTerminal::Shutdown { .. }
        | surface::OperationTerminal::AbortedByRuntimeRestart { .. } => (
            surface::SurfaceTaskStatus::Stopped,
            Some(surface::DisplayText::new("Background turn stopped")),
            None,
        ),
        surface::OperationTerminal::Failed { message, .. }
        | surface::OperationTerminal::Panicked { message }
        | surface::OperationTerminal::JoinFailed { message } => (
            surface::SurfaceTaskStatus::Failed,
            None,
            Some(surface::DisplayText::new(message.as_str())),
        ),
        surface::OperationTerminal::BudgetExhausted { .. } => (
            surface::SurfaceTaskStatus::Failed,
            None,
            Some(surface::DisplayText::new(
                "Background turn exhausted its runtime budget",
            )),
        ),
    };
    let event = (
        surface::SurfaceScope::Thread,
        surface::SurfaceEvent::Task(surface::TaskPatch::StatusChanged {
            task_id: task.task_id.clone(),
            expected_revision: task.revision,
            next_revision,
            status,
            completed_at: Some(surface::UnixMillis::new(
                chrono::Utc::now().timestamp_millis(),
            )),
            result: result.clone(),
            error: error.clone(),
        }),
    );
    Ok(Some(PreparedMainSessionTaskTerminalProjection {
        event,
        task_id: task.task_id,
        status,
        result,
        error,
    }))
}

fn mirror_main_session_task_terminal_projection(
    task_registry: &TaskRegistry,
    terminal: &surface::OperationTerminalRecord,
    projection: &PreparedMainSessionTaskTerminalProjection,
) {
    let legacy_usage = UsageTotals {
        input_tokens: terminal.usage.input_tokens,
        output_tokens: terminal.usage.output_tokens,
        cache_tokens: terminal.usage.cache_tokens,
        estimated_cost_usd: terminal.usage.estimated_cost_usd_micros as f64 / 1_000_000.0,
    };
    match projection.status {
        surface::SurfaceTaskStatus::Completed => {
            let _ = task_registry.apply_main_session_terminal_update(
                projection.task_id.as_str(),
                MainSessionTerminalUpdate::Completed {
                    result: projection
                        .result
                        .as_ref()
                        .map(|value| value.as_str().to_string())
                        .unwrap_or_default(),
                },
                Some(legacy_usage),
            );
        }
        surface::SurfaceTaskStatus::Failed => {
            let _ = task_registry.apply_main_session_terminal_update(
                projection.task_id.as_str(),
                MainSessionTerminalUpdate::Failed {
                    error: projection
                        .error
                        .as_ref()
                        .map(|value| value.as_str().to_string())
                        .unwrap_or_else(|| "Background turn failed".to_string()),
                },
                Some(legacy_usage),
            );
        }
        surface::SurfaceTaskStatus::Stopped | surface::SurfaceTaskStatus::Cancelled => {
            let _ = task_registry.stop(
                projection.task_id.as_str(),
                projection
                    .result
                    .as_ref()
                    .map(|value| value.as_str().to_string())
                    .unwrap_or_else(|| "Background turn stopped".to_string()),
            );
        }
        _ => unreachable!("terminal projection maps only terminal task states"),
    }
}

fn reconcile_main_session_task_mirror(task_registry: &TaskRegistry, task: &surface::SurfaceTask) {
    if task.task_type != surface::SurfaceTaskType::MainSession {
        return;
    }
    let Some(legacy) = task_registry.get(task.task_id.as_str()) else {
        return;
    };
    if legacy.is_backgrounded != task.backgrounded {
        if let Err(error) = task_registry
            .reconcile_main_session_backgrounded(task.task_id.as_str(), task.backgrounded)
        {
            eprintln!(
                "orca: durable task ownership could not refresh legacy mirror during startup: {error}"
            );
        }
    }
    if matches!(
        legacy.status,
        TaskStatus::Completed | TaskStatus::Failed | TaskStatus::Cancelled | TaskStatus::Stopped
    ) {
        return;
    }
    let usage = task.usage.as_ref().map(|usage| UsageTotals {
        input_tokens: usage.input_tokens,
        output_tokens: usage.output_tokens,
        cache_tokens: usage.cache_tokens,
        estimated_cost_usd: usage.estimated_cost_usd_micros as f64 / 1_000_000.0,
    });
    let result = match task.status {
        surface::SurfaceTaskStatus::Completed => task_registry
            .apply_main_session_terminal_update(
                task.task_id.as_str(),
                MainSessionTerminalUpdate::Completed {
                    result: task
                        .result
                        .as_ref()
                        .map(|value| value.as_str().to_string())
                        .unwrap_or_default(),
                },
                usage,
            )
            .map(|_| ()),
        surface::SurfaceTaskStatus::Failed => task_registry
            .apply_main_session_terminal_update(
                task.task_id.as_str(),
                MainSessionTerminalUpdate::Failed {
                    error: task
                        .error
                        .as_ref()
                        .map(|value| value.as_str().to_string())
                        .unwrap_or_else(|| "Background turn failed".to_string()),
                },
                usage,
            )
            .map(|_| ()),
        surface::SurfaceTaskStatus::Stopped | surface::SurfaceTaskStatus::Cancelled => {
            task_registry.stop(
                task.task_id.as_str(),
                task.result
                    .as_ref()
                    .or(task.error.as_ref())
                    .map(|value| value.as_str().to_string())
                    .unwrap_or_else(|| "Background turn stopped".to_string()),
            )
        }
        surface::SurfaceTaskStatus::Running if legacy.status == TaskStatus::Running => Ok(()),
        surface::SurfaceTaskStatus::Queued
        | surface::SurfaceTaskStatus::Paused
        | surface::SurfaceTaskStatus::Stopping
        | surface::SurfaceTaskStatus::ApprovalRequired
        | surface::SurfaceTaskStatus::Running => Ok(()),
    };
    if let Err(error) = result {
        eprintln!(
            "orca: durable task state could not refresh legacy mirror during startup: {error}"
        );
    }
}

fn reconcile_main_session_task_mirrors_on_start(
    thread: &RuntimeThread,
    snapshot: &surface::SurfaceSnapshot,
) {
    let task_registry = thread.session().task_registry();
    for task in &snapshot.tasks {
        reconcile_main_session_task_mirror(&task_registry, task);
        if matches!(
            task.status,
            surface::SurfaceTaskStatus::Completed
                | surface::SurfaceTaskStatus::Failed
                | surface::SurfaceTaskStatus::Stopped
                | surface::SurfaceTaskStatus::Cancelled
                | surface::SurfaceTaskStatus::ApprovalRequired
        ) && let Err(error) = task_registry.clear_typed_provider_outcome(task.task_id.as_str())
        {
            eprintln!(
                "orca: stale typed provider outcome cleanup failed for {}: {error}",
                task.task_id.as_str()
            );
        }
    }
}

fn recover_background_approval_routes_on_start(
    coordinator: &mut surface::RuntimeCommitCoordinator<'static, surface::JsonlSurfaceCommitLedger>,
) -> Result<(), RuntimeHostError> {
    loop {
        let snapshot = coordinator.state().snapshot().clone();
        let Some((interaction, background_fence, current_epoch)) =
            snapshot.interactions.iter().find_map(|interaction| {
                if interaction.kind != surface::SurfaceInteractionKind::BackgroundApproval
                    || !matches!(
                        interaction.lifecycle,
                        surface::SurfaceInteractionLifecycle::Requested
                    )
                {
                    return None;
                }
                let current_epoch = match &interaction.route {
                    surface::SurfaceInteractionRoute::Unassigned { .. } => return None,
                    surface::SurfaceInteractionRoute::Exclusive { epoch, .. }
                    | surface::SurfaceInteractionRoute::SharedFirstCommitWins { epoch, .. } => {
                        *epoch
                    }
                };
                let background_fence = snapshot
                    .background_operations
                    .iter()
                    .find(|background| {
                        background.operation_id == interaction.fence.operation_id
                            && background.fence.operation_fence == interaction.fence
                    })?
                    .fence
                    .clone();
                Some((interaction.clone(), background_fence, current_epoch))
            })
        else {
            return Ok(());
        };
        let next_revision =
            surface::InteractionRevision::try_new(interaction.revision.get().saturating_add(1))
                .expect("interaction revision did not exhaust");
        let next_epoch =
            surface::ResponseRouteEpoch::try_new(current_epoch.get().saturating_add(1))
                .expect("interaction route epoch did not exhaust");
        let batch = runtime_surface_event_batch(
            &snapshot,
            vec![(
                surface::SurfaceScope::Background {
                    fence: background_fence.clone(),
                },
                surface::SurfaceEvent::Interaction(surface::InteractionPatch::RouteChanged {
                    interaction_id: interaction.interaction_id,
                    expected_revision: interaction.revision,
                    next_revision,
                    route: surface::SurfaceInteractionRoute::Unassigned { epoch: next_epoch },
                }),
            )],
            None,
        );
        coordinator
            .commit_provider_background_interaction_route_batch(background_fence, &batch)
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("failed to recover background approval response route: {error:?}"),
            })?;
    }
}

fn recovered_background_approval_interactions(
    coordinator: &surface::RuntimeCommitCoordinator<'static, surface::JsonlSurfaceCommitLedger>,
) -> HashMap<surface::SurfaceInteractionId, ResidentSurfaceInteraction> {
    let snapshot = coordinator.state().snapshot();
    let mut committed_resolutions = HashMap::new();
    if let Ok(recovered) = coordinator.ledger().recover_batches() {
        for batch in recovered.committed {
            for envelope in batch.events.as_slice() {
                let surface::SurfaceEvent::Interaction(surface::InteractionPatch::Resolved {
                    interaction_id,
                    ..
                }) = &envelope.event
                else {
                    continue;
                };
                committed_resolutions.insert(
                    interaction_id.clone(),
                    (
                        surface::MutationCommitAck::ThreadLocalCursor {
                            cursor: batch.cursor_after.clone(),
                            family: surface::SurfaceFactFamily::Interaction,
                            event_id: envelope.event_id.clone(),
                            commit_class: batch.commit_class.clone(),
                        },
                        batch.cursor_after.clone(),
                    ),
                );
            }
        }
    }
    snapshot
        .interactions
        .iter()
        .filter_map(|interaction| {
            if interaction.kind != surface::SurfaceInteractionKind::BackgroundApproval {
                return None;
            }
            let (winning_receipt, resolution_ack, projected_cursor) = match &interaction.lifecycle {
                surface::SurfaceInteractionLifecycle::Requested => (None, None, None),
                surface::SurfaceInteractionLifecycle::Resolved { receipt } => {
                    let (ack, cursor) = committed_resolutions
                        .get(&interaction.interaction_id)?
                        .clone();
                    (Some(receipt.clone()), Some(ack), Some(cursor))
                }
                surface::SurfaceInteractionLifecycle::Cancelled { .. }
                | surface::SurfaceInteractionLifecycle::Expired { .. }
                | surface::SurfaceInteractionLifecycle::Transferred { .. } => return None,
            };
            let epoch = match &interaction.route {
                surface::SurfaceInteractionRoute::Unassigned { epoch }
                | surface::SurfaceInteractionRoute::Exclusive { epoch, .. }
                | surface::SurfaceInteractionRoute::SharedFirstCommitWins { epoch, .. } => *epoch,
            };
            let record = surface::BrokerInteractionRequestRecord {
                thread_id: interaction.fence.thread_id.clone(),
                interaction_id: interaction.interaction_id.clone(),
                fence: interaction.fence.clone(),
                kind: interaction.kind,
                request: interaction.request.clone(),
                response_token: surface::SurfaceResponseToken::new(random_token_bytes()),
                answer_policy: surface::BrokerInteractionAnswerPolicy::NativeStrict,
                recovery_disposition: interaction.recovery_disposition.clone(),
            };
            Some((
                interaction.interaction_id.clone(),
                ResidentSurfaceInteraction {
                    record,
                    route: surface::BrokerInteractionResponseRoute::Unassigned { epoch },
                    revision: interaction.revision,
                    waiter: None,
                    private_response: None,
                    pending_background_route: None,
                    winning_receipt,
                    resolution_ack,
                    projected_cursor,
                    cancelled: None,
                },
            ))
        })
        .collect()
}

fn recovered_background_approval_resolutions(
    snapshot: &surface::SurfaceSnapshot,
) -> HashMap<surface::SurfaceOperationId, PendingBackgroundApprovalResolution> {
    snapshot
        .interactions
        .iter()
        .filter_map(|interaction| {
            let surface::SurfaceInteractionRequest::BackgroundApproval { task, tool, .. } =
                &interaction.request
            else {
                return None;
            };
            let surface::SurfaceInteractionLifecycle::Resolved { receipt } = &interaction.lifecycle
            else {
                return None;
            };
            let surface::SurfaceInteractionSafeProjection::BackgroundApproval { allowed } =
                receipt.safe_projection
            else {
                return None;
            };
            let suspended_background = snapshot.background_operations.iter().any(|background| {
                background.operation_id == interaction.fence.operation_id
                    && background.fence.operation_fence == interaction.fence
            });
            let committed_successor = snapshot
                .foreground_operation
                .iter()
                .chain(snapshot.queued_operations.iter())
                .chain(snapshot.operation_history.iter())
                .any(|operation| {
                    operation.operation_id == interaction.fence.operation_id
                        && operation.terminal.is_none()
                        && operation.generations.iter().any(|generation| {
                            generation.fence.generation_id > interaction.fence.generation_id
                        })
                });
            (suspended_background || committed_successor).then(|| {
                (
                    interaction.fence.operation_id.clone(),
                    PendingBackgroundApprovalResolution {
                        fence: interaction.fence.clone(),
                        task: task.clone(),
                        tool: tool.clone(),
                        decision: if allowed {
                            surface::SurfaceAllowDeny::Allow
                        } else {
                            surface::SurfaceAllowDeny::Deny
                        },
                        pending_commit: None,
                        retry_at: tokio::time::Instant::now(),
                    },
                )
            })
        })
        .collect()
}

fn bootstrap_runtime_surface(
    thread: &mut RuntimeThread,
    config: &RunConfig,
    title: &str,
    host_incarnation: surface::HostIncarnation,
    command_tx: tokio_mpsc::Sender<ThreadCommand>,
    capability_change_tx: tokio_mpsc::Sender<()>,
    surface_owner: PreparedSurfaceOwner,
    surface_hub_config: surface::SurfaceHubConfig,
) -> Result<(surface::RuntimeSurfaceHandle, ResidentSurfaceState), RuntimeHostError> {
    if matches!(
        &surface_owner.persistence,
        PreparedSurfacePersistence::Recorded { .. }
    ) {
        bootstrap_recorded_surface(
            thread,
            config,
            title,
            host_incarnation,
            command_tx,
            capability_change_tx,
            surface_owner,
            surface_hub_config,
        )
    } else {
        bootstrap_ephemeral_surface(
            thread,
            config,
            title,
            host_incarnation,
            command_tx,
            capability_change_tx,
            surface_owner,
            surface_hub_config,
        )
    }
}

fn bootstrap_recorded_surface(
    thread: &mut RuntimeThread,
    config: &RunConfig,
    title: &str,
    host_incarnation: surface::HostIncarnation,
    command_tx: tokio_mpsc::Sender<ThreadCommand>,
    capability_change_tx: tokio_mpsc::Sender<()>,
    surface_owner: PreparedSurfaceOwner,
    surface_hub_config: surface::SurfaceHubConfig,
) -> Result<(surface::RuntimeSurfaceHandle, ResidentSurfaceState), RuntimeHostError> {
    let PreparedSurfacePersistence::Recorded { path } = surface_owner.persistence else {
        unreachable!("recorded surface bootstrap received ephemeral persistence")
    };
    let materialized_path = thread.session().surface_commit_path().ok_or_else(|| {
        RuntimeHostError::ThreadStartFailed {
            message: "typed runtime surface requires recorded session history".to_string(),
        }
    })?;
    if materialized_path != path || thread.thread_id() != surface_owner.thread_id {
        return Err(RuntimeHostError::ThreadStartFailed {
            message: "prepared surface owner identity changed during materialization".to_string(),
        });
    }
    let raw_thread_id = uuid::Uuid::parse_str(&surface_owner.thread_id)
        .expect("prepared surface thread identity was validated");
    let thread_id = surface_owner.surface_thread_id;
    let mut incarnation_bytes = *raw_thread_id.as_bytes();
    incarnation_bytes[6] = 0x70 | (incarnation_bytes[6] & 0x0f);
    incarnation_bytes[8] = 0x80 | (incarnation_bytes[8] & 0x3f);
    let incarnation = surface::SurfaceIncarnation::try_from_bytes(incarnation_bytes)
        .expect("normalized thread UUID is v7");
    let restored_context_tokens =
        crate::thread_store::read_latest_context_tokens(&path).map_err(|error| {
            RuntimeHostError::ThreadStartFailed {
                message: format!("failed to restore latest provider context: {error}"),
            }
        })?;

    let owner_lease = surface_owner.owner_lease;
    let current_owner_epoch = surface::ThreadOwnerEpoch::new(owner_lease.owner_epoch());
    let initial_owner_epoch = current_owner_epoch.get().saturating_sub(1).max(1);
    let snapshot = initial_surface_snapshot(
        thread_id,
        incarnation,
        surface::ThreadOwnerEpoch::new(initial_owner_epoch),
        surface::ThreadPersistence::RecordedCatalogued,
        config,
        title,
        restored_context_tokens,
    )?;
    let ledger = surface::JsonlSurfaceCommitLedger::new(path, snapshot.cursor.clone());
    let mut coordinator = surface::RuntimeCommitCoordinator::recover_with_owned_lease(
        ledger,
        surface::SurfaceReducerState::new(snapshot),
        owner_lease,
    )
    .map_err(|error| RuntimeHostError::ThreadStartFailed {
        message: format!("failed to recover typed runtime surface: {error:?}"),
    })?;
    if current_owner_epoch.get() > initial_owner_epoch {
        let materialization = surface::MaterializationCause::ColdOwnerTakeover {
            new_incarnation: surface::SurfaceIncarnation::try_from_bytes(
                *uuid::Uuid::now_v7().as_bytes(),
            )
            .expect("generated UUID is v7"),
            new_owner_epoch: current_owner_epoch,
        };
        coordinator
            .materialize_cold_owner_takeover(&materialization)
            .map_err(|error| RuntimeHostError::ThreadStartFailed {
                message: format!("failed to materialize typed surface owner: {error:?}"),
            })?;
        reconcile_main_session_task_mirrors_on_start(thread, coordinator.state().snapshot());
        reconcile_durable_workflow_outcomes_on_start(thread, config, &mut coordinator)?;
        reconcile_durable_provider_outcomes_on_start(thread, &mut coordinator, &host_incarnation)?;
        let operation_ids = coordinator
            .state()
            .snapshot()
            .foreground_operation
            .iter()
            .chain(coordinator.state().snapshot().queued_operations.iter())
            .chain(coordinator.state().snapshot().operation_history.iter())
            .map(|operation| operation.operation_id.clone())
            .collect::<Vec<_>>();
        for operation_id in operation_ids {
            let durable_compaction = thread
                .session()
                .manual_compaction_snapshot(&operation_id)
                .map_err(|error| RuntimeHostError::ThreadStartFailed {
                    message: format!("failed to read durable manual compaction snapshot: {error}"),
                })?;
            coordinator
                .recover_interrupted_manual_compaction(&operation_id, durable_compaction.as_ref())
                .map_err(|error| RuntimeHostError::ThreadStartFailed {
                    message: format!(
                        "failed to reconcile typed manual compaction context: {error:?}"
                    ),
                })?;
            coordinator
                .recover_unavailable_interactions(&operation_id, &materialization)
                .map_err(|error| RuntimeHostError::ThreadStartFailed {
                    message: format!(
                        "failed to reconcile typed interaction availability: {error:?}"
                    ),
                })?;
            coordinator
                .recover_interrupted_capability_calls(&operation_id, &materialization)
                .map_err(|error| RuntimeHostError::ThreadStartFailed {
                    message: format!(
                        "failed to reconcile typed capability availability: {error:?}"
                    ),
                })?;
            loop {
                let before = coordinator.state().snapshot().cursor.clone();
                let action = coordinator
                    .recover_operation(&operation_id, &materialization)
                    .map_err(|error| RuntimeHostError::ThreadStartFailed {
                        message: format!("failed to reconcile typed operation: {error:?}"),
                    })?;
                if matches!(
                    action,
                    surface::RecoveryAction::ExposeRecoveryRequired
                        | surface::RecoveryAction::ExposeRetryFinalization
                        | surface::RecoveryAction::ExposeRetryProjection
                        | surface::RecoveryAction::NoOp
                ) {
                    break;
                }
                let terminal = coordinator
                    .state()
                    .snapshot()
                    .foreground_operation
                    .iter()
                    .chain(coordinator.state().snapshot().queued_operations.iter())
                    .chain(coordinator.state().snapshot().operation_history.iter())
                    .find(|operation| operation.operation_id == operation_id)
                    .is_some_and(|operation| {
                        matches!(operation.phase, surface::OperationPhase::Terminal)
                    });
                if terminal {
                    break;
                }
                if coordinator.state().snapshot().cursor == before {
                    return Err(RuntimeHostError::ThreadStartFailed {
                        message: "typed operation recovery made no durable progress".to_string(),
                    });
                }
            }
        }
        reconcile_terminal_main_session_tasks(thread.session().task_registry(), &mut coordinator)?;
        reconcile_interrupted_workflow_surfaces_on_start(&mut coordinator)?;
    }
    recover_background_approval_routes_on_start(&mut coordinator)?;
    reconcile_goal_surface_outbox_on_start(thread, &mut coordinator)?;
    reconcile_main_session_task_mirrors_on_start(thread, coordinator.state().snapshot());
    hydrate_session_pinned_context_from_surface(
        thread,
        coordinator
            .state()
            .snapshot()
            .pinned_context
            .entries
            .as_slice(),
    );
    persist_surface_settings_metadata(
        thread.thread_id(),
        &coordinator.state().snapshot().settings.effective,
    )
    .map_err(|error| RuntimeHostError::ThreadStartFailed {
        message: format!("failed to persist effective typed surface settings: {error}"),
    })?;
    let terminals = recovered_surface_terminals(&coordinator);
    let interactions = recovered_background_approval_interactions(&coordinator);
    let coordinator = coordinator.map_ledger(surface::RuntimeSurfaceCommitLedger::Recorded);
    bind_runtime_surface(
        coordinator,
        host_incarnation,
        command_tx,
        capability_change_tx,
        surface_hub_config,
        terminals,
        interactions,
    )
}

fn bootstrap_ephemeral_surface(
    thread: &mut RuntimeThread,
    config: &RunConfig,
    title: &str,
    host_incarnation: surface::HostIncarnation,
    command_tx: tokio_mpsc::Sender<ThreadCommand>,
    capability_change_tx: tokio_mpsc::Sender<()>,
    surface_owner: PreparedSurfaceOwner,
    surface_hub_config: surface::SurfaceHubConfig,
) -> Result<(surface::RuntimeSurfaceHandle, ResidentSurfaceState), RuntimeHostError> {
    let persistence = surface_owner.persistence;
    let close_after = match persistence {
        PreparedSurfacePersistence::EphemeralNonCataloguedOneShot { close_after } => {
            Some(close_after)
        }
        PreparedSurfacePersistence::EphemeralAttached => None,
        PreparedSurfacePersistence::Recorded { .. } => {
            unreachable!("ephemeral surface bootstrap received recorded persistence")
        }
    };

    if thread.session().session_id().is_some() || thread.thread_id() != surface_owner.thread_id {
        return Err(RuntimeHostError::ThreadStartFailed {
            message: "prepared ephemeral surface identity changed during materialization"
                .to_string(),
        });
    }
    let raw_thread_id = uuid::Uuid::parse_str(&surface_owner.thread_id)
        .expect("prepared ephemeral surface thread identity was validated");
    let incarnation = surface::SurfaceIncarnation::try_from_bytes(*raw_thread_id.as_bytes())
        .expect("ephemeral runtime thread UUID is v7");
    let owner_epoch = surface::ThreadOwnerEpoch::new(surface_owner.owner_lease.owner_epoch());
    let persistence = match close_after {
        Some(close_after) => {
            surface::ThreadPersistence::EphemeralNonCataloguedOneShot { close_after }
        }
        None => surface::ThreadPersistence::EphemeralAttached,
    };
    let snapshot = initial_surface_snapshot(
        surface_owner.surface_thread_id,
        incarnation,
        owner_epoch,
        persistence,
        config,
        title,
        None,
    )?;
    let ledger = surface::RuntimeSurfaceCommitLedger::Ephemeral(
        surface::InMemorySurfaceCommitLedger::new(snapshot.cursor.clone()),
    );
    let coordinator = surface::RuntimeCommitCoordinator::new_with_owned_lease(
        ledger,
        surface::SurfaceReducerState::new(snapshot),
        surface_owner.owner_lease,
    )
    .map_err(|error| RuntimeHostError::ThreadStartFailed {
        message: format!("failed to initialize ephemeral runtime surface: {error:?}"),
    })?;
    bind_runtime_surface(
        coordinator,
        host_incarnation,
        command_tx,
        capability_change_tx,
        surface_hub_config,
        HashMap::new(),
        HashMap::new(),
    )
}

fn bind_runtime_surface(
    mut coordinator: surface::RuntimeCommitCoordinator<
        'static,
        surface::RuntimeSurfaceCommitLedger,
    >,
    host_incarnation: surface::HostIncarnation,
    command_tx: tokio_mpsc::Sender<ThreadCommand>,
    capability_change_tx: tokio_mpsc::Sender<()>,
    surface_hub_config: surface::SurfaceHubConfig,
    terminals: HashMap<surface::SurfaceOperationId, surface::OperationTerminalAtCursor>,
    interactions: HashMap<surface::SurfaceInteractionId, ResidentSurfaceInteraction>,
) -> Result<(surface::RuntimeSurfaceHandle, ResidentSurfaceState), RuntimeHostError> {
    let authority = surface::SurfaceAttachAuthority::new(
        host_incarnation,
        coordinator.state().snapshot().thread.thread_id.clone(),
        surface::SurfaceAttachmentRole::Tui,
        surface::NonEmptySet::try_new(BTreeSet::from([
            surface::SurfaceCapability::ReadSnapshot,
            surface::SurfaceCapability::SubmitOperation,
            surface::SurfaceCapability::ControlBoundOperation,
            surface::SurfaceCapability::ManageTask,
            surface::SurfaceCapability::ManageWorkflow,
            surface::SurfaceCapability::ManageGoal,
            surface::SurfaceCapability::ManageThreadSettings,
            surface::SurfaceCapability::ManagePinnedContext,
            surface::SurfaceCapability::RespondGrantedInteraction,
            surface::SurfaceCapability::RepairThread,
        ]))
        .expect("production TUI grant is non-empty"),
        surface::NonEmptySet::try_new(BTreeSet::from([surface::SurfaceCapability::ReadSnapshot]))
            .expect("production TUI required grant is non-empty"),
        BTreeSet::from([
            surface::SurfaceInteractionKind::ToolApproval,
            surface::SurfaceInteractionKind::PermissionRequest,
            surface::SurfaceInteractionKind::UserInput,
            surface::SurfaceInteractionKind::McpElicitation,
            surface::SurfaceInteractionKind::BackgroundApproval,
        ]),
    );
    let hub = surface::SurfaceHub::from_authority(
        coordinator.state().snapshot().clone(),
        authority,
        surface_hub_config,
    )
    .map_err(|error| RuntimeHostError::ThreadStartFailed {
        message: format!("failed to create typed runtime surface: {error:?}"),
    })?
    .with_dispatcher(Arc::new(ThreadSurfaceDispatcher {
        command_tx,
        capability_change_tx,
    }));
    coordinator.bind_surface_hub(hub.clone()).map_err(|error| {
        RuntimeHostError::ThreadStartFailed {
            message: format!("failed to bind typed runtime surface: {error:?}"),
        }
    })?;
    Ok((
        surface::RuntimeSurfaceHandle::from_hub(hub.clone()),
        ResidentSurfaceState {
            coordinator,
            hub: hub.clone(),
            capability: RuntimeCapabilityController::new(),
            interactions,
            operation_origin_attachments: HashMap::new(),
            pending_task_ownership: None,
            pending_detaches: HashMap::new(),
            pending_capability_losses: HashMap::new(),
            commit: SurfaceCommitController::new(terminals),
        },
    ))
}

fn hydrate_session_pinned_context_from_surface(
    thread: &mut RuntimeThread,
    entries: &[surface::SurfacePinnedContextEntry],
) {
    let missing = entries
        .iter()
        .filter(|entry| matches!(entry.kind, surface::SurfacePinnedContextKind::User))
        .filter(|entry| {
            !thread
                .session()
                .conversation()
                .messages
                .iter()
                .any(|message| {
                    matches!(
                        message,
                        Message::User { content, pinned: true } if content == entry.content.as_str()
                    )
                })
        })
        .map(|entry| entry.content.as_str().to_string())
        .collect::<Vec<_>>();
    if missing.is_empty() {
        return;
    }
    let session = thread.session_mut();
    for content in missing {
        session.add_pinned_context(content);
    }
}

fn initial_surface_snapshot(
    thread_id: surface::SurfaceThreadId,
    incarnation: surface::SurfaceIncarnation,
    owner_epoch: surface::ThreadOwnerEpoch,
    persistence: surface::ThreadPersistence,
    config: &RunConfig,
    title: &str,
    restored_context_tokens: Option<u64>,
) -> Result<surface::SurfaceSnapshot, RuntimeHostError> {
    let cwd = config.cwd.clone().unwrap_or_else(|| {
        std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("/"))
    });
    let cwd = surface::CanonicalPath::try_new(cwd).map_err(|error| {
        RuntimeHostError::ThreadStartFailed {
            message: format!("invalid surface cwd: {error:?}"),
        }
    })?;
    let workspace_roots = config
        .runtime_workspace_roots
        .clone()
        .unwrap_or_else(|| vec![cwd.as_path().to_path_buf()])
        .into_iter()
        .map(surface::CanonicalPath::try_new)
        .collect::<Result<Vec<_>, _>>()
        .map_err(|error| RuntimeHostError::ThreadStartFailed {
            message: format!("invalid surface workspace root: {error:?}"),
        })?;
    let additional_working_directories = config
        .additional_working_directories
        .iter()
        .map(|directory| {
            Ok(surface::SurfaceAdditionalWorkingDirectory {
                path: surface::CanonicalPath::try_new(directory.path.clone()).map_err(|error| {
                    RuntimeHostError::ThreadStartFailed {
                        message: format!("invalid surface additional working directory: {error:?}"),
                    }
                })?,
                source: surface::NonEmptyText::try_new(directory.source.clone()).map_err(
                    |error| RuntimeHostError::ThreadStartFailed {
                        message: format!(
                            "invalid surface additional working directory source: {error:?}"
                        ),
                    },
                )?,
            })
        })
        .collect::<Result<Vec<_>, RuntimeHostError>>()?;
    let now = surface::UnixMillis::new(
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis()
            .min(i64::MAX as u128) as i64,
    );
    let approval_mode = match config.approval_mode {
        ApprovalMode::Suggest => surface::SurfaceApprovalMode::Suggest,
        ApprovalMode::AutoEdit => surface::SurfaceApprovalMode::AutoEdit,
        ApprovalMode::FullAuto => surface::SurfaceApprovalMode::FullAuto,
        ApprovalMode::Plan => surface::SurfaceApprovalMode::Plan,
    };
    let reasoning_effort = match config.reasoning_effort {
        orca_core::config::ReasoningEffort::Low => surface::SurfaceReasoningEffort::Low,
        orca_core::config::ReasoningEffort::High => surface::SurfaceReasoningEffort::High,
        orca_core::config::ReasoningEffort::Max => surface::SurfaceReasoningEffort::Max,
    };
    let active_permission_profile = config
        .active_permission_profile
        .as_ref()
        .map(|profile| {
            Ok(surface::SurfaceActivePermissionProfile {
                id: surface::NonEmptyText::try_new(profile.id.clone()).map_err(|error| {
                    RuntimeHostError::ThreadStartFailed {
                        message: format!("invalid active permission profile id: {error:?}"),
                    }
                })?,
                extends: profile
                    .extends
                    .as_ref()
                    .map(|value| surface::NonEmptyText::try_new(value.clone()))
                    .transpose()
                    .map_err(|error| RuntimeHostError::ThreadStartFailed {
                        message: format!("invalid active permission profile parent: {error:?}"),
                    })?,
            })
        })
        .transpose()?;
    let permission_rules = config
        .permission_rules
        .rules
        .iter()
        .map(|rule| {
            Ok(surface::SurfacePermissionRule {
                tool: surface::NonEmptyText::try_new(rule.tool.clone()).map_err(|error| {
                    RuntimeHostError::ThreadStartFailed {
                        message: format!("invalid permission rule tool: {error:?}"),
                    }
                })?,
                pattern: surface::NonEmptyText::try_new(rule.pattern.clone()).map_err(|error| {
                    RuntimeHostError::ThreadStartFailed {
                        message: format!("invalid permission rule pattern: {error:?}"),
                    }
                })?,
                decision: match rule.decision {
                    orca_core::approval_types::Decision::Allow => {
                        surface::SurfacePermissionDecision::Allow
                    }
                    orca_core::approval_types::Decision::Prompt => {
                        surface::SurfacePermissionDecision::Prompt
                    }
                    orca_core::approval_types::Decision::Deny => {
                        surface::SurfacePermissionDecision::Deny
                    }
                },
            })
        })
        .collect::<Result<Vec<_>, RuntimeHostError>>()?;
    let permission_rules_digest = surface_sha256(
        &serde_json::to_vec(&permission_rules).expect("surface permission rules are serializable"),
    );
    let context_limit_tokens = config
        .model_runtime
        .context_window
        .unwrap_or_else(|| orca_core::model::max_context_tokens(config.model.as_deref()))
        .max(1) as u64;
    let settings = surface::SurfaceRuntimeSettings {
        model: surface::NonEmptyText::try_new(
            config
                .model
                .as_history_value()
                .unwrap_or_else(|| "runtime-default".to_string()),
        )
        .expect("runtime model is non-empty"),
        reasoning_effort,
        approval_mode,
        cwd: cwd.clone(),
        workspace_roots: workspace_roots.clone(),
        active_permission_profile,
        permission_rules: surface::SurfacePermissionRuleSet {
            ordered_rules: permission_rules,
            digest: permission_rules_digest,
        },
        additional_working_directories,
        network_permissions: surface::SurfaceNetworkPermissions {
            enabled: None,
            domains: Vec::new(),
        },
        policy_epoch: surface::PolicyEpoch::try_new(1).expect("one is a valid revision"),
    };
    let source_revision = match &persistence {
        surface::ThreadPersistence::RecordedCatalogued => surface::CursorSourceRevision::Recorded {
            durable_revision: surface::DurableRevision::try_new(1)
                .expect("one is a valid revision"),
        },
        surface::ThreadPersistence::EphemeralNonCataloguedOneShot { .. }
        | surface::ThreadPersistence::EphemeralAttached => {
            surface::CursorSourceRevision::Ephemeral {
                live_revision: surface::LiveRevision::try_new(1).expect("one is a valid revision"),
            }
        }
    };
    let cursor = surface::SurfaceCursor {
        thread_id: thread_id.clone(),
        incarnation,
        next_seq: surface::SequenceNumber::new(0),
        source_revision,
    };
    Ok(surface::SurfaceSnapshot {
        cursor,
        thread: surface::SurfaceThreadSnapshot {
            thread_id,
            owner_epoch,
            persistence,
            title: surface::DisplayText::new(title),
            metadata_revision: surface::SessionMetadataRevision::try_new(1)
                .expect("one is a valid revision"),
            created_at: now,
            updated_at: now,
            cwd: cwd.clone(),
            workspace_roots,
            closed: false,
        },
        foreground_operation: None,
        queued_operations: Vec::new(),
        background_operations: Vec::new(),
        operation_history: Vec::new(),
        items: Vec::new(),
        assistant_streams: Vec::new(),
        tools: Vec::new(),
        plan: surface::SurfacePlanSnapshot {
            revision: surface::PlanRevision::try_new(1).expect("one is a valid revision"),
            explanation: None,
            items: Vec::new(),
            causative_generation: None,
        },
        usage: surface::SurfaceUsageSnapshot {
            revision: surface::UsageRevision::try_new(1).expect("one is a valid revision"),
            thread_total: surface::UsageTotals {
                input_tokens: 0,
                output_tokens: 0,
                cache_tokens: 0,
                estimated_cost_usd_micros: 0,
            },
            active_operation: None,
            goal: None,
            workflow: Vec::new(),
        },
        context: surface::SurfaceContextSnapshot {
            revision: surface::ContextRevision::try_new(1).expect("one is a valid revision"),
            used_tokens: restored_context_tokens.unwrap_or(0),
            limit_tokens: context_limit_tokens,
            compaction: surface::CompactionState::Idle,
            fragments: Vec::new(),
            provider_replay: surface::ProviderReplayHealth::None,
        },
        interactions: Vec::new(),
        tasks: Vec::new(),
        workflows: Vec::new(),
        subagents: Vec::new(),
        goal: None,
        settings: surface::SurfaceSettingsSnapshot {
            host_revision: surface::SettingsRevision::try_new(1).expect("one is a valid revision"),
            thread_revision: surface::SettingsRevision::try_new(1)
                .expect("one is a valid revision"),
            effective: settings,
            pending: None,
            frozen_generation_revision: None,
        },
        mcp_catalog: surface::SurfaceMcpCatalogSnapshot {
            revision: surface::McpCatalogRevision::try_new(1).expect("one is a valid revision"),
            servers: Vec::new(),
            tools: Vec::new(),
            resources: Vec::new(),
            resource_templates: Vec::new(),
            diagnostics: Vec::new(),
        },
        pinned_context: surface::SurfacePinnedContextSnapshot {
            revision: surface::PinnedContextRevision::try_new(1).expect("one is a valid revision"),
            entries: Vec::new(),
        },
        session_health: surface::SurfaceSessionHealth {
            revision: surface::SessionHealthRevision::try_new(1).expect("one is a valid revision"),
            accepting_admission: true,
            issues: Vec::new(),
            closing: false,
            closed: false,
        },
    })
}

fn apply_runtime_settings_patch(
    config: &mut RunConfig,
    settings: &mut surface::SurfaceRuntimeSettings,
    patch: &surface::RuntimeSettingsPatch,
) -> Result<(), surface::SurfaceClientCommandError> {
    match patch {
        surface::RuntimeSettingsPatch::SetModel { model } => {
            config.model =
                orca_core::model::ModelSelection::from_unchecked(Some(model.as_str().to_string()));
            settings.model = model.clone();
        }
        surface::RuntimeSettingsPatch::SetReasoning { effort } => {
            config.reasoning_effort = match effort {
                surface::SurfaceReasoningEffort::Low => orca_core::config::ReasoningEffort::Low,
                surface::SurfaceReasoningEffort::Medium => {
                    return Err(surface::SurfaceClientCommandError::Unauthorized);
                }
                surface::SurfaceReasoningEffort::High => orca_core::config::ReasoningEffort::High,
                surface::SurfaceReasoningEffort::Max => orca_core::config::ReasoningEffort::Max,
            };
            settings.reasoning_effort = *effort;
        }
        surface::RuntimeSettingsPatch::SetApprovalMode { mode } => {
            config.approval_mode = match mode {
                surface::SurfaceApprovalMode::Suggest => ApprovalMode::Suggest,
                surface::SurfaceApprovalMode::AutoEdit => ApprovalMode::AutoEdit,
                surface::SurfaceApprovalMode::FullAuto => ApprovalMode::FullAuto,
                surface::SurfaceApprovalMode::Plan => ApprovalMode::Plan,
            };
            settings.approval_mode = *mode;
        }
        surface::RuntimeSettingsPatch::SetCwd { cwd } => {
            config.cwd = Some(cwd.as_path().to_path_buf());
            settings.cwd = cwd.clone();
        }
        surface::RuntimeSettingsPatch::SetWorkspaceRoots { roots } => {
            config.runtime_workspace_roots = Some(
                roots
                    .iter()
                    .map(|root| root.as_path().to_path_buf())
                    .collect(),
            );
            settings.workspace_roots = roots.clone();
        }
        surface::RuntimeSettingsPatch::SetActivePermissionProfile { profile } => {
            config.active_permission_profile =
                profile
                    .as_ref()
                    .map(|profile| orca_core::config::ActivePermissionProfile {
                        id: profile.id.as_str().to_string(),
                        extends: profile
                            .extends
                            .as_ref()
                            .map(|value| value.as_str().to_string()),
                    });
            settings.active_permission_profile = profile.clone();
        }
        surface::RuntimeSettingsPatch::ReplacePermissionRules { rules } => {
            config.permission_rules = orca_core::approval_rules::PermissionRules {
                rules: rules
                    .iter()
                    .map(|rule| {
                        orca_core::approval_rules::PermissionRule::new(
                            rule.tool.as_str(),
                            rule.pattern.as_str(),
                            match rule.decision {
                                surface::SurfacePermissionDecision::Allow => {
                                    orca_core::approval_types::Decision::Allow
                                }
                                surface::SurfacePermissionDecision::Prompt => {
                                    orca_core::approval_types::Decision::Prompt
                                }
                                surface::SurfacePermissionDecision::Deny => {
                                    orca_core::approval_types::Decision::Deny
                                }
                            },
                        )
                    })
                    .collect(),
            };
            settings.permission_rules = surface::SurfacePermissionRuleSet {
                ordered_rules: rules.clone(),
                digest: surface_sha256(
                    &serde_json::to_vec(rules).expect("surface permission rules are serializable"),
                ),
            };
        }
        surface::RuntimeSettingsPatch::ReplaceAdditionalWorkingDirectories { directories } => {
            config.additional_working_directories = directories
                .iter()
                .map(|directory| orca_core::config::AdditionalWorkingDirectory {
                    path: directory.path.as_path().to_path_buf(),
                    source: directory.source.as_str().to_string(),
                })
                .collect();
            settings.additional_working_directories = directories.clone();
        }
        surface::RuntimeSettingsPatch::ReplaceNetworkPermissions { permissions } => {
            settings.network_permissions = permissions.clone();
        }
        surface::RuntimeSettingsPatch::ApplyPermissionUpdate { .. } => {
            return Err(surface::SurfaceClientCommandError::Unauthorized);
        }
    }
    Ok(())
}

fn runtime_settings_patch_affects_policy(patch: &surface::RuntimeSettingsPatch) -> bool {
    matches!(
        patch,
        surface::RuntimeSettingsPatch::SetApprovalMode { .. }
            | surface::RuntimeSettingsPatch::SetCwd { .. }
            | surface::RuntimeSettingsPatch::SetWorkspaceRoots { .. }
            | surface::RuntimeSettingsPatch::SetActivePermissionProfile { .. }
            | surface::RuntimeSettingsPatch::ReplacePermissionRules { .. }
            | surface::RuntimeSettingsPatch::ReplaceAdditionalWorkingDirectories { .. }
            | surface::RuntimeSettingsPatch::ReplaceNetworkPermissions { .. }
            | surface::RuntimeSettingsPatch::ApplyPermissionUpdate { .. }
    )
}

fn hydrate_run_config_from_surface_settings(
    config: &mut RunConfig,
    settings: &surface::SurfaceRuntimeSettings,
) -> Result<(), surface::SurfaceClientCommandError> {
    let mut restored = settings.clone();
    apply_runtime_settings_patch(
        config,
        &mut restored,
        &surface::RuntimeSettingsPatch::SetModel {
            model: settings.model.clone(),
        },
    )?;
    apply_runtime_settings_patch(
        config,
        &mut restored,
        &surface::RuntimeSettingsPatch::SetReasoning {
            effort: settings.reasoning_effort,
        },
    )?;
    apply_runtime_settings_patch(
        config,
        &mut restored,
        &surface::RuntimeSettingsPatch::SetApprovalMode {
            mode: settings.approval_mode,
        },
    )?;
    apply_runtime_settings_patch(
        config,
        &mut restored,
        &surface::RuntimeSettingsPatch::SetCwd {
            cwd: settings.cwd.clone(),
        },
    )?;
    apply_runtime_settings_patch(
        config,
        &mut restored,
        &surface::RuntimeSettingsPatch::SetWorkspaceRoots {
            roots: settings.workspace_roots.clone(),
        },
    )?;
    apply_runtime_settings_patch(
        config,
        &mut restored,
        &surface::RuntimeSettingsPatch::SetActivePermissionProfile {
            profile: settings.active_permission_profile.clone(),
        },
    )?;
    apply_runtime_settings_patch(
        config,
        &mut restored,
        &surface::RuntimeSettingsPatch::ReplacePermissionRules {
            rules: settings.permission_rules.ordered_rules.clone(),
        },
    )?;
    apply_runtime_settings_patch(
        config,
        &mut restored,
        &surface::RuntimeSettingsPatch::ReplaceAdditionalWorkingDirectories {
            directories: settings.additional_working_directories.clone(),
        },
    )?;
    Ok(())
}

fn persist_surface_settings_metadata(
    thread_id: &str,
    settings: &surface::SurfaceRuntimeSettings,
) -> io::Result<()> {
    let network_domain_permissions = settings
        .network_permissions
        .domains
        .iter()
        .map(|permission| {
            (
                permission.domain.as_str().to_string(),
                match permission.access {
                    surface::SurfaceNetworkDomainAccess::Allow => {
                        orca_core::config::PermissionProfileNetworkAccess::Allow
                    }
                    surface::SurfaceNetworkDomainAccess::Deny => {
                        orca_core::config::PermissionProfileNetworkAccess::Deny
                    }
                },
            )
        })
        .collect();
    SessionStore::new()
        .update_thread_metadata(
            thread_id,
            ThreadMetadataPatch {
                title: None,
                active_permission_profile: settings.active_permission_profile.as_ref().map(
                    |profile| orca_core::config::ActivePermissionProfile {
                        id: profile.id.as_str().to_string(),
                        extends: profile
                            .extends
                            .as_ref()
                            .map(|value| value.as_str().to_string()),
                    },
                ),
                approval_mode: Some(match settings.approval_mode {
                    surface::SurfaceApprovalMode::Suggest => ApprovalMode::Suggest,
                    surface::SurfaceApprovalMode::AutoEdit => ApprovalMode::AutoEdit,
                    surface::SurfaceApprovalMode::FullAuto => ApprovalMode::FullAuto,
                    surface::SurfaceApprovalMode::Plan => ApprovalMode::Plan,
                }),
                runtime_workspace_roots: Some(
                    settings
                        .workspace_roots
                        .iter()
                        .map(|root| root.as_path().to_path_buf())
                        .collect(),
                ),
                permission_rules: Some(orca_core::approval_rules::PermissionRules {
                    rules: settings
                        .permission_rules
                        .ordered_rules
                        .iter()
                        .map(|rule| {
                            orca_core::approval_rules::PermissionRule::new(
                                rule.tool.as_str(),
                                rule.pattern.as_str(),
                                match rule.decision {
                                    surface::SurfacePermissionDecision::Allow => {
                                        orca_core::approval_types::Decision::Allow
                                    }
                                    surface::SurfacePermissionDecision::Prompt => {
                                        orca_core::approval_types::Decision::Prompt
                                    }
                                    surface::SurfacePermissionDecision::Deny => {
                                        orca_core::approval_types::Decision::Deny
                                    }
                                },
                            )
                        })
                        .collect(),
                }),
                additional_working_directories: Some(
                    settings
                        .additional_working_directories
                        .iter()
                        .map(|directory| orca_core::config::AdditionalWorkingDirectory {
                            path: directory.path.as_path().to_path_buf(),
                            source: directory.source.as_str().to_string(),
                        })
                        .collect(),
                ),
                metadata_writable_directories: None,
                network_domain_permissions: Some(network_domain_permissions),
            },
        )
        .map(|_| ())
}

fn recovered_surface_terminals(
    coordinator: &surface::RuntimeCommitCoordinator<'static, surface::JsonlSurfaceCommitLedger>,
) -> HashMap<surface::SurfaceOperationId, surface::OperationTerminalAtCursor> {
    let mut terminals = HashMap::new();
    let Ok(recovered) = coordinator.ledger().recover_batches() else {
        return terminals;
    };
    for batch in recovered.committed {
        for envelope in batch.events.as_slice() {
            let surface::SurfaceEvent::Operation(surface::OperationPatch::Terminal { record }) =
                &envelope.event
            else {
                continue;
            };
            terminals.insert(
                record.operation_id.clone(),
                surface::OperationTerminalAtCursor {
                    operation_id: record.operation_id.clone(),
                    terminal: record.terminal.clone(),
                    cursor: batch.cursor_after.clone(),
                    commit_class: batch.commit_class.clone(),
                    batch_digest: batch.batch_digest.clone(),
                },
            );
        }
    }
    terminals
}

fn surface_request_text(request: &surface::SurfaceInputRequest) -> String {
    request
        .blocks
        .as_slice()
        .iter()
        .filter_map(|block| match block {
            surface::SurfaceInputRequestBlock::Text { text }
            | surface::SurfaceInputRequestBlock::EmbeddedText { text, .. } => Some(text.as_str()),
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn jsonl_turn_control_wire_action(
    action: &surface::JsonlTurnControlAction,
) -> surface::JsonlTurnControlWireAction {
    match action {
        surface::JsonlTurnControlAction::Interrupt => {
            surface::JsonlTurnControlWireAction::Interrupt
        }
        surface::JsonlTurnControlAction::Resume => surface::JsonlTurnControlWireAction::Resume,
        surface::JsonlTurnControlAction::Steer { .. } => surface::JsonlTurnControlWireAction::Steer,
    }
}

fn jsonl_turn_control_legacy_input(
    action: &surface::JsonlTurnControlAction,
) -> Option<surface::DisplayText> {
    match action {
        surface::JsonlTurnControlAction::Steer { input } => {
            Some(surface::DisplayText::new(surface_request_text(input)))
        }
        surface::JsonlTurnControlAction::Interrupt | surface::JsonlTurnControlAction::Resume => {
            None
        }
    }
}

fn jsonl_idle_turn_control(
    request_id: surface::SurfaceRequestId,
    legacy_turn_id: surface::LegacyTurnId,
    action: &surface::JsonlTurnControlAction,
) -> surface::JsonlTurnControlResult {
    surface::JsonlTurnControlResult::Idle {
        request_id,
        echo: surface::JsonlIdleTurnControlWireEcho {
            legacy_turn_id,
            action: jsonl_turn_control_wire_action(action),
            status: surface::JsonlIdleTurnControlStatus::Idle,
            legacy_input: jsonl_turn_control_legacy_input(action),
        },
    }
}

fn resolve_surface_input(request: &surface::SurfaceInputRequest) -> Option<surface::SurfaceInput> {
    let blocks = request
        .blocks
        .as_slice()
        .iter()
        .map(|block| match block {
            surface::SurfaceInputRequestBlock::Text { text } => {
                Some(surface::SurfaceInputBlock::Text { text: text.clone() })
            }
            surface::SurfaceInputRequestBlock::Binding {
                binding:
                    surface::SurfaceInputBindingRequest::ExactCatalog {
                        kind,
                        identity,
                        observed_catalog_revision,
                        observed_settings_revision,
                        label,
                    },
            } => Some(surface::SurfaceInputBlock::Binding {
                binding: surface::SurfaceInputBinding {
                    kind: *kind,
                    identity: identity.clone(),
                    observed_catalog_revision: *observed_catalog_revision,
                    observed_settings_revision: *observed_settings_revision,
                    label: label.clone(),
                },
            }),
            surface::SurfaceInputRequestBlock::Binding {
                binding: surface::SurfaceInputBindingRequest::LegacyJsonlMention { .. },
            } => None,
            surface::SurfaceInputRequestBlock::ResourceLink {
                uri,
                name,
                description,
                mime,
            } => Some(surface::SurfaceInputBlock::ResourceLink {
                uri: uri.clone(),
                name: name.clone(),
                description: description.clone(),
                mime: mime.clone(),
            }),
            surface::SurfaceInputRequestBlock::EmbeddedText {
                uri,
                mime,
                text,
                digest,
            } => Some(surface::SurfaceInputBlock::EmbeddedText {
                uri: uri.clone(),
                mime: mime.clone(),
                text: text.clone(),
                digest: digest.clone(),
            }),
        })
        .collect::<Option<Vec<_>>>()?;
    Some(surface::SurfaceInput {
        blocks: surface::NonEmptyVec::try_new(blocks).ok()?,
        canonical_text: surface::DisplayText::new(surface_request_text(request)),
        bindings_digest: surface_sha256(
            &serde_json::to_vec(request).expect("surface input request is serializable"),
        ),
    })
}

fn surface_input_for_persisted_presentation(
    input: &surface::SurfaceInput,
) -> surface::SurfaceInput {
    let canonical_text = surface_input_presentation_text(input);
    surface::SurfaceInput {
        blocks: surface::NonEmptyVec::try_new(vec![surface::SurfaceInputBlock::Text {
            text: canonical_text.clone(),
        }])
        .expect("persisted presentation input remains non-empty"),
        canonical_text,
        bindings_digest: input.bindings_digest.clone(),
    }
}

fn surface_input_presentation_text(input: &surface::SurfaceInput) -> surface::DisplayText {
    surface_persisted_display_text(input.canonical_text.as_str())
}

fn surface_persisted_display_text(text: &str) -> surface::DisplayText {
    surface::DisplayText::new(crate::thread_store::redact_sensitive_text(text))
}

fn surface_safe_diagnostic(text: &str, fallback: &'static str) -> surface::SafeDiagnosticText {
    surface::SafeDiagnosticText::try_new(crate::thread_store::redact_sensitive_text(text))
        .unwrap_or_else(|_| {
            surface::SafeDiagnosticText::try_new(fallback).expect("fixed diagnostic is bounded")
        })
}

fn stable_surface_stream_prefix_len(text: &str) -> usize {
    if let Some(sensitive_assignment_start) = incomplete_surface_sensitive_assignment_start(text) {
        return sensitive_assignment_start;
    }

    let trailing_token_start = text
        .char_indices()
        .filter_map(|(index, ch)| {
            (ch.is_whitespace()
                || matches!(
                    ch,
                    '"' | '\'' | '{' | '}' | '[' | ']' | ',' | ':' | ';' | '(' | ')'
                ))
            .then_some(index + ch.len_utf8())
        })
        .last()
        .unwrap_or(0);
    let trailing_token = &text[trailing_token_start..];
    let lower = trailing_token.to_ascii_lowercase();
    let mut retained_start = None;
    for needle in [
        "api_key",
        "apikey",
        "token",
        "password",
        "secret",
        "authorization",
    ] {
        if let Some(index) = lower.find(needle) {
            retained_start =
                Some(retained_start.map_or(index, |current: usize| current.min(index)));
            continue;
        }
        for prefix_len in 1..needle.len() {
            if lower.ends_with(&needle[..prefix_len]) {
                let index = lower.len() - prefix_len;
                retained_start =
                    Some(retained_start.map_or(index, |current: usize| current.min(index)));
            }
        }
    }
    if matches!(lower.as_str(), "s" | "sk") || lower.starts_with("sk-") {
        retained_start = Some(0);
    }

    retained_start
        .map(|index| trailing_token_start + index)
        .unwrap_or(text.len())
}

fn incomplete_surface_sensitive_assignment_start(text: &str) -> Option<usize> {
    let bytes = text.as_bytes();
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] != b'=' && bytes[index] != b':' {
            index += 1;
            continue;
        }

        let key_start = surface_sensitive_key_start(bytes, index);
        let key = text[key_start..index].trim_matches(|ch: char| {
            ch.is_whitespace() || matches!(ch, '"' | '\'' | '{' | '[' | ',')
        });
        if !is_surface_sensitive_key(key) {
            index += 1;
            continue;
        }

        let mut value_start = index + 1;
        while value_start < bytes.len() && bytes[value_start].is_ascii_whitespace() {
            value_start += 1;
        }
        if value_start == bytes.len() {
            return Some(key_start);
        }

        if matches!(bytes[value_start], b'"' | b'\'') {
            let quote = bytes[value_start];
            let mut value_index = value_start + 1;
            let mut escaped = false;
            let mut closed = false;
            while value_index < bytes.len() {
                let byte = bytes[value_index];
                if escaped {
                    escaped = false;
                } else if byte == b'\\' {
                    escaped = true;
                } else if byte == quote {
                    closed = true;
                    value_index += 1;
                    break;
                }
                value_index += 1;
            }
            if !closed {
                return Some(key_start);
            }
            index = value_index;
            continue;
        }

        let mut value_index = value_start;
        while value_index < bytes.len()
            && !bytes[value_index].is_ascii_whitespace()
            && !matches!(bytes[value_index], b',' | b'}' | b']' | b';')
        {
            value_index += 1;
        }
        if value_index == bytes.len() {
            return Some(key_start);
        }
        index = value_index + 1;
    }
    None
}

fn surface_sensitive_key_start(bytes: &[u8], delimiter_index: usize) -> usize {
    let mut start = delimiter_index;
    while start > 0 {
        let previous = bytes[start - 1];
        if previous.is_ascii_whitespace() || matches!(previous, b'{' | b'[' | b',' | b';' | b'(') {
            break;
        }
        start -= 1;
    }
    start
}

fn is_surface_sensitive_key(key: &str) -> bool {
    let key = key.to_ascii_lowercase();
    key.contains("api_key")
        || key.contains("apikey")
        || key.contains("token")
        || key.contains("password")
        || key.contains("secret")
        || key.contains("authorization")
}

