fn random_token_bytes() -> [u8; 32] {
    let mut bytes = [0_u8; 32];
    bytes[..16].copy_from_slice(uuid::Uuid::new_v4().as_bytes());
    bytes[16..].copy_from_slice(uuid::Uuid::new_v4().as_bytes());
    bytes
}

fn keyed_interaction_response_digest(
    token: &surface::SurfaceResponseToken,
    answer: &surface::SurfaceClientInteractionAnswer,
) -> surface::OpaqueToken {
    let mut hasher = Sha256::new();
    hasher.update(token.key_bytes());
    hasher.update(serde_json::to_vec(answer).expect("interaction answer serializes"));
    surface::OpaqueToken::new(hasher.finalize().into())
}

fn surface_sha256(bytes: &[u8]) -> surface::Sha256Digest {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    surface::Sha256Digest::new(hasher.finalize().into())
}

fn runtime_terminal_exit_status(
    status: surface::SurfaceTerminalExitStatus,
) -> RuntimeAcpTerminalExitStatus {
    RuntimeAcpTerminalExitStatus {
        exit_code: status.exit_code,
        signal: status.signal.map(|signal| signal.as_str().to_string()),
    }
}

fn surface_workflow_launch_fingerprint(
    catalog_entry_id: &surface::SurfaceCatalogEntryId,
    args: &serde_json::Value,
) -> surface::Sha256Digest {
    surface_sha256(
        &serde_json::to_vec(&(
            "standalone_workflow_launch_v1",
            catalog_entry_id.as_str(),
            args,
        ))
        .expect("workflow launch identity is serializable"),
    )
}

fn surface_goal_finish_command_digest(input: &FinishGoalOuterTurnForSurfaceInput) -> [u8; 32] {
    let continuation = input.continuation.as_ref().map(|continuation| {
        (
            continuation.reason,
            continuation.successor.as_ref(),
            continuation.provider_turn_id.as_str(),
        )
    });
    *surface_sha256(
        &serde_json::to_vec(&(
            "goal_outer_turn_finished_v1",
            input.session_id.as_str(),
            input.expected_goal_id.as_str(),
            input.expected_goal_revision,
            input.identity.as_ref(),
            input.status,
            &input.usage,
            (
                input.progress.tool_count,
                input.progress.model_response_count,
                input.progress.gap_fingerprint.as_deref(),
            ),
            input.next_action,
            &input.verification,
            continuation,
            &input.stop_reason,
            &input.terminal,
            input.pause_message.as_str(),
        ))
        .expect("Goal finish command digest input is serializable"),
    )
    .as_bytes()
}

fn surface_goal_state(
    state: &orca_core::goal_runtime::GoalState,
) -> Result<surface::SurfaceGoalState, RuntimeHostError> {
    use orca_core::goal_runtime::GoalState;
    Ok(match state {
        GoalState::Active => surface::SurfaceGoalState::Active,
        GoalState::Paused { reason, message } => surface::SurfaceGoalState::Paused {
            reason: match reason {
                orca_core::goal_runtime::GoalPauseReason::User => {
                    surface::SurfaceGoalPauseReason::User
                }
                orca_core::goal_runtime::GoalPauseReason::NoProgress => {
                    surface::SurfaceGoalPauseReason::NoProgress
                }
                orca_core::goal_runtime::GoalPauseReason::Backoff => {
                    surface::SurfaceGoalPauseReason::Backoff
                }
                orca_core::goal_runtime::GoalPauseReason::Infrastructure => {
                    surface::SurfaceGoalPauseReason::Infrastructure
                }
                orca_core::goal_runtime::GoalPauseReason::WaitingForWorkflow => {
                    surface::SurfaceGoalPauseReason::WaitingForWorkflow
                }
                orca_core::goal_runtime::GoalPauseReason::Recovery => {
                    surface::SurfaceGoalPauseReason::Recovery
                }
                orca_core::goal_runtime::GoalPauseReason::UsageLimit => {
                    surface::SurfaceGoalPauseReason::UsageLimit
                }
            },
            message: surface::DisplayText::new(message),
        },
        GoalState::Blocked { blocker } => surface::SurfaceGoalState::Blocked {
            blocker: surface_goal_blocker(blocker)?,
        },
        GoalState::BudgetLimited => surface::SurfaceGoalState::BudgetLimited,
        GoalState::Complete { evidence } => surface::SurfaceGoalState::Complete {
            evidence: evidence
                .iter()
                .map(surface_goal_evidence)
                .collect::<Result<Vec<_>, _>>()?,
        },
    })
}

fn surface_goal_evidence(
    evidence: &orca_core::goal_runtime::EvidenceItem,
) -> Result<surface::SurfaceEvidenceItem, RuntimeHostError> {
    Ok(surface::SurfaceEvidenceItem {
        kind: match evidence.kind {
            orca_core::goal_runtime::EvidenceKind::Test => surface::SurfaceEvidenceKind::Test,
            orca_core::goal_runtime::EvidenceKind::File => surface::SurfaceEvidenceKind::File,
            orca_core::goal_runtime::EvidenceKind::Command => surface::SurfaceEvidenceKind::Command,
            orca_core::goal_runtime::EvidenceKind::Observation => {
                surface::SurfaceEvidenceKind::Observation
            }
            orca_core::goal_runtime::EvidenceKind::External => {
                surface::SurfaceEvidenceKind::External
            }
        },
        summary: surface::NonEmptyText::try_new(evidence.summary.clone())
            .map_err(surface_goal_value_error)?,
        target: evidence.target.clone().map(surface::DisplayText::new),
    })
}

fn surface_goal_intent(
    intent: &orca_core::goal_runtime::GoalUpdateIntent,
) -> Result<surface::SurfaceGoalIntent, RuntimeHostError> {
    let intent_id = surface::SurfaceGoalIntentId::try_new(intent.intent_id.to_string())
        .map_err(surface_goal_value_error)?;
    let reason =
        surface::NonEmptyText::try_new(intent.reason.clone()).map_err(surface_goal_value_error)?;
    let evidence = intent
        .evidence
        .iter()
        .map(surface_goal_evidence)
        .collect::<Result<Vec<_>, _>>()?;
    match intent.requested_state {
        orca_core::goal_runtime::GoalRequestedState::Complete => {
            Ok(surface::SurfaceGoalIntent::Complete {
                intent_id,
                reason,
                evidence: surface::NonEmptyVec::try_new(evidence)
                    .map_err(surface_goal_value_error)?,
            })
        }
        orca_core::goal_runtime::GoalRequestedState::Blocked => {
            let blocker =
                intent
                    .blocker
                    .as_ref()
                    .ok_or_else(|| RuntimeHostError::GoalControlFailed {
                        message: "blocked Goal intent lost its blocker".to_string(),
                    })?;
            Ok(surface::SurfaceGoalIntent::Blocked {
                intent_id,
                reason,
                blocker: surface_goal_blocker(blocker)?,
                evidence,
            })
        }
    }
}

fn surface_goal_intent_ack(
    ack: &orca_core::goal_runtime::GoalUpdateAck,
) -> Result<surface::SurfaceGoalIntentAck, RuntimeHostError> {
    use orca_core::goal_runtime::{GoalRejectCode, GoalUpdateAck};
    Ok(match ack {
        GoalUpdateAck::DeferredToTurnEnd {
            intent_id,
            pending_depth,
        } => surface::SurfaceGoalIntentAck::DeferredToTurnEnd {
            intent_id: surface::SurfaceGoalIntentId::try_new(intent_id.to_string())
                .map_err(surface_goal_value_error)?,
            pending_depth: *pending_depth,
        },
        GoalUpdateAck::AlreadyPending { intent_id } => {
            surface::SurfaceGoalIntentAck::AlreadyPending {
                intent_id: surface::SurfaceGoalIntentId::try_new(intent_id.to_string())
                    .map_err(surface_goal_value_error)?,
            }
        }
        GoalUpdateAck::Rejected { code, message } => surface::SurfaceGoalIntentAck::Rejected {
            code: match code {
                GoalRejectCode::Inactive | GoalRejectCode::NoActiveOuterTurn => {
                    surface::GoalIntentRejectionCode::NoActiveOuterTurn
                }
                GoalRejectCode::TerminalIntentPending => {
                    surface::GoalIntentRejectionCode::TerminalIntentPending
                }
                GoalRejectCode::MissingEvidence => {
                    surface::GoalIntentRejectionCode::MissingEvidence
                }
                GoalRejectCode::MissingBlocker => surface::GoalIntentRejectionCode::MissingBlocker,
                GoalRejectCode::StaleIdentity => surface::GoalIntentRejectionCode::StaleIdentity,
            },
            message: surface::DisplayText::new(message),
        },
        GoalUpdateAck::BlockedAgainstInactive { state } => {
            surface::SurfaceGoalIntentAck::BlockedAgainstInactive {
                state: surface_goal_state(state)?,
            }
        }
    })
}

fn surface_goal_verification(
    result: &orca_core::goal_runtime::GoalVerificationResult,
) -> Result<surface::SurfaceGoalVerification, RuntimeHostError> {
    Ok(match result {
        orca_core::goal_runtime::GoalVerificationResult::Achieved { evidence } => {
            surface::SurfaceGoalVerification::Achieved {
                evidence: evidence
                    .iter()
                    .map(surface_goal_evidence)
                    .collect::<Result<Vec<_>, _>>()?,
            }
        }
        orca_core::goal_runtime::GoalVerificationResult::NotAchieved { gaps } => {
            surface::SurfaceGoalVerification::NotAchieved {
                gaps: gaps
                    .iter()
                    .map(|gap| {
                        Ok(surface::SurfaceGoalGap {
                            summary: surface::NonEmptyText::try_new(gap.summary.clone())
                                .map_err(surface_goal_value_error)?,
                            fingerprint: surface::NonEmptyText::try_new(gap.fingerprint.clone())
                                .map_err(surface_goal_value_error)?,
                            model_fixable: gap.model_fixable,
                        })
                    })
                    .collect::<Result<Vec<_>, RuntimeHostError>>()?,
            }
        }
        orca_core::goal_runtime::GoalVerificationResult::Blocked { blocker } => {
            surface::SurfaceGoalVerification::Blocked {
                blocker: surface_goal_blocker(blocker)?,
            }
        }
        orca_core::goal_runtime::GoalVerificationResult::Indeterminate { message } => {
            surface::SurfaceGoalVerification::Indeterminate {
                message: surface::DisplayText::new(message),
            }
        }
    })
}

fn surface_goal_blocker(
    blocker: &orca_core::goal_runtime::BlockerSummary,
) -> Result<surface::SurfaceBlocker, RuntimeHostError> {
    Ok(surface::SurfaceBlocker {
        kind: match blocker.kind {
            orca_core::goal_runtime::BlockerKind::UserDecision => {
                surface::SurfaceBlockerKind::UserDecision
            }
            orca_core::goal_runtime::BlockerKind::MissingAuthority => {
                surface::SurfaceBlockerKind::MissingAuthority
            }
            orca_core::goal_runtime::BlockerKind::ExternalState => {
                surface::SurfaceBlockerKind::ExternalState
            }
            orca_core::goal_runtime::BlockerKind::EnvironmentContradiction => {
                surface::SurfaceBlockerKind::EnvironmentContradiction
            }
            orca_core::goal_runtime::BlockerKind::UnverifiableRequirement => {
                surface::SurfaceBlockerKind::UnverifiableRequirement
            }
        },
        summary: surface::NonEmptyText::try_new(blocker.summary.clone())
            .map_err(surface_goal_value_error)?,
        fingerprint: surface::NonEmptyText::try_new(blocker.fingerprint.clone())
            .map_err(surface_goal_value_error)?,
        evidence: blocker
            .evidence
            .iter()
            .map(surface_goal_evidence)
            .collect::<Result<Vec<_>, _>>()?,
    })
}

fn surface_goal_value_error(error: surface::SurfaceValueError) -> RuntimeHostError {
    RuntimeHostError::GoalControlFailed {
        message: format!("invalid durable Goal projection: {error:?}"),
    }
}

fn surface_goal_from_record(
    record: &orca_core::goal_runtime::GoalRecord,
    receipt: &crate::goal_store::GoalSurfaceStoreReceipt,
    thread_id: surface::SurfaceThreadId,
    current_run: Option<surface::SurfaceGoalRun>,
) -> Result<surface::SurfaceGoal, RuntimeHostError> {
    if record.current_run.is_some() != current_run.is_some() {
        return Err(RuntimeHostError::GoalControlFailed {
            message: "durable Goal row and typed run binding disagree".to_string(),
        });
    }
    Ok(surface::SurfaceGoal {
        goal_id: surface::SurfaceGoalId::try_new(record.goal_id.to_string())
            .map_err(surface_goal_value_error)?,
        thread_id,
        goal_revision: surface::GoalRevision::try_new(u64::from(receipt.goal_revision))
            .map_err(surface_goal_value_error)?,
        goal_owner_epoch: surface::GoalOwnerEpoch::try_new(receipt.goal_owner_epoch)
            .map_err(surface_goal_value_error)?,
        catalog_revision: surface::GoalCatalogRevision::try_new(u64::from(
            receipt.catalog_revision,
        ))
        .map_err(surface_goal_value_error)?,
        receipt_digest: surface::Sha256Digest::new(receipt.receipt_digest),
        objective: surface::NonEmptyText::try_new(record.objective.clone())
            .map_err(surface_goal_value_error)?,
        objective_revision: surface::GoalObjectiveRevision::new(receipt.objective_revision),
        state: surface_goal_state(&record.state)?,
        token_budget: record.token_budget,
        usage: surface::GoalUsage {
            charged_input_tokens: record.usage.charged_input_tokens,
            output_tokens: record.usage.output_tokens,
            cache_tokens: record.usage.cache_tokens,
            verifier_tokens: record.usage.verifier_tokens,
            cost_micros: record.usage.cost_micros,
            elapsed_seconds: record.usage.elapsed_seconds,
        },
        current_run,
        last_transition: record
            .last_transition
            .as_ref()
            .map(|transition| {
                Ok(surface::SurfaceGoalTransition {
                    previous: surface_goal_state(&transition.previous_state)?,
                    next: surface_goal_state(&transition.next_state)?,
                    reason_code: surface::NonEmptyText::try_new(transition.reason_code.clone())
                        .map_err(surface_goal_value_error)?,
                })
            })
            .transpose()?,
    })
}

fn surface_preparing_goal_run(
    record: &orca_core::goal_runtime::GoalRecord,
    goal_run_id: &orca_core::goal_runtime::GoalRunId,
    operation_id: &surface::SurfaceOperationId,
    origin: orca_core::goal_runtime::GoalTurnOrigin,
) -> Result<surface::SurfaceGoalRun, RuntimeHostError> {
    let stored_run =
        record
            .current_run
            .as_ref()
            .ok_or_else(|| RuntimeHostError::GoalControlFailed {
                message: "durable Goal mutation is missing its preparing run".to_string(),
            })?;
    if &stored_run.goal_run_id != goal_run_id
        || stored_run.origin != origin
        || stored_run.in_flight
        || stored_run.outer_turn_id.is_some()
        || stored_run.continuation_count != 0
    {
        return Err(RuntimeHostError::GoalControlFailed {
            message: "durable Goal mutation has an invalid preparing run".to_string(),
        });
    }
    surface_goal_run_binding(goal_run_id, operation_id, origin)
}

fn surface_goal_run_binding(
    goal_run_id: &orca_core::goal_runtime::GoalRunId,
    operation_id: &surface::SurfaceOperationId,
    origin: orca_core::goal_runtime::GoalTurnOrigin,
) -> Result<surface::SurfaceGoalRun, RuntimeHostError> {
    let run_origin = match origin {
        orca_core::goal_runtime::GoalTurnOrigin::User => surface::SurfaceGoalRunOrigin::User,
        orca_core::goal_runtime::GoalTurnOrigin::Resume => surface::SurfaceGoalRunOrigin::Resume,
        orca_core::goal_runtime::GoalTurnOrigin::WorkflowNotification => {
            surface::SurfaceGoalRunOrigin::WorkflowNotification
        }
        orca_core::goal_runtime::GoalTurnOrigin::Continuation => {
            return Err(RuntimeHostError::GoalControlFailed {
                message: "a continuation cannot start a new durable Goal run".to_string(),
            });
        }
    };
    Ok(surface::SurfaceGoalRun {
        goal_run_id: surface::SurfaceGoalRunId::try_new(goal_run_id.to_string())
            .map_err(surface_goal_value_error)?,
        run_origin,
        operation_id: operation_id.clone(),
        phase: surface::SurfaceGoalRunPhase::Preparing,
    })
}

fn surface_in_flight_goal_run(
    record: &orca_core::goal_runtime::GoalRecord,
    identity: &surface::SurfaceGoalGenerationIdentity,
) -> Result<surface::SurfaceGoalRun, RuntimeHostError> {
    let stored_run =
        record
            .current_run
            .as_ref()
            .ok_or_else(|| RuntimeHostError::GoalControlFailed {
                message: "durable Goal outer-turn mutation is missing its run".to_string(),
            })?;
    if stored_run.goal_run_id.as_str() != identity.goal_run_id.as_str()
        || !stored_run.in_flight
        || stored_run.continuation_count != identity.outer_turn_count
        || stored_run
            .outer_turn_id
            .as_ref()
            .is_none_or(|outer_turn_id| {
                outer_turn_id.as_str() != identity.goal_outer_turn_id.as_str()
            })
    {
        return Err(RuntimeHostError::GoalControlFailed {
            message: "durable Goal outer-turn row disagrees with its typed identity".to_string(),
        });
    }
    let mut run = surface_goal_run_binding(
        &stored_run.goal_run_id,
        &identity.operation_fence.operation_id,
        stored_run.origin,
    )?;
    let origin = match identity.outer_turn_origin {
        surface::GoalOuterTurnOrigin::User => surface::SurfaceGoalOuterTurnReceiptOrigin::User,
        surface::GoalOuterTurnOrigin::Resume => surface::SurfaceGoalOuterTurnReceiptOrigin::Resume,
        surface::GoalOuterTurnOrigin::Continuation => {
            surface::SurfaceGoalOuterTurnReceiptOrigin::Continuation
        }
        surface::GoalOuterTurnOrigin::WorkflowNotification => {
            surface::SurfaceGoalOuterTurnReceiptOrigin::WorkflowNotification
        }
    };
    run.phase = surface::SurfaceGoalRunPhase::InFlight {
        outer_turn: surface::SurfaceGoalOuterTurnReceipt {
            outer_turn_id: identity.goal_outer_turn_id.clone(),
            origin,
            outer_turn_count: identity.outer_turn_count,
        },
    };
    Ok(run)
}

fn surface_settled_goal_run(
    record: &orca_core::goal_runtime::GoalRecord,
    identity: &surface::SurfaceGoalGenerationIdentity,
) -> Result<surface::SurfaceGoalRun, RuntimeHostError> {
    let stored_run =
        record
            .current_run
            .as_ref()
            .ok_or_else(|| RuntimeHostError::GoalControlFailed {
                message: "durable Goal settlement is missing its run".to_string(),
            })?;
    if stored_run.goal_run_id.as_str() != identity.goal_run_id.as_str()
        || stored_run.in_flight
        || stored_run.outer_turn_id.is_some()
        || stored_run.continuation_count != identity.outer_turn_count
    {
        return Err(RuntimeHostError::GoalControlFailed {
            message: "durable Goal settlement row disagrees with its typed identity".to_string(),
        });
    }
    let mut run = surface_goal_run_binding(
        &stored_run.goal_run_id,
        &identity.operation_fence.operation_id,
        stored_run.origin,
    )?;
    let origin = match identity.outer_turn_origin {
        surface::GoalOuterTurnOrigin::User => surface::SurfaceGoalOuterTurnReceiptOrigin::User,
        surface::GoalOuterTurnOrigin::Resume => surface::SurfaceGoalOuterTurnReceiptOrigin::Resume,
        surface::GoalOuterTurnOrigin::Continuation => {
            surface::SurfaceGoalOuterTurnReceiptOrigin::Continuation
        }
        surface::GoalOuterTurnOrigin::WorkflowNotification => {
            surface::SurfaceGoalOuterTurnReceiptOrigin::WorkflowNotification
        }
    };
    run.phase = surface::SurfaceGoalRunPhase::Settled {
        last_outer_turn: Some(surface::SurfaceGoalOuterTurnReceipt {
            outer_turn_id: identity.goal_outer_turn_id.clone(),
            origin,
            outer_turn_count: identity.outer_turn_count,
        }),
    };
    Ok(run)
}

fn goal_surface_operation(
    mutation: &GoalSurfaceMutationRecord,
) -> Option<&surface::OperationRecord> {
    match &mutation.mutation {
        GoalSurfaceMutation::CreatedWithRun { operation, .. }
        | GoalSurfaceMutation::RunStarted { operation, .. } => Some(operation),
        GoalSurfaceMutation::Created
        | GoalSurfaceMutation::Edited { .. }
        | GoalSurfaceMutation::Removed { .. }
        | GoalSurfaceMutation::OuterTurnStarted { .. }
        | GoalSurfaceMutation::IntentRequested { .. }
        | GoalSurfaceMutation::IntentAcknowledged { .. }
        | GoalSurfaceMutation::OuterTurnFinished { .. }
        | GoalSurfaceMutation::VerificationCompleted { .. }
        | GoalSurfaceMutation::Paused { .. }
        | GoalSurfaceMutation::PausedQuiescent { .. }
        | GoalSurfaceMutation::ContinuationStopped { .. }
        | GoalSurfaceMutation::ContinuationAdmitted { .. }
        | GoalSurfaceMutation::Recovered { .. } => None,
    }
}

fn surface_goal_mutation_event(
    mutation: &GoalSurfaceMutationRecord,
    thread_id: surface::SurfaceThreadId,
) -> Result<
    (
        surface::SurfaceGoalFence,
        surface::Sha256Digest,
        surface::SurfaceCommitId,
        surface::SurfaceScope,
        surface::SurfaceEvent,
    ),
    RuntimeHostError,
> {
    let receipt = &mutation.receipt;
    let goal_id = surface::SurfaceGoalId::try_new(receipt.goal_id.to_string())
        .map_err(surface_goal_value_error)?;
    let goal_revision = surface::GoalRevision::try_new(u64::from(receipt.goal_revision))
        .map_err(surface_goal_value_error)?;
    let goal_owner_epoch = surface::GoalOwnerEpoch::try_new(receipt.goal_owner_epoch)
        .map_err(surface_goal_value_error)?;
    let catalog_revision =
        surface::GoalCatalogRevision::try_new(u64::from(receipt.catalog_revision))
            .map_err(surface_goal_value_error)?;
    let receipt_digest = surface::Sha256Digest::new(receipt.receipt_digest);
    let raw_commit_id = uuid::Uuid::parse_str(&receipt.store_commit_id).map_err(|error| {
        RuntimeHostError::GoalControlFailed {
            message: format!("invalid durable Goal commit identity: {error}"),
        }
    })?;
    let store_commit_id = surface::SurfaceCommitId::try_from_bytes(*raw_commit_id.as_bytes())
        .map_err(surface_goal_value_error)?;
    let (row_state, patch) = match (&receipt.row_state, &mutation.mutation) {
        (GoalSurfaceRowState::Present(record), GoalSurfaceMutation::Created) => {
            let goal = surface_goal_from_record(record, receipt, thread_id, None)?;
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: goal.state.clone(),
                    current_run: goal.current_run.clone(),
                },
                surface::GoalPatch::Created { goal },
            )
        }
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::CreatedWithRun {
                goal_run_id,
                operation,
                origin,
            },
        ) => {
            let goal_run =
                surface_preparing_goal_run(record, goal_run_id, &operation.operation_id, *origin)?;
            let goal =
                surface_goal_from_record(record, receipt, thread_id, Some(goal_run.clone()))?;
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: goal.state.clone(),
                    current_run: Some(goal_run),
                },
                surface::GoalPatch::Created { goal },
            )
        }
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::Edited { previous_revision },
        ) => {
            let goal = surface_goal_from_record(record, receipt, thread_id, None)?;
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: goal.state.clone(),
                    current_run: goal.current_run.clone(),
                },
                surface::GoalPatch::Edited {
                    goal_id: goal_id.clone(),
                    previous_revision: surface::GoalRevision::try_new(u64::from(
                        *previous_revision,
                    ))
                    .map_err(surface_goal_value_error)?,
                    goal,
                },
            )
        }
        (
            GoalSurfaceRowState::Removed,
            GoalSurfaceMutation::Removed {
                previous_revision,
                tombstone_revision,
            },
        ) => {
            let tombstone_revision = surface::GoalRevision::try_new(u64::from(*tombstone_revision))
                .map_err(surface_goal_value_error)?;
            (
                surface::SurfaceGoalReceiptState::Removed { tombstone_revision },
                surface::GoalPatch::Removed {
                    goal_id: goal_id.clone(),
                    previous_revision: surface::GoalRevision::try_new(u64::from(
                        *previous_revision,
                    ))
                    .map_err(surface_goal_value_error)?,
                    tombstone_revision,
                },
            )
        }
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::RunStarted {
                goal_run_id,
                operation,
                origin,
                ..
            },
        ) => {
            let goal_run =
                surface_preparing_goal_run(record, goal_run_id, &operation.operation_id, *origin)?;
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: surface_goal_state(&record.state)?,
                    current_run: Some(goal_run.clone()),
                },
                surface::GoalPatch::RunStarted {
                    goal_id: goal_id.clone(),
                    goal_run,
                },
            )
        }
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::OuterTurnStarted { identity, .. },
        ) => {
            let goal_run = surface_in_flight_goal_run(record, identity)?;
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: surface_goal_state(&record.state)?,
                    current_run: Some(goal_run),
                },
                surface::GoalPatch::OuterTurnStarted {
                    identity: identity.as_ref().clone(),
                },
            )
        }
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::IntentRequested {
                identity, intent, ..
            },
        ) => (
            surface::SurfaceGoalReceiptState::Present {
                state: surface_goal_state(&record.state)?,
                current_run: Some(surface_in_flight_goal_run(record, identity)?),
            },
            surface::GoalPatch::IntentRequested {
                goal_id: goal_id.clone(),
                outer_turn_id: identity.goal_outer_turn_id.clone(),
                intent: surface_goal_intent(intent)?,
            },
        ),
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::IntentAcknowledged {
                identity,
                intent,
                ack,
                ..
            },
        ) => (
            surface::SurfaceGoalReceiptState::Present {
                state: surface_goal_state(&record.state)?,
                current_run: Some(surface_in_flight_goal_run(record, identity)?),
            },
            surface::GoalPatch::IntentAcknowledged {
                goal_id: goal_id.clone(),
                outer_turn_id: identity.goal_outer_turn_id.clone(),
                intent: surface_goal_intent(intent)?,
                ack: surface_goal_intent_ack(ack)?,
            },
        ),
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::OuterTurnFinished {
                identity,
                status,
                usage,
                next_action,
                ..
            },
        ) => {
            let goal_run = surface_settled_goal_run(record, identity)?;
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: surface_goal_state(&record.state)?,
                    current_run: Some(goal_run),
                },
                surface::GoalPatch::OuterTurnFinished {
                    identity: identity.as_ref().clone(),
                    status: *status,
                    usage: usage.clone(),
                    next_action: *next_action,
                },
            )
        }
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::VerificationCompleted {
                identity, result, ..
            },
        ) => {
            let goal_run = surface_settled_goal_run(record, identity)?;
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: surface_goal_state(&record.state)?,
                    current_run: Some(goal_run),
                },
                surface::GoalPatch::VerificationCompleted {
                    identity: identity.as_ref().clone(),
                    result: result.clone(),
                },
            )
        }
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::Paused {
                goal_run_id,
                operation_id,
                outer_turn_id,
                ..
            },
        ) => {
            let stored_run =
                record
                    .current_run
                    .as_ref()
                    .ok_or_else(|| RuntimeHostError::GoalControlFailed {
                        message: "paused Goal receipt lost its current run".to_string(),
                    })?;
            if &stored_run.goal_run_id != goal_run_id
                || stored_run.outer_turn_id.as_ref() != outer_turn_id.as_ref()
            {
                return Err(RuntimeHostError::GoalControlFailed {
                    message: "paused Goal receipt disagrees with its run identity".to_string(),
                });
            }
            let mut goal_run =
                surface_goal_run_binding(goal_run_id, operation_id, stored_run.origin)?;
            goal_run.phase = match outer_turn_id {
                Some(outer_turn_id) => surface::SurfaceGoalRunPhase::InFlight {
                    outer_turn: surface::SurfaceGoalOuterTurnReceipt {
                        outer_turn_id: surface::SurfaceGoalOuterTurnId::try_new(
                            outer_turn_id.to_string(),
                        )
                        .map_err(surface_goal_value_error)?,
                        origin: match stored_run.origin {
                            orca_core::goal_runtime::GoalTurnOrigin::User => {
                                surface::SurfaceGoalOuterTurnReceiptOrigin::User
                            }
                            orca_core::goal_runtime::GoalTurnOrigin::Resume => {
                                surface::SurfaceGoalOuterTurnReceiptOrigin::Resume
                            }
                            orca_core::goal_runtime::GoalTurnOrigin::Continuation => {
                                surface::SurfaceGoalOuterTurnReceiptOrigin::Continuation
                            }
                            orca_core::goal_runtime::GoalTurnOrigin::WorkflowNotification => {
                                surface::SurfaceGoalOuterTurnReceiptOrigin::WorkflowNotification
                            }
                        },
                        outer_turn_count: stored_run.continuation_count,
                    },
                },
                None => surface::SurfaceGoalRunPhase::Preparing,
            };
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: surface_goal_state(&record.state)?,
                    current_run: Some(goal_run),
                },
                surface::GoalPatch::Paused {
                    goal_id: goal_id.clone(),
                    goal_run_id: Some(
                        surface::SurfaceGoalRunId::try_new(goal_run_id.to_string())
                            .map_err(surface_goal_value_error)?,
                    ),
                    outer_turn_id: outer_turn_id
                        .as_ref()
                        .map(|outer_turn_id| {
                            surface::SurfaceGoalOuterTurnId::try_new(outer_turn_id.to_string())
                                .map_err(surface_goal_value_error)
                        })
                        .transpose()?,
                    state: surface_goal_state(&record.state)?,
                },
            )
        }
        (GoalSurfaceRowState::Present(record), GoalSurfaceMutation::PausedQuiescent { .. }) => {
            if record.current_run.is_some() {
                return Err(RuntimeHostError::GoalControlFailed {
                    message: "quiescent paused Goal receipt retained a current run".to_string(),
                });
            }
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: surface_goal_state(&record.state)?,
                    current_run: None,
                },
                surface::GoalPatch::Paused {
                    goal_id: goal_id.clone(),
                    goal_run_id: None,
                    outer_turn_id: None,
                    state: surface_goal_state(&record.state)?,
                },
            )
        }
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::ContinuationStopped {
                predecessor,
                decision,
                ..
            },
        ) => {
            if record.current_run.is_some() {
                return Err(RuntimeHostError::GoalControlFailed {
                    message: "stopped Goal continuation retained an open run".to_string(),
                });
            }
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: surface_goal_state(&record.state)?,
                    current_run: None,
                },
                surface::GoalPatch::ContinuationDecided {
                    goal_id: goal_id.clone(),
                    predecessor: predecessor.as_ref().clone(),
                    decision: decision.as_ref().clone(),
                },
            )
        }
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::ContinuationAdmitted {
                predecessor,
                decision,
                ..
            },
        ) => {
            let surface::GoalContinuationDecision::Admitted { successor, .. } = decision.as_ref()
            else {
                return Err(RuntimeHostError::GoalControlFailed {
                    message: "admitted Goal continuation stored a stopped decision".to_string(),
                });
            };
            let goal_run = surface_in_flight_goal_run(record, successor)?;
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: surface_goal_state(&record.state)?,
                    current_run: Some(goal_run),
                },
                surface::GoalPatch::ContinuationDecided {
                    goal_id: goal_id.clone(),
                    predecessor: predecessor.as_ref().clone(),
                    decision: decision.as_ref().clone(),
                },
            )
        }
        (
            GoalSurfaceRowState::Present(record),
            GoalSurfaceMutation::Recovered {
                stale_goal_run_id,
                operation,
                origin,
                stale_identity,
                stale_run_settled,
                recovery_message,
                ..
            },
        ) => {
            if record.current_run.is_some() {
                return Err(RuntimeHostError::GoalControlFailed {
                    message: "recovered durable Goal still has an open run".to_string(),
                });
            }
            let mut stale_run =
                surface_goal_run_binding(stale_goal_run_id, &operation.operation_id, *origin)?;
            if let Some(identity) = stale_identity {
                let receipt_origin = match identity.outer_turn_origin {
                    surface::GoalOuterTurnOrigin::User => {
                        surface::SurfaceGoalOuterTurnReceiptOrigin::User
                    }
                    surface::GoalOuterTurnOrigin::Resume => {
                        surface::SurfaceGoalOuterTurnReceiptOrigin::Resume
                    }
                    surface::GoalOuterTurnOrigin::Continuation => {
                        surface::SurfaceGoalOuterTurnReceiptOrigin::Continuation
                    }
                    surface::GoalOuterTurnOrigin::WorkflowNotification => {
                        surface::SurfaceGoalOuterTurnReceiptOrigin::WorkflowNotification
                    }
                };
                let outer_turn = surface::SurfaceGoalOuterTurnReceipt {
                    outer_turn_id: identity.goal_outer_turn_id.clone(),
                    origin: receipt_origin,
                    outer_turn_count: identity.outer_turn_count,
                };
                stale_run.phase = if *stale_run_settled {
                    surface::SurfaceGoalRunPhase::Settled {
                        last_outer_turn: Some(outer_turn),
                    }
                } else {
                    surface::SurfaceGoalRunPhase::InFlight { outer_turn }
                };
            }
            (
                surface::SurfaceGoalReceiptState::Present {
                    state: surface_goal_state(&record.state)?,
                    current_run: None,
                },
                surface::GoalPatch::Recovered {
                    goal_id: goal_id.clone(),
                    stale_run: surface::SurfaceGoalClosedRunReceipt {
                        run: stale_run,
                        close_reason: surface::SurfaceGoalCloseReason::Recovery,
                        store_commit_id: store_commit_id.clone(),
                        receipt_digest: receipt_digest.clone(),
                    },
                    recovery_message: surface::DisplayText::new(recovery_message.clone()),
                    discarded_continuation: surface::DiscardedContinuation::new(),
                },
            )
        }
        _ => {
            return Err(RuntimeHostError::GoalControlFailed {
                message: "durable Goal mutation and row state disagree".to_string(),
            });
        }
    };
    let envelope = surface::GoalPatchEnvelope {
        receipt: surface::SurfaceGoalStoreReceipt {
            goal_id: goal_id.clone(),
            goal_revision,
            objective_revision: surface::GoalObjectiveRevision::new(receipt.objective_revision),
            catalog_revision,
            goal_owner_epoch,
            row_state,
            store_commit_id: store_commit_id.clone(),
            receipt_digest: receipt_digest.clone(),
        },
        patch,
    };
    let causative_generation = match &envelope.patch {
        surface::GoalPatch::OuterTurnStarted { identity }
        | surface::GoalPatch::OuterTurnFinished { identity, .. }
        | surface::GoalPatch::VerificationCompleted { identity, .. } => {
            Some(identity.operation_fence.clone())
        }
        surface::GoalPatch::ContinuationDecided { predecessor, .. } => {
            Some(predecessor.operation_fence.clone())
        }
        _ => None,
    };
    Ok((
        surface::SurfaceGoalFence {
            goal_id: goal_id.clone(),
            goal_revision,
            goal_owner_epoch,
        },
        receipt_digest,
        store_commit_id,
        surface::SurfaceScope::Goal {
            goal_id,
            causative_generation,
        },
        surface::SurfaceEvent::Goal(envelope),
    ))
}

fn runtime_surface_event_batch(
    snapshot: &surface::SurfaceSnapshot,
    events: Vec<(surface::SurfaceScope, surface::SurfaceEvent)>,
    commit_id: Option<surface::SurfaceCommitId>,
) -> surface::SurfaceCommitBatch {
    let cursor_before = snapshot.cursor.clone();
    let commit_id = commit_id.unwrap_or_else(|| {
        surface::SurfaceCommitId::try_from_bytes(*uuid::Uuid::now_v7().as_bytes())
            .expect("generated UUID is v7")
    });
    let (commit_class, source_revision) = match cursor_before.source_revision {
        surface::CursorSourceRevision::Recorded { durable_revision } => {
            let durable_revision = surface::DurableRevision::try_new(
                durable_revision
                    .get()
                    .checked_add(1)
                    .expect("surface durable revision did not exhaust"),
            )
            .expect("surface durable revision did not exhaust");
            (
                surface::CommitClass::Recorded {
                    thread_owner_epoch: snapshot.thread.owner_epoch,
                    durable_revision,
                    commit_id,
                },
                surface::CursorSourceRevision::Recorded { durable_revision },
            )
        }
        surface::CursorSourceRevision::Ephemeral { live_revision } => {
            let live_revision = surface::LiveRevision::try_new(
                live_revision
                    .get()
                    .checked_add(1)
                    .expect("surface live revision did not exhaust"),
            )
            .expect("surface live revision did not exhaust");
            (
                surface::CommitClass::Ephemeral {
                    incarnation: cursor_before.incarnation.clone(),
                    live_revision,
                    commit_id,
                },
                surface::CursorSourceRevision::Ephemeral { live_revision },
            )
        }
    };
    let events = events
        .into_iter()
        .enumerate()
        .map(|(ordinal, (scope, event))| surface::SurfaceEventEnvelope {
            ordinal: ordinal as u32,
            event_id: surface::SurfaceEventId::try_from_bytes(*uuid::Uuid::now_v7().as_bytes())
                .expect("generated UUID is v7"),
            commit_class: commit_class.clone(),
            scope,
            event,
        })
        .collect::<Vec<_>>();
    let event_count = events.len() as u32;
    let mut batch = surface::SurfaceCommitBatch {
        cursor_after: surface::SurfaceCursor {
            next_seq: surface::SequenceNumber::new(
                cursor_before.next_seq.get() + u64::from(event_count),
            ),
            source_revision,
            ..cursor_before.clone()
        },
        cursor_before,
        commit_class,
        event_count,
        batch_digest: surface::Sha256Digest::new([0; 32]),
        events: surface::NonEmptyVec::try_new(events).expect("surface batch is non-empty"),
    };
    batch.batch_digest = surface::canonical_batch_digest(&batch);
    batch
}

fn surface_tool_action(
    action: orca_core::approval_types::ActionKind,
) -> surface::SurfaceToolAction {
    match action {
        orca_core::approval_types::ActionKind::Read => surface::SurfaceToolAction::Read,
        orca_core::approval_types::ActionKind::Write => surface::SurfaceToolAction::Write,
        orca_core::approval_types::ActionKind::Network => surface::SurfaceToolAction::Network,
        orca_core::approval_types::ActionKind::Agent => surface::SurfaceToolAction::Agent,
        orca_core::approval_types::ActionKind::Shell => surface::SurfaceToolAction::Shell,
    }
}

fn surface_permission_paths(
    paths: Option<Vec<std::path::PathBuf>>,
) -> io::Result<Option<Vec<surface::SurfacePermissionPathLabel>>> {
    paths
        .map(|paths| {
            paths
                .into_iter()
                .map(|path| {
                    path.to_str()
                        .map(|path| {
                            surface::SurfacePermissionPathLabel(surface::DisplayText::new(path))
                        })
                        .ok_or_else(|| {
                            io::Error::new(
                                io::ErrorKind::InvalidInput,
                                "permission path is not lossless UTF-8",
                            )
                        })
                })
                .collect()
        })
        .transpose()
}

fn surface_permission_profile_from_runtime(
    profile: crate::protocol::RequestPermissionProfile,
) -> io::Result<surface::SurfacePermissionProfile> {
    let profile = profile.normalize_file_system_entries();
    let file_system = profile
        .file_system
        .map(|permissions| {
            Ok::<surface::SurfaceFileSystemPermissionProfile, io::Error>(
                surface::SurfaceFileSystemPermissionProfile {
                    read: surface_permission_paths(permissions.read)?,
                    write: surface_permission_paths(permissions.write)?,
                },
            )
        })
        .transpose()?;
    let network = profile.network.map(|permissions| {
        let mut domains = permissions.domains.into_iter().collect::<Vec<_>>();
        domains.sort_by(|left, right| left.0.cmp(&right.0));
        surface::SurfacePermissionNetworkProfile {
            enabled: permissions.enabled,
            domains: domains
                .into_iter()
                .map(|(domain, access)| {
                    (
                        surface::SurfacePermissionDomainPattern(surface::DisplayText::new(domain)),
                        match access {
                            orca_core::config::PermissionProfileNetworkAccess::Allow => {
                                surface::SurfaceAllowDeny::Allow
                            }
                            orca_core::config::PermissionProfileNetworkAccess::Deny => {
                                surface::SurfaceAllowDeny::Deny
                            }
                        },
                    )
                })
                .collect(),
        }
    });
    let shell = profile
        .shell
        .map(|permissions| surface::SurfaceShellPermissionProfile {
            unsandboxed: permissions.unsandboxed,
        });
    Ok(surface::SurfacePermissionProfile {
        file_system,
        network,
        shell,
    })
}

fn runtime_permission_profile_from_surface(
    profile: &surface::SurfacePermissionProfile,
) -> crate::protocol::RequestPermissionProfile {
    let file_system = profile.file_system.as_ref().map(|permissions| {
        crate::protocol::RequestFileSystemPermissions {
            read: permissions.read.as_ref().map(|paths| {
                paths
                    .iter()
                    .map(|path| std::path::PathBuf::from(path.0.as_str()))
                    .collect()
            }),
            write: permissions.write.as_ref().map(|paths| {
                paths
                    .iter()
                    .map(|path| std::path::PathBuf::from(path.0.as_str()))
                    .collect()
            }),
            entries: None,
        }
    });
    let network =
        profile
            .network
            .as_ref()
            .map(|permissions| crate::protocol::RequestNetworkPermissions {
                enabled: permissions.enabled,
                domains: permissions
                    .domains
                    .iter()
                    .map(|(domain, access)| {
                        (
                            domain.0.as_str().to_string(),
                            match access {
                                surface::SurfaceAllowDeny::Allow => {
                                    orca_core::config::PermissionProfileNetworkAccess::Allow
                                }
                                surface::SurfaceAllowDeny::Deny => {
                                    orca_core::config::PermissionProfileNetworkAccess::Deny
                                }
                            },
                        )
                    })
                    .collect(),
            });
    let shell =
        profile
            .shell
            .as_ref()
            .map(|permissions| crate::protocol::RequestShellPermissions {
                unsandboxed: permissions.unsandboxed,
            });
    crate::protocol::RequestPermissionProfile {
        file_system,
        network,
        shell,
    }
}

fn permission_path_subset(
    candidate: Option<&Vec<surface::SurfacePermissionPathLabel>>,
    requested: Option<&Vec<surface::SurfacePermissionPathLabel>>,
) -> bool {
    candidate.is_none_or(|candidate| {
        let requested = requested
            .into_iter()
            .flatten()
            .map(|path| path.0.as_str())
            .collect::<BTreeSet<_>>();
        candidate
            .iter()
            .all(|path| requested.contains(path.0.as_str()))
    })
}

fn surface_permission_profile_is_subset(
    candidate: &surface::SurfacePermissionProfile,
    requested: &surface::SurfacePermissionProfile,
) -> bool {
    let file_system_subset = candidate.file_system.as_ref().is_none_or(|candidate| {
        requested.file_system.as_ref().is_some_and(|requested| {
            permission_path_subset(candidate.read.as_ref(), requested.read.as_ref())
                && permission_path_subset(candidate.write.as_ref(), requested.write.as_ref())
        })
    });
    let network_subset = candidate.network.as_ref().is_none_or(|candidate| {
        requested.network.as_ref().is_some_and(|requested| {
            let enabled_subset = match candidate.enabled {
                None | Some(false) => true,
                Some(true) => requested.enabled == Some(true),
            };
            let requested_domains = requested
                .domains
                .iter()
                .map(|(domain, access)| (domain.0.as_str(), *access))
                .collect::<HashMap<_, _>>();
            enabled_subset
                && candidate.domains.iter().all(|(domain, access)| {
                    requested_domains.get(domain.0.as_str()) == Some(access)
                })
        })
    });
    let shell_subset = candidate.shell.as_ref().is_none_or(|candidate| {
        !candidate.unsandboxed
            || requested
                .shell
                .as_ref()
                .is_some_and(|requested| requested.unsandboxed)
    });
    file_system_subset && network_subset && shell_subset
}

fn surface_session_permission_grant_is_applied(
    settings: &surface::SurfaceRuntimeSettings,
    permissions: &surface::SurfacePermissionProfile,
) -> bool {
    let paths_applied = permissions.file_system.as_ref().is_none_or(|file_system| {
        file_system
            .read
            .iter()
            .flatten()
            .chain(file_system.write.iter().flatten())
            .all(|path| {
                surface::CanonicalPath::try_new(std::path::PathBuf::from(path.0.as_str()))
                    .ok()
                    .is_some_and(|path| {
                        settings
                            .additional_working_directories
                            .iter()
                            .any(|directory| directory.path == path)
                    })
            })
    });
    let network_applied = permissions.network.as_ref().is_none_or(|requested| {
        let enabled = requested
            .enabled
            .is_none_or(|enabled| settings.network_permissions.enabled == Some(enabled));
        enabled
            && requested.domains.iter().all(|(domain, access)| {
                settings
                    .network_permissions
                    .domains
                    .iter()
                    .any(|permission| {
                        permission.domain.as_str() == domain.0.as_str()
                            && permission.access
                                == match access {
                                    surface::SurfaceAllowDeny::Allow => {
                                        surface::SurfaceNetworkDomainAccess::Allow
                                    }
                                    surface::SurfaceAllowDeny::Deny => {
                                        surface::SurfaceNetworkDomainAccess::Deny
                                    }
                                }
                    })
            })
    });
    let shell_applied = permissions
        .shell
        .as_ref()
        .is_none_or(|shell| !shell.unsandboxed);
    paths_applied && network_applied && shell_applied
}

fn surface_session_permission_settings_delta_authorized(
    current: &surface::SurfaceRuntimeSettings,
    next: &surface::SurfaceRuntimeSettings,
    requested: &surface::SurfacePermissionProfile,
) -> bool {
    if current.model != next.model
        || current.reasoning_effort != next.reasoning_effort
        || current.approval_mode != next.approval_mode
        || current.cwd != next.cwd
        || current.workspace_roots != next.workspace_roots
        || current.active_permission_profile != next.active_permission_profile
        || current.permission_rules != next.permission_rules
    {
        return false;
    }
    if current
        .additional_working_directories
        .iter()
        .any(|directory| !next.additional_working_directories.contains(directory))
    {
        return false;
    }
    let requested_paths = requested
        .file_system
        .iter()
        .flat_map(|file_system| {
            file_system
                .read
                .iter()
                .flatten()
                .chain(file_system.write.iter().flatten())
        })
        .filter_map(|path| {
            surface::CanonicalPath::try_new(std::path::PathBuf::from(path.0.as_str())).ok()
        })
        .collect::<BTreeSet<_>>();
    if next
        .additional_working_directories
        .iter()
        .filter(|directory| !current.additional_working_directories.contains(directory))
        .any(|directory| {
            directory.source.as_str() != "session" || !requested_paths.contains(&directory.path)
        })
    {
        return false;
    }
    let requested_network = requested.network.as_ref();
    if current.network_permissions.enabled != next.network_permissions.enabled
        && requested_network.and_then(|network| network.enabled) != next.network_permissions.enabled
    {
        return false;
    }
    let requested_domains = requested_network
        .into_iter()
        .flat_map(|network| network.domains.iter())
        .map(|(domain, access)| {
            (
                domain.0.as_str(),
                match access {
                    surface::SurfaceAllowDeny::Allow => surface::SurfaceNetworkDomainAccess::Allow,
                    surface::SurfaceAllowDeny::Deny => surface::SurfaceNetworkDomainAccess::Deny,
                },
            )
        })
        .collect::<HashMap<_, _>>();
    let current_domains = current
        .network_permissions
        .domains
        .iter()
        .map(|permission| (permission.domain.as_str(), permission.access))
        .collect::<HashMap<_, _>>();
    next.network_permissions.domains.iter().all(|permission| {
        current_domains.get(permission.domain.as_str()) == Some(&permission.access)
            || requested_domains.get(permission.domain.as_str()) == Some(&permission.access)
    }) && current
        .network_permissions
        .domains
        .iter()
        .all(|permission| {
            next.network_permissions
                .domains
                .iter()
                .any(|next| next.domain == permission.domain)
        })
}

const PRIVATE_INTERACTION_ANSWER_DEPTH_LIMIT: usize = 64;
const PRIVATE_INTERACTION_ANSWER_NODE_LIMIT: usize = 16_384;

struct BoundedAnswerWriter {
    written: u64,
}

impl io::Write for BoundedAnswerWriter {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        let next = self
            .written
            .checked_add(bytes.len() as u64)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "answer is too large"))?;
        if next > surface::SURFACE_COMMIT_BATCH_BYTE_LIMIT {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "answer is too large",
            ));
        }
        self.written = next;
        Ok(bytes.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

fn surface_data_within_private_limits(value: &surface::SurfaceDataValue) -> bool {
    let mut stack = vec![(value, 1_usize)];
    let mut nodes = 0_usize;
    while let Some((value, depth)) = stack.pop() {
        if depth > PRIVATE_INTERACTION_ANSWER_DEPTH_LIMIT {
            return false;
        }
        nodes = nodes.saturating_add(1);
        if nodes > PRIVATE_INTERACTION_ANSWER_NODE_LIMIT {
            return false;
        }
        match value {
            surface::SurfaceDataValue::Array(values) => {
                stack.extend(values.iter().map(|value| (value, depth + 1)));
            }
            surface::SurfaceDataValue::Object(properties) => {
                stack.extend(
                    properties
                        .iter()
                        .map(|property| (property.value.as_ref(), depth + 1)),
                );
            }
            surface::SurfaceDataValue::Null
            | surface::SurfaceDataValue::Boolean(_)
            | surface::SurfaceDataValue::Integer(_)
            | surface::SurfaceDataValue::Unsigned(_)
            | surface::SurfaceDataValue::Number(_)
            | surface::SurfaceDataValue::String(_) => {}
        }
    }
    true
}

fn interaction_answer_within_private_limits(
    answer: &surface::SurfaceClientInteractionAnswer,
) -> bool {
    if let surface::SurfaceClientInteractionAnswer::McpElicitation {
        decision: surface::SurfaceMcpElicitationDecision::Accept { content },
    } = answer
        && !surface_data_within_private_limits(content)
    {
        return false;
    }
    serde_json::to_writer(&mut BoundedAnswerWriter { written: 0 }, answer).is_ok()
}

fn interaction_answer_kind(
    answer: &surface::SurfaceClientInteractionAnswer,
) -> surface::SurfaceInteractionKind {
    match answer {
        surface::SurfaceClientInteractionAnswer::ToolApproval { .. } => {
            surface::SurfaceInteractionKind::ToolApproval
        }
        surface::SurfaceClientInteractionAnswer::PermissionRequest { .. } => {
            surface::SurfaceInteractionKind::PermissionRequest
        }
        surface::SurfaceClientInteractionAnswer::UserInput { .. } => {
            surface::SurfaceInteractionKind::UserInput
        }
        surface::SurfaceClientInteractionAnswer::McpElicitation { .. } => {
            surface::SurfaceInteractionKind::McpElicitation
        }
        surface::SurfaceClientInteractionAnswer::BackgroundApproval { .. } => {
            surface::SurfaceInteractionKind::BackgroundApproval
        }
    }
}

fn interaction_answer_authority(
    request: &surface::SurfaceInteractionRequest,
    answer: &surface::SurfaceClientInteractionAnswer,
) -> surface::ApplicableAuthorityFingerprint {
    match (request, answer) {
        (
            surface::SurfaceInteractionRequest::ToolApproval { authority, .. },
            surface::SurfaceClientInteractionAnswer::ToolApproval {
                decision: surface::SurfaceAllowDeny::Allow,
            },
        )
        | (
            surface::SurfaceInteractionRequest::PermissionRequest { authority, .. },
            surface::SurfaceClientInteractionAnswer::PermissionRequest {
                decision: surface::SurfacePermissionClientDecision::Allow { .. },
            },
        )
        | (
            surface::SurfaceInteractionRequest::BackgroundApproval { authority, .. },
            surface::SurfaceClientInteractionAnswer::BackgroundApproval {
                decision: surface::SurfaceAllowDeny::Allow,
            },
        ) => surface::ApplicableAuthorityFingerprint::persisted(authority.clone()),
        _ => surface::ApplicableAuthorityFingerprint::not_applicable(),
    }
}

fn interaction_answer_authority_matches(
    request: &surface::SurfaceInteractionRequest,
    answer: &surface::SurfaceClientInteractionAnswer,
    actual: &surface::ApplicableAuthorityFingerprint,
) -> bool {
    interaction_answer_authority(request, answer).authority() == actual.authority()
}

fn interaction_safe_projection(
    answer: &surface::SurfaceClientInteractionAnswer,
) -> surface::SurfaceInteractionSafeProjection {
    match answer {
        surface::SurfaceClientInteractionAnswer::ToolApproval { decision } => {
            surface::SurfaceInteractionSafeProjection::ToolApproval {
                allowed: *decision == surface::SurfaceAllowDeny::Allow,
            }
        }
        surface::SurfaceClientInteractionAnswer::PermissionRequest { decision } => {
            let (decision, scope, strict_auto_review) = match decision {
                surface::SurfacePermissionClientDecision::Allow {
                    scope,
                    strict_auto_review,
                    ..
                } => (
                    surface::SurfaceAllowDeny::Allow,
                    *scope,
                    *strict_auto_review,
                ),
                surface::SurfacePermissionClientDecision::Deny {
                    scope,
                    strict_auto_review,
                    ..
                } => (surface::SurfaceAllowDeny::Deny, *scope, *strict_auto_review),
            };
            surface::SurfaceInteractionSafeProjection::PermissionRequest {
                decision,
                scope,
                strict_auto_review,
            }
        }
        surface::SurfaceClientInteractionAnswer::UserInput { decision } => {
            surface::SurfaceInteractionSafeProjection::UserInput {
                answered: matches!(decision, surface::SurfaceUserInputDecision::Answer(_)),
            }
        }
        surface::SurfaceClientInteractionAnswer::McpElicitation { decision } => {
            surface::SurfaceInteractionSafeProjection::McpElicitation {
                accepted: matches!(
                    decision,
                    surface::SurfaceMcpElicitationDecision::Accept { .. }
                ),
            }
        }
        surface::SurfaceClientInteractionAnswer::BackgroundApproval { decision } => {
            surface::SurfaceInteractionSafeProjection::BackgroundApproval {
                allowed: *decision == surface::SurfaceAllowDeny::Allow,
            }
        }
    }
}

fn surface_data_from_json(value: &Value) -> Result<surface::SurfaceDataValue, String> {
    match value {
        Value::Null => Ok(surface::SurfaceDataValue::Null),
        Value::Bool(value) => Ok(surface::SurfaceDataValue::Boolean(*value)),
        Value::Number(value) => {
            if let Some(value) = value.as_u64() {
                Ok(surface::SurfaceDataValue::Unsigned(value))
            } else if let Some(value) = value.as_i64() {
                surface::NegativeI64::try_new(value)
                    .map(surface::SurfaceDataValue::Integer)
                    .map_err(|error| format!("invalid negative integer: {error:?}"))
            } else {
                surface::FiniteF64::try_new(
                    value
                        .as_f64()
                        .ok_or_else(|| "JSON number is not representable as f64".to_string())?,
                )
                .map(surface::SurfaceDataValue::Number)
                .map_err(|error| format!("non-finite JSON number: {error:?}"))
            }
        }
        Value::String(value) => Ok(surface::SurfaceDataValue::String(
            surface::DisplayText::new(value.clone()),
        )),
        Value::Array(values) => values
            .iter()
            .map(surface_data_from_json)
            .collect::<Result<Vec<_>, _>>()
            .map(surface::SurfaceDataValue::Array),
        Value::Object(properties) => properties
            .iter()
            .map(|(name, value)| {
                Ok(surface::SurfaceDataProperty {
                    name: surface::DisplayText::new(name.clone()),
                    value: Box::new(surface_data_from_json(value)?),
                })
            })
            .collect::<Result<Vec<_>, String>>()
            .map(surface::SurfaceDataValue::Object),
    }
}

fn json_from_surface_data(value: &surface::SurfaceDataValue) -> Value {
    match value {
        surface::SurfaceDataValue::Null => Value::Null,
        surface::SurfaceDataValue::Boolean(value) => Value::Bool(*value),
        surface::SurfaceDataValue::Integer(value) => Value::Number(value.get().into()),
        surface::SurfaceDataValue::Unsigned(value) => Value::Number((*value).into()),
        surface::SurfaceDataValue::Number(value) => serde_json::Number::from_f64(value.get())
            .map(Value::Number)
            .expect("surface number is finite"),
        surface::SurfaceDataValue::String(value) => Value::String(value.as_str().to_string()),
        surface::SurfaceDataValue::Array(values) => {
            Value::Array(values.iter().map(json_from_surface_data).collect())
        }
        surface::SurfaceDataValue::Object(properties) => Value::Object(
            properties
                .iter()
                .map(|property| {
                    (
                        property.name.as_str().to_string(),
                        json_from_surface_data(&property.value),
                    )
                })
                .collect(),
        ),
    }
}

fn interaction_route_attachments(
    route: &surface::BrokerInteractionResponseRoute,
) -> Vec<surface::SurfaceAttachmentId> {
    match route {
        surface::BrokerInteractionResponseRoute::Unassigned { .. } => Vec::new(),
        surface::BrokerInteractionResponseRoute::Exclusive { attachment_id, .. } => {
            vec![attachment_id.clone()]
        }
        surface::BrokerInteractionResponseRoute::SharedFirstCommitWins { grants, .. } => grants
            .as_slice()
            .iter()
            .map(|(attachment_id, _)| attachment_id.clone())
            .collect(),
    }
}

fn interaction_route_admits(
    route: &surface::BrokerInteractionResponseRoute,
    attachment_id: &surface::SurfaceAttachmentId,
) -> bool {
    match route {
        surface::BrokerInteractionResponseRoute::Unassigned { .. } => false,
        surface::BrokerInteractionResponseRoute::Exclusive {
            attachment_id: expected,
            ..
        } => expected == attachment_id,
        surface::BrokerInteractionResponseRoute::SharedFirstCommitWins { grants, .. } => grants
            .as_slice()
            .iter()
            .any(|(expected, _)| expected == attachment_id),
    }
}

fn interaction_route_admits_exact(
    route: &surface::BrokerInteractionResponseRoute,
    attachment_id: &surface::SurfaceAttachmentId,
    route_epoch: surface::ResponseRouteEpoch,
    grant_token: &surface::SurfaceResponseGrantToken,
) -> bool {
    match route {
        surface::BrokerInteractionResponseRoute::Unassigned { .. } => false,
        surface::BrokerInteractionResponseRoute::Exclusive {
            epoch,
            attachment_id: expected_attachment,
            grant_token: expected_grant,
        } => {
            *epoch == route_epoch
                && expected_attachment == attachment_id
                && expected_grant == grant_token
        }
        surface::BrokerInteractionResponseRoute::SharedFirstCommitWins {
            epoch, grants, ..
        } => {
            *epoch == route_epoch
                && grants
                    .as_slice()
                    .iter()
                    .any(|(expected_attachment, expected_grant)| {
                        expected_attachment == attachment_id && expected_grant == grant_token
                    })
        }
    }
}

fn interaction_route_epoch(
    route: &surface::BrokerInteractionResponseRoute,
) -> surface::ResponseRouteEpoch {
    match route {
        surface::BrokerInteractionResponseRoute::Unassigned { epoch }
        | surface::BrokerInteractionResponseRoute::Exclusive { epoch, .. }
        | surface::BrokerInteractionResponseRoute::SharedFirstCommitWins { epoch, .. } => *epoch,
    }
}

fn exact_interaction_selectors(
    interaction: &ResidentSurfaceInteraction,
) -> Vec<(surface::SurfaceAttachmentId, surface::InteractionSelector)> {
    let grants = match &interaction.route {
        surface::BrokerInteractionResponseRoute::Unassigned { .. } => Vec::new(),
        surface::BrokerInteractionResponseRoute::Exclusive {
            epoch,
            attachment_id,
            grant_token,
        } => vec![(attachment_id.clone(), *epoch, grant_token.clone())],
        surface::BrokerInteractionResponseRoute::SharedFirstCommitWins {
            epoch, grants, ..
        } => grants
            .as_slice()
            .iter()
            .map(|(attachment_id, grant_token)| {
                (attachment_id.clone(), *epoch, grant_token.clone())
            })
            .collect(),
    };
    grants
        .into_iter()
        .map(
            |(attachment_id, response_route_epoch, response_grant_token)| {
                (
                    attachment_id,
                    surface::InteractionSelector::Exact {
                        interaction_id: interaction.record.interaction_id.clone(),
                        expected_revision: interaction.revision,
                        kind: interaction.record.kind,
                        response_token: interaction.record.response_token.clone(),
                        response_route_epoch,
                        response_grant_token,
                        operation_fence: interaction.record.fence.clone(),
                    },
                )
            },
        )
        .collect()
}

#[cfg(test)]
fn exact_interaction_selector_for_test(
    state: &ResidentSurfaceState,
    operation_id: &surface::SurfaceOperationId,
) -> Option<surface::InteractionSelector> {
    state
        .interactions
        .values()
        .find(|interaction| &interaction.record.fence.operation_id == operation_id)
        .and_then(|interaction| exact_interaction_selectors(interaction).into_iter().next())
        .map(|(_, selector)| selector)
}

#[cfg(test)]
fn pending_capability_loss_for_test(
    state: &ResidentSurfaceState,
) -> Option<PendingCapabilityLossTestProbe> {
    state
        .pending_capability_losses
        .iter()
        .min_by_key(|(attachment_id, _)| (*attachment_id).clone())
        .map(|(attachment_id, pending)| PendingCapabilityLossTestProbe {
            attachment_id: attachment_id.clone(),
            commit_id: pending.transition.commit_id.clone(),
            cursor_after: pending.transition.batch.cursor_after.clone(),
            batch_digest: pending.transition.batch.batch_digest.clone(),
        })
}

#[cfg(test)]
fn pending_terminalization_for_test(
    state: &ResidentSurfaceState,
) -> Option<PendingTerminalizationTestProbe> {
    state.commit.inspect_terminalization(|pending| {
        let surface::CommitClass::Recorded { commit_id, .. } = &pending.batch.commit_class else {
            unreachable!("recorded runtime surface used ephemeral commit class")
        };
        PendingTerminalizationTestProbe {
            commit_id: commit_id.clone(),
            cursor_before: pending.batch.cursor_before.clone(),
            cursor_after: pending.batch.cursor_after.clone(),
            batch_digest: pending.batch.batch_digest.clone(),
        }
    })
}

