    impl ThreadOperationExecutor for SurfaceGoalUpdateExecutor {
        fn run_turn(
            &self,
            thread: &mut RuntimeThread,
            request: &HostedTurnRequest,
            generation: &GenerationContext,
            events: &mut EventFactory,
            writer: &mut (dyn io::Write + Send),
            cancel: &CancelToken,
        ) -> io::Result<ThreadOperationOutcome> {
            let tool = ToolRequest {
                id: "surface-goal-complete".to_string(),
                name: ToolName::UpdateGoal,
                action: ActionKind::Read,
                target: None,
                raw_arguments: Some(
                    r#"{"status":"complete","reason":"fixture verified","evidence":[{"kind":"observation","summary":"surface Goal integration fixture passed","target":"runtime_host"}]}"#
                        .to_string(),
                ),
            };
            let continuation = RuntimeTurnContinuation::from_response(
                ProviderResponse {
                    steps: vec![ProviderStep::ToolCall(tool.clone())],
                    assistant_content: Some("Completing the runtime-owned Goal.".to_string()),
                    assistant_reasoning: None,
                    tool_calls: vec![orca_core::conversation::RawToolCall {
                        id: tool.id.clone(),
                        function_name: tool.name.as_str().to_string(),
                        arguments: tool.raw_arguments.clone().unwrap_or_default(),
                    }],
                    usage: None,
                },
                request.turn_id().clone(),
            );
            let turn_request = request
                .thread_turn_request(generation)
                .with_continuation(continuation);
            thread
                .run_request_with_event_factory_and_cancel_outcome_unbound(
                    generation.config(),
                    &turn_request,
                    writer,
                    events,
                    cancel.clone(),
                )
                .map(|outcome| match outcome {
                    crate::controller::ThreadTurnOutcome::Completed {
                        status,
                        end_reason,
                        background_workflows,
                        terminal,
                    } => ThreadOperationOutcome::Completed {
                        status,
                        end_reason,
                        background_workflows,
                        terminal,
                    },
                    crate::controller::ThreadTurnOutcome::ProviderSuspended {
                        suspension,
                        background_workflows,
                    } => ThreadOperationOutcome::ProviderSuspended {
                        suspension,
                        background_workflows,
                    },
                })
        }
    }

    impl ThreadOperationExecutor for SurfaceGoalContinueThenUpdateExecutor {
        fn run_turn(
            &self,
            thread: &mut RuntimeThread,
            request: &HostedTurnRequest,
            generation: &GenerationContext,
            events: &mut EventFactory,
            writer: &mut (dyn io::Write + Send),
            cancel: &CancelToken,
        ) -> io::Result<ThreadOperationOutcome> {
            let call = self.calls.fetch_add(1, Ordering::SeqCst);
            assert!(
                call < 2,
                "Goal continuation admitted an unexpected third turn"
            );
            if call == 0 {
                thread.lifecycle_mut().finish_task(RunStatus::Failed);
                return Ok(ThreadOperationOutcome::Completed {
                    status: RunStatus::Failed,
                    end_reason: crate::lifecycle::TurnEndReason::Unclassified,
                    background_workflows: RuntimeBackgroundWorkflows::from_vec(Vec::new()),
                    terminal: Some(orca_core::budget::OperationTerminal::Stopped {
                        reason: orca_core::budget::StopReason::TurnBudget { max_turns: 1 },
                        usage: orca_core::budget::BudgetUsage::default(),
                        checkpoint_id: "surface-goal-continuation".to_string(),
                        resumable: true,
                    }),
                });
            }
            SurfaceGoalUpdateExecutor.run_turn(thread, request, generation, events, writer, cancel)
        }
    }

    impl ThreadOperationExecutor for SurfaceGoalPlanThenUpdateExecutor {
        fn run_turn(
            &self,
            thread: &mut RuntimeThread,
            request: &HostedTurnRequest,
            generation: &GenerationContext,
            events: &mut EventFactory,
            writer: &mut (dyn io::Write + Send),
            cancel: &CancelToken,
        ) -> io::Result<ThreadOperationOutcome> {
            let call = self.calls.fetch_add(1, Ordering::SeqCst);
            assert!(
                call < 2,
                "plan-only Goal continuation admitted an unexpected third turn"
            );
            if call == 0 {
                thread
                    .session_mut()
                    .conversation_mut()
                    .replace_plan_state("[in_progress] finish typed Goal projection".to_string());
                thread.lifecycle_mut().finish_task(RunStatus::Success);
                return Ok(RunStatus::Success.into());
            }
            SurfaceGoalUpdateExecutor.run_turn(thread, request, generation, events, writer, cancel)
        }
    }

    impl ThreadOperationExecutor for SurfaceGoalCostBudgetExecutor {
        fn run_turn(
            &self,
            thread: &mut RuntimeThread,
            _request: &HostedTurnRequest,
            _generation: &GenerationContext,
            _events: &mut EventFactory,
            _writer: &mut (dyn io::Write + Send),
            _cancel: &CancelToken,
        ) -> io::Result<ThreadOperationOutcome> {
            thread.lifecycle_mut().finish_task(RunStatus::Failed);
            Ok(ThreadOperationOutcome::Completed {
                status: RunStatus::Failed,
                end_reason: crate::lifecycle::TurnEndReason::CostBudgetExhausted,
                background_workflows: RuntimeBackgroundWorkflows::from_vec(Vec::new()),
                terminal: Some(orca_core::budget::OperationTerminal::Stopped {
                    reason: orca_core::budget::StopReason::CostBudget {
                        max_cost_usd_micros: 1_000,
                    },
                    usage: orca_core::budget::BudgetUsage::default(),
                    checkpoint_id: String::new(),
                    resumable: false,
                }),
            })
        }
    }

    impl ThreadOperationExecutor for SurfaceGoalApprovalExecutor {
        fn run_turn(
            &self,
            thread: &mut RuntimeThread,
            request: &HostedTurnRequest,
            generation: &GenerationContext,
            events: &mut EventFactory,
            writer: &mut (dyn io::Write + Send),
            cancel: &CancelToken,
        ) -> io::Result<ThreadOperationOutcome> {
            thread
                .session_mut()
                .cost_tracker_mut()
                .add_usage(orca_core::provider_types::Usage {
                    input_tokens: 7,
                    output_tokens: 3,
                    cache_tokens: 0,
                });
            let turn_id = request.turn_id().as_str();
            let approval_tool = ToolRequest {
                id: format!("goal-approval-tool-{turn_id}"),
                name: ToolName::WriteFile,
                action: ActionKind::Write,
                target: Some(self.marker_path.display().to_string()),
                raw_arguments: Some(
                    serde_json::json!({
                        "path": self.marker_path,
                        "content": "allowed"
                    })
                    .to_string(),
                ),
            };
            let update_goal_tool = ToolRequest {
                id: format!("goal-approval-complete-{turn_id}"),
                name: ToolName::UpdateGoal,
                action: ActionKind::Read,
                target: None,
                raw_arguments: Some(
                    r#"{"status":"complete","reason":"approved Goal tool completed","evidence":[{"kind":"observation","summary":"typed Goal approval fixture passed","target":"runtime_host"}]}"#
                        .to_string(),
                ),
            };
            let continuation = RuntimeTurnContinuation::from_response(
                ProviderResponse {
                    steps: vec![
                        ProviderStep::ToolCall(approval_tool.clone()),
                        ProviderStep::ToolCall(update_goal_tool.clone()),
                    ],
                    assistant_content: Some("Completing the approved Goal operation.".to_string()),
                    assistant_reasoning: None,
                    tool_calls: [&approval_tool, &update_goal_tool]
                        .into_iter()
                        .map(|tool| orca_core::conversation::RawToolCall {
                            id: tool.id.clone(),
                            function_name: tool.name.as_str().to_string(),
                            arguments: tool.raw_arguments.clone().unwrap_or_default(),
                        })
                        .collect(),
                    usage: None,
                },
                request.turn_id().clone(),
            );
            let turn_request = request
                .thread_turn_request(generation)
                .with_continuation(continuation);
            thread
                .run_request_with_event_factory_and_cancel_outcome_unbound(
                    generation.config(),
                    &turn_request,
                    writer,
                    events,
                    cancel.clone(),
                )
                .map(|outcome| match outcome {
                    crate::controller::ThreadTurnOutcome::Completed {
                        status,
                        end_reason,
                        background_workflows,
                        terminal,
                    } => ThreadOperationOutcome::Completed {
                        status,
                        end_reason,
                        background_workflows,
                        terminal,
                    },
                    crate::controller::ThreadTurnOutcome::ProviderSuspended {
                        suspension,
                        background_workflows,
                    } => ThreadOperationOutcome::ProviderSuspended {
                        suspension,
                        background_workflows,
                    },
                })
        }
    }

