    fn collect_surface_interaction_route(
        receiver: &mut surface::SurfaceSubscriptionReceiver,
        interaction_id: &surface::SurfaceInteractionId,
    ) -> surface::SurfaceInteractionRoute {
        let deadline = Instant::now() + SURFACE_TEST_TIMEOUT;
        loop {
            while let Some(item) = receiver.try_recv() {
                if let surface::SurfaceSubscriptionItem::Batch { batch } = item {
                    for event in batch.events.as_slice() {
                        if let surface::SurfaceEvent::Interaction(
                            surface::InteractionPatch::RouteChanged {
                                interaction_id: candidate,
                                route,
                                ..
                            },
                        ) = &event.event
                            && candidate == interaction_id
                        {
                            return route.clone();
                        }
                    }
                }
            }
            assert!(
                Instant::now() < deadline,
                "typed interaction route change was not published"
            );
            std::thread::yield_now();
        }
    }

    fn corrupt_exact_selector(
        mut selector: surface::InteractionSelector,
        corruption: ExactSelectorCorruption,
    ) -> surface::InteractionSelector {
        let surface::InteractionSelector::Exact {
            expected_revision,
            response_token,
            response_route_epoch,
            response_grant_token,
            operation_fence,
            ..
        } = &mut selector
        else {
            panic!("actor probe returned an opaque selector")
        };
        match corruption {
            ExactSelectorCorruption::Revision => {
                *expected_revision =
                    surface::InteractionRevision::try_new(expected_revision.get() + 1)
                        .expect("test interaction revision did not exhaust");
            }
            ExactSelectorCorruption::ResponseToken => {
                let mut bytes = *response_token.key_bytes();
                bytes[0] ^= 0xff;
                *response_token = surface::SurfaceResponseToken::new(bytes);
            }
            ExactSelectorCorruption::RouteEpoch => {
                *response_route_epoch =
                    surface::ResponseRouteEpoch::try_new(response_route_epoch.get() + 1)
                        .expect("test route epoch did not exhaust");
            }
            ExactSelectorCorruption::OperationFence => {
                operation_fence.generation_id =
                    surface::SurfaceGenerationId::new(operation_fence.generation_id.get() + 1);
            }
            ExactSelectorCorruption::GrantToken => {
                let mut bytes = *response_grant_token.key_bytes();
                bytes[0] ^= 0xff;
                *response_grant_token = surface::SurfaceResponseGrantToken::new(bytes);
            }
        }
        selector
    }

    fn assert_exact_selector_rejection_is_non_consuming(
        corruption: ExactSelectorCorruption,
        expected_stale: bool,
        expected_code: surface::SurfaceMutationErrorCode,
    ) {
        let cwd = tempfile::tempdir().unwrap();
        let (answer_tx, answer_rx) = mpsc::sync_channel(1);
        let host = RuntimeHost::start_with_executor(Arc::new(ExactSelectorUserInputExecutor {
            answer_tx,
        }))
        .expect("start runtime host");
        let thread = host
            .start_thread(
                surface_test_config(cwd.path().to_path_buf(), HistoryMode::Record),
                "validate exact interaction selector",
            )
            .expect("start recorded runtime thread");
        let surface = thread.surface();
        let attachment = fresh_surface_interaction_attachment(&surface);
        let _subscription = surface
            .claim_subscription(&attachment.subscription)
            .expect("claim interaction subscription");
        let reserved = committed_surface_value(
            attachment
                .client
                .reserve_operation(
                    surface_request_id(),
                    surface_user_turn_intent(
                        &attachment.baseline.snapshot,
                        "request exact interaction",
                    ),
                )
                .expect("reserve typed operation"),
        );
        let operation_id = reserved.operation_id.clone();
        let _ = committed_surface_value(
            attachment
                .client
                .admit_reserved(
                    surface_request_id(),
                    operation_id.clone(),
                    reserved.lease.lease_id,
                )
                .expect("admit typed operation"),
        );
        let deadline = Instant::now() + SURFACE_TEST_TIMEOUT;
        let exact_selector = loop {
            let probe = thread
                .surface_actor_probe_for_test(operation_id.clone())
                .expect("probe resident interaction");
            if let Some(selector) = probe.exact_interaction_selector {
                break selector;
            }
            assert!(
                Instant::now() < deadline,
                "typed interaction did not become resident"
            );
            std::thread::yield_now();
        };
        let response = surface::BoundInteractionResponse::new(
            surface::SurfaceResponseId::try_from_bytes(*uuid::Uuid::now_v7().as_bytes())
                .expect("generated UUID is v7"),
            surface::SurfaceClientInteractionAnswer::UserInput {
                decision: surface::SurfaceUserInputDecision::Answer(surface::DisplayText::new(
                    "accepted",
                )),
            },
            surface::BrokerInteractionAnswerPolicy::NativeStrict,
            surface::ApplicableAuthorityFingerprint::not_applicable(),
        );
        let rejected = thread
            .respond_surface_interaction_for_test(
                attachment.client.clone(),
                surface_request_id(),
                corrupt_exact_selector(exact_selector.clone(), corruption),
                response.clone(),
            )
            .expect("actor returns typed selector rejection");
        let (actual_stale, actual_code) = match rejected {
            surface::MutationReply::Uncommitted {
                mutation: surface::UncommittedMutation::Invalid { error, .. },
            } => (false, error.error().code),
            surface::MutationReply::Uncommitted {
                mutation: surface::UncommittedMutation::Stale { error, .. },
            } => (true, error.error().code),
            _ => panic!("invalid exact selector consumed or deferred the interaction"),
        };
        assert_eq!(actual_stale, expected_stale);
        assert_eq!(actual_code, expected_code);
        assert!(
            answer_rx.try_recv().is_err(),
            "invalid exact selector woke the native waiter"
        );

        let _ = committed_surface_value(
            thread
                .respond_surface_interaction_for_test(
                    attachment.client.clone(),
                    surface_request_id(),
                    exact_selector,
                    response,
                )
                .expect("valid exact selector remains usable"),
        );
        assert_eq!(
            answer_rx.recv_timeout(SURFACE_TEST_TIMEOUT).unwrap(),
            Some("accepted".to_string())
        );
        let _ = attachment
            .client
            .wait_operation_terminal(surface_request_id(), operation_id)
            .expect("wait exact-selector operation terminal");
        host.shutdown().expect("shutdown runtime host");
    }

    #[test]
    fn failed_typed_admission_is_terminal_and_allows_next_turn_without_restart() {
        let cwd = tempfile::tempdir().unwrap();
        let (entered_tx, entered_rx) = mpsc::sync_channel(1);
        let (release_tx, release_rx) = mpsc::sync_channel(1);
        let host = RuntimeHost::start_with_executor(Arc::new(GatedSuccessExecutor {
            entered: entered_tx,
            release: Mutex::new(release_rx),
        }))
        .expect("start runtime host");
        let thread = host
            .start_thread(
                surface_test_config(cwd.path().to_path_buf(), HistoryMode::Record),
                "repair failed typed admission",
            )
            .expect("start recorded runtime thread");
        let transcript_path = SessionStore::new()
            .load_session(thread.thread_id())
            .expect("load runtime transcript")
            .path;
        let surface = thread.surface();
        let attachment = fresh_surface_attachment(&surface);
        let first = committed_surface_value(
            attachment
                .client
                .reserve_operation(
                    surface_request_id(),
                    surface_user_turn_intent(&attachment.baseline.snapshot, "first turn"),
                )
                .expect("reserve first typed operation"),
        );
        surface::JsonlSurfaceCommitLedger::inject_generation_append_failure_once(
            transcript_path.clone(),
        );
        surface::JsonlSurfaceCommitLedger::inject_admission_repair_append_failure_once(
            transcript_path.clone(),
        );
        assert!(
            attachment
                .client
                .admit_reserved(
                    surface_request_id(),
                    first.operation_id.clone(),
                    first.lease.lease_id,
                )
                .is_err(),
            "admission should report the injected durable failure"
        );
        let failed = attachment
            .client
            .wait_operation_terminal(surface_request_id(), first.operation_id.clone())
            .expect("wait repaired admission terminal");
        assert!(matches!(
            failed,
            surface::WaitOperationTerminalResult::Terminal { value }
                if matches!(
                    value.terminal,
                    surface::OperationTerminal::Failed {
                        class: surface::FailureClass::Persistence,
                        ..
                    }
                )
        ));

        let second = committed_surface_value(
            attachment
                .client
                .reserve_operation(
                    surface_request_id(),
                    surface_user_turn_intent(&attachment.baseline.snapshot, "second turn"),
                )
                .expect("reserve second typed operation after repair"),
        );
        let admitted = committed_surface_value(
            attachment
                .client
                .admit_reserved(
                    surface_request_id(),
                    second.operation_id.clone(),
                    second.lease.lease_id,
                )
                .expect("admit second typed operation after repair"),
        );
        assert!(matches!(
            admitted,
            surface::AdmissionOutput::Admitted { .. }
        ));
        entered_rx
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("second turn did not reach executor");
        release_tx.send(()).expect("release second turn");
        let second_terminal = attachment
            .client
            .wait_operation_terminal(surface_request_id(), second.operation_id)
            .expect("wait second turn terminal");
        assert!(matches!(
            second_terminal,
            surface::WaitOperationTerminalResult::Terminal { value }
                if matches!(value.terminal, surface::OperationTerminal::Succeeded { .. })
        ));
        host.shutdown().expect("shutdown repaired runtime host");
    }

    #[test]
    fn typed_manual_compaction_cancel_settles_context_before_cancelled_terminal() {
        let cwd = tempfile::tempdir().unwrap();
        let (entered_tx, entered_rx) = mpsc::sync_channel(1);
        let (cancel_observed_tx, cancel_observed_rx) = mpsc::sync_channel(1);
        let (completed_tx, completed_rx) = mpsc::sync_channel(1);
        let host = RuntimeHost::start_with_executor(Arc::new(CancelAwareShutdownExecutor {
            entered: entered_tx,
            cancel_observed: cancel_observed_tx,
            completed: completed_tx,
        }))
        .expect("start runtime host");
        let thread = host
            .start_thread(
                surface_test_config(cwd.path().to_path_buf(), HistoryMode::Record),
                "cancel typed manual compaction",
            )
            .expect("start recorded runtime thread");
        let surface = thread.surface();
        let attachment = fresh_surface_attachment(&surface);
        let output = committed_surface_value(
            attachment
                .client
                .manual_compact(
                    surface_request_id(),
                    attachment.baseline.snapshot.context.revision,
                )
                .expect("start typed manual compaction"),
        );
        entered_rx
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("manual compaction entered executor");

        let _ = committed_surface_value(
            attachment
                .client
                .cancel_operation(surface_request_id(), output.operation_id.clone())
                .expect("cancel typed manual compaction"),
        );
        cancel_observed_rx
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("executor observed manual compaction cancel");
        completed_rx
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("manual compaction executor completed");
        let terminal = attachment
            .client
            .wait_operation_terminal(surface_request_id(), output.operation_id.clone())
            .expect("wait manual compaction terminal");
        assert!(matches!(
            terminal,
            surface::WaitOperationTerminalResult::Terminal { value }
                if matches!(
                    value.terminal,
                    surface::OperationTerminal::Cancelled {
                        reason: surface::CancelReason::User
                    }
                )
        ));
        let refreshed = fresh_surface_attachment(&surface);
        assert!(matches!(
            &refreshed.baseline.snapshot.context.compaction,
            surface::CompactionState::Completed { operation_id, .. }
                if operation_id == &output.operation_id
        ));

        host.shutdown().expect("shutdown runtime host");
    }

    #[test]
    fn typed_manual_compaction_completion_append_failure_retries_before_terminal() {
        let cwd = tempfile::tempdir().unwrap();
        let (entered_tx, entered_rx) = mpsc::sync_channel(2);
        let (release_tx, release_rx) = mpsc::sync_channel(1);
        let host = RuntimeHost::start_with_executor(Arc::new(GatedSuccessExecutor {
            entered: entered_tx,
            release: Mutex::new(release_rx),
        }))
        .expect("start runtime host");
        let thread = host
            .start_thread(
                surface_test_config(cwd.path().to_path_buf(), HistoryMode::Record),
                "retry typed manual compaction completion",
            )
            .expect("start recorded runtime thread");
        let transcript_path = SessionStore::new()
            .load_session(thread.thread_id())
            .expect("load runtime transcript")
            .path;
        let surface = thread.surface();
        let attachment = fresh_surface_attachment(&surface);
        let mut subscription = surface
            .claim_subscription(&attachment.subscription)
            .expect("claim manual compaction subscription");
        let compact_request_id = surface_request_id();
        let output = committed_surface_value(
            attachment
                .client
                .manual_compact(
                    compact_request_id.clone(),
                    attachment.baseline.snapshot.context.revision,
                )
                .expect("start typed manual compaction"),
        );
        entered_rx
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("manual compaction entered executor");
        surface::JsonlSurfaceCommitLedger::inject_manual_compaction_completion_append_failures(
            transcript_path,
            2,
        );
        release_tx.send(()).expect("release manual compaction");
        let deadline = Instant::now() + SURFACE_TEST_TIMEOUT;
        loop {
            let probe = thread
                .surface_actor_probe_for_test(output.operation_id.clone())
                .expect("probe retained manual compaction completion");
            if probe.pending_manual_compaction_completion {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "manual compaction completion was not retained for retry"
            );
            std::thread::yield_now();
        }
        assert!(matches!(
            attachment.client.reserve_operation(
                surface_request_id(),
                surface_user_turn_intent(
                    &attachment.baseline.snapshot,
                    "must not advance the cursor during compaction retry",
                ),
            ),
            Err(surface::SurfaceClientCommandError::RuntimeUnavailable)
        ));

        let terminal = attachment
            .client
            .wait_operation_terminal(surface_request_id(), output.operation_id.clone())
            .expect("wait retried manual compaction terminal");
        assert!(matches!(
            terminal,
            surface::WaitOperationTerminalResult::Terminal { value }
                if matches!(value.terminal, surface::OperationTerminal::Succeeded { .. })
        ));
        assert!(
            entered_rx.try_recv().is_err(),
            "completion retry must not execute compaction again"
        );
        let replayed = committed_surface_value(
            attachment
                .client
                .manual_compact(
                    compact_request_id,
                    attachment.baseline.snapshot.context.revision,
                )
                .expect("replay typed manual compaction request"),
        );
        assert_eq!(replayed.operation_id, output.operation_id);
        assert_eq!(replayed.admitted_cursor, output.admitted_cursor);
        assert!(
            entered_rx.try_recv().is_err(),
            "idempotent request replay must not execute compaction again"
        );

        let deadline = Instant::now() + SURFACE_TEST_TIMEOUT;
        let mut events = Vec::new();
        loop {
            while let Some(item) = subscription.try_recv() {
                if let surface::SurfaceSubscriptionItem::Batch { batch } = item {
                    events.extend(batch.events.as_slice().iter().cloned());
                }
            }
            if events.iter().any(|envelope| {
                matches!(
                    &envelope.event,
                    surface::SurfaceEvent::Operation(surface::OperationPatch::Terminal {
                        record
                    }) if record.operation_id == output.operation_id
                )
            }) {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "manual compaction subscription did not publish terminal"
            );
            std::thread::yield_now();
        }
        let completed = events
            .iter()
            .enumerate()
            .filter_map(|(index, envelope)| {
                matches!(
                    &envelope.event,
                    surface::SurfaceEvent::Context(surface::SurfaceContextSnapshot {
                        compaction: surface::CompactionState::Completed {
                            operation_id,
                            ..
                        },
                        ..
                    }) if operation_id == &output.operation_id
                )
                .then_some(index)
            })
            .collect::<Vec<_>>();
        assert_eq!(
            completed.len(),
            1,
            "completion batch must commit exactly once"
        );
        let terminal_index = events
            .iter()
            .position(|envelope| {
                matches!(
                    &envelope.event,
                    surface::SurfaceEvent::Operation(surface::OperationPatch::Terminal {
                        record
                    }) if record.operation_id == output.operation_id
                )
            })
            .expect("terminal event");
        assert!(
            completed[0] < terminal_index,
            "completion fact must be durable before terminal"
        );

        host.shutdown().expect("shutdown runtime host");
    }

    #[test]
    fn host_shutdown_bounds_persistent_workflow_completion_failure() {
        if !crate::workflow::host::WorkflowHost::node_available() {
            return;
        }
        let _env = crate::history::lock_test_env();
        let home = tempfile::tempdir().unwrap();
        let _home = crate::history::redirect_test_orca_home(home.path());
        let cwd = tempfile::tempdir().unwrap();
        let workflow_dir = cwd.path().join(".orca").join("workflows");
        std::fs::create_dir_all(&workflow_dir).unwrap();
        std::fs::write(
            workflow_dir.join("bounded-shutdown.js"),
            "export const meta = { name: 'bounded-shutdown', description: 'bounded shutdown', phases: ['main'] };\nexport default 'done';",
        )
        .unwrap();
        orca_core::config::folder_trust::set_trust_with_config_dir(
            cwd.path(),
            home.path(),
            orca_core::config::folder_trust::TrustLevel::Trusted,
        )
        .unwrap();
        let mut config = surface_test_config(cwd.path().to_path_buf(), HistoryMode::Record);
        config.approval_mode = ApprovalMode::FullAuto;
        let host = RuntimeHost::start().expect("start workflow runtime");
        let thread = host
            .start_thread(config, "bounded workflow shutdown")
            .expect("start workflow thread");
        let transcript_path = SessionStore::new()
            .load_session(thread.thread_id())
            .expect("load workflow transcript")
            .path;
        surface::JsonlSurfaceCommitLedger::inject_workflow_completion_append_failures(
            transcript_path,
            100,
        );
        let attachment = fresh_surface_attachment_with_capabilities(
            &thread.surface(),
            BTreeSet::from([
                surface::SurfaceCapability::ReadSnapshot,
                surface::SurfaceCapability::ManageWorkflow,
            ]),
        );
        let output = committed_surface_value(
            attachment
                .client
                .workflow_control(
                    surface_request_id(),
                    surface::WorkflowControlAction::Launch {
                        catalog_entry_id: surface::SurfaceCatalogEntryId::try_new(
                            "bounded-shutdown",
                        )
                        .unwrap(),
                        observed_catalog_revision: surface::WorkflowCatalogRevision::try_new(1)
                            .unwrap(),
                        args: Vec::new(),
                        parent: None,
                    },
                )
                .expect("launch typed workflow"),
        );
        let operation_id = output.operation_id.expect("workflow operation");
        let deadline = Instant::now() + SURFACE_TEST_TIMEOUT;
        while !thread
            .surface_actor_probe_for_test(operation_id.clone())
            .expect("probe workflow completion")
            .pending_workflow_completion
        {
            assert!(
                Instant::now() < deadline,
                "workflow completion failure was not retained for retry"
            );
            std::thread::yield_now();
        }

        let shutdown_started = Instant::now();
        assert!(
            host.shutdown().is_err(),
            "persistent workflow completion failure must fail shutdown"
        );
        assert!(
            shutdown_started.elapsed() < Duration::from_secs(3),
            "workflow completion recovery must not keep HostShutdown pending forever"
        );
    }

    #[test]
    fn workflow_cancel_checkpoint_failure_retries_exact_batch_before_signalling_worker() {
        if !crate::workflow::host::WorkflowHost::node_available() {
            return;
        }
        let _env = crate::history::lock_test_env();
        let home = tempfile::tempdir().unwrap();
        let _home = crate::history::redirect_test_orca_home(home.path());
        let cwd = tempfile::tempdir().unwrap();
        let workflow_dir = cwd.path().join(".orca").join("workflows");
        std::fs::create_dir_all(&workflow_dir).unwrap();
        std::fs::write(
            workflow_dir.join("retry-cancel.js"),
            "export const meta = { name: 'retry-cancel', description: 'retry cancel', phases: ['main'] };\nexport default await phase('main', async () => agent('mock_stream_delay_ms 30000'));",
        )
        .unwrap();
        orca_core::config::folder_trust::set_trust_with_config_dir(
            cwd.path(),
            home.path(),
            orca_core::config::folder_trust::TrustLevel::Trusted,
        )
        .unwrap();
        let (foreground_entered_tx, foreground_entered_rx) = mpsc::sync_channel(1);
        let (foreground_release_tx, foreground_release_rx) = mpsc::sync_channel(1);
        let host = RuntimeHost::start_with_executor(Arc::new(GatedSuccessExecutor {
            entered: foreground_entered_tx,
            release: Mutex::new(foreground_release_rx),
        }))
        .expect("start workflow cancel retry runtime");
        let mut config = surface_test_config(cwd.path().to_path_buf(), HistoryMode::Record);
        config.approval_mode = ApprovalMode::FullAuto;
        let thread = host
            .start_thread(config, "retry workflow cancellation")
            .expect("start recorded workflow thread");
        let transcript_path = SessionStore::new()
            .load_session(thread.thread_id())
            .expect("load workflow transcript")
            .path;
        let surface_handle = thread.surface();
        let attachment = fresh_surface_attachment_with_capabilities(
            &surface_handle,
            BTreeSet::from([
                surface::SurfaceCapability::ReadSnapshot,
                surface::SurfaceCapability::SubmitOperation,
                surface::SurfaceCapability::ControlBoundOperation,
                surface::SurfaceCapability::ManageWorkflow,
            ]),
        );
        let initial_cursor = attachment.baseline.cursor.clone();
        let mut subscription = surface_handle
            .claim_subscription(&attachment.subscription)
            .expect("claim workflow cancellation subscription");
        let workflow = committed_surface_value(
            attachment
                .client
                .workflow_control(
                    surface_request_id(),
                    surface::WorkflowControlAction::Launch {
                        catalog_entry_id: surface::SurfaceCatalogEntryId::try_new("retry-cancel")
                            .unwrap(),
                        observed_catalog_revision: surface::WorkflowCatalogRevision::try_new(1)
                            .unwrap(),
                        args: Vec::new(),
                        parent: None,
                    },
                )
                .expect("launch cancellable workflow"),
        );
        let workflow_operation_id = workflow.operation_id.expect("workflow operation");
        let foreground = committed_surface_value(
            attachment
                .client
                .reserve_operation(
                    surface_request_id(),
                    surface_user_turn_intent(
                        &attachment.baseline.snapshot,
                        "keep foreground active during workflow cancel recovery",
                    ),
                )
                .expect("reserve foreground turn"),
        );
        let _ = committed_surface_value(
            attachment
                .client
                .admit_reserved(
                    surface_request_id(),
                    foreground.operation_id.clone(),
                    foreground.lease.lease_id,
                )
                .expect("admit foreground turn"),
        );
        foreground_entered_rx
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("foreground turn did not enter executor");

        surface::JsonlSurfaceCommitLedger::inject_terminal_checkpoint_failure_once(
            transcript_path.clone(),
        );
        assert!(matches!(
            attachment
                .client
                .cancel_operation(surface_request_id(), workflow_operation_id.clone()),
            Err(surface::SurfaceClientCommandError::RuntimeUnavailable)
        ));

        let deadline = Instant::now() + SURFACE_TEST_TIMEOUT;
        let recovered_control = loop {
            let mut found = None;
            while let Some(item) = subscription.try_recv() {
                let surface::SurfaceSubscriptionItem::Batch { batch } = item else {
                    continue;
                };
                if batch.events.as_slice().iter().any(|event| {
                    matches!(
                        &event.event,
                        surface::SurfaceEvent::Operation(
                            surface::OperationPatch::ControlIntentCommitted {
                                operation_id,
                                intent: surface::PendingControlIntent::Terminalize {
                                    cause: surface::TerminalizationCause::UserCancel,
                                    ..
                                },
                                ..
                            }
                        ) if operation_id == &workflow_operation_id
                    )
                }) {
                    found = Some(batch);
                    break;
                }
            }
            if found.is_some() || Instant::now() >= deadline {
                break found;
            }
            std::thread::yield_now();
        };
        if recovered_control.is_none() {
            foreground_release_tx
                .send(())
                .expect("release foreground after failed assertion");
            let _ = host.shutdown();
            panic!("prepared workflow cancellation was not retried");
        }
        let recovered_control = recovered_control.expect("checked recovered workflow control");
        let during_cancel = fresh_surface_attachment_with_capabilities(
            &surface_handle,
            BTreeSet::from([surface::SurfaceCapability::ReadSnapshot]),
        )
        .baseline
        .snapshot;
        assert_eq!(
            during_cancel
                .foreground_operation
                .as_ref()
                .map(|operation| &operation.operation_id),
            Some(&foreground.operation_id),
            "background recovery must not cancel the active foreground operation"
        );
        foreground_release_tx
            .send(())
            .expect("release foreground after background cancellation");
        let _ = attachment
            .client
            .wait_operation_terminal(surface_request_id(), foreground.operation_id)
            .expect("wait foreground terminal");
        let terminal = attachment
            .client
            .wait_operation_terminal(surface_request_id(), workflow_operation_id.clone())
            .expect("wait recovered workflow cancellation");
        assert!(matches!(
            terminal,
            surface::WaitOperationTerminalResult::Terminal {
                value: surface::OperationTerminalAtCursor {
                    terminal: surface::OperationTerminal::Cancelled {
                        reason: surface::CancelReason::User
                    },
                    ..
                }
            }
        ));
        let recovered =
            surface::JsonlSurfaceCommitLedger::new(transcript_path, initial_cursor.clone())
                .recover_batches()
                .expect("read recovered workflow cancellation ledger");
        let exact = recovered
            .committed
            .iter()
            .filter(|batch| {
                batch.events.as_slice().iter().any(|event| {
                    matches!(
                        &event.event,
                        surface::SurfaceEvent::Operation(
                            surface::OperationPatch::ControlIntentCommitted {
                                operation_id,
                                ..
                            }
                        ) if operation_id == &workflow_operation_id
                    )
                })
            })
            .collect::<Vec<_>>();
        assert_eq!(exact.len(), 1);
        assert_eq!(exact[0].commit_class, recovered_control.commit_class);
        assert_eq!(exact[0].cursor_before, recovered_control.cursor_before);
        assert_eq!(exact[0].cursor_after, recovered_control.cursor_after);
        assert_eq!(exact[0].batch_digest, recovered_control.batch_digest);

        host.shutdown()
            .expect("shutdown workflow cancel retry host");
    }

    #[test]
    fn active_host_shutdown_settles_prepared_workflow_cancel_before_terminalizing_foreground() {
        if !crate::workflow::host::WorkflowHost::node_available() {
            return;
        }
        let _env = crate::history::lock_test_env();
        let fixture = checkpoint_failed_workflow_cancel_with_active_foreground(2);
        let shutdown_started = Instant::now();
        fixture
            .host
            .shutdown()
            .expect("transient prepared workflow cancel must settle during host shutdown");
        assert!(
            shutdown_started.elapsed() < Duration::from_secs(3),
            "prepared workflow cancel must not make host shutdown unbounded"
        );
        fixture
            .foreground_cancel_observed
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("foreground executor did not observe host shutdown");
        fixture
            .foreground_completed
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("foreground executor did not join during host shutdown");
        let recovered = surface::JsonlSurfaceCommitLedger::new(
            fixture.transcript_path,
            fixture.prepared_control.cursor_before.clone(),
        )
        .recover_batches()
        .expect("read settled workflow cancel");
        assert!(recovered.prepared.is_none());
        assert_eq!(
            recovered
                .committed
                .iter()
                .filter(|batch| {
                    batch.commit_class == fixture.prepared_control.commit_class
                        && batch.batch_digest == fixture.prepared_control.batch_digest
                })
                .count(),
            1
        );
    }

    #[test]
    fn persistent_workflow_cancel_wins_completed_before_reap_during_cold_restart() {
        if !crate::workflow::host::WorkflowHost::node_available() {
            return;
        }
        let _env = crate::history::lock_test_env();
        let fixture = checkpoint_failed_workflow_cancel_with_active_foreground(100);
        let session_id = fixture.thread.thread_id().to_string();
        let resume_cwd = fixture.cwd.path().to_path_buf();
        let transcript_path = fixture.transcript_path.clone();
        let operation_id = fixture.workflow_operation_id.clone();
        let task_id = fixture.task_id.clone();
        let workflow_run_id = fixture.workflow_run_id.clone();
        let prepared = fixture.prepared_control.clone();
        let shutdown_started = Instant::now();
        let error = fixture
            .host
            .shutdown()
            .expect_err("persistent workflow cancel recovery must retain cold-restart ownership");
        assert!(
            shutdown_started.elapsed() < Duration::from_secs(3),
            "persistent workflow cancel recovery must leave live shutdown in bounded time"
        );
        assert!(
            matches!(
                error,
                RuntimeHostError::ThreadStartFailed { ref message }
                    if message.contains(
                        "typed workflow cancellation recovery was retained for cold restart"
                    )
            ),
            "unexpected cold-handoff error: {error}"
        );
        fixture
            .foreground_cancel_observed
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("foreground executor did not observe bounded host shutdown");
        fixture
            .foreground_completed
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("foreground executor did not join before cold handoff");

        surface::JsonlSurfaceCommitLedger::clear_terminal_checkpoint_failures(
            transcript_path.clone(),
        );
        TaskRegistry::new_persistent(
            session_id.clone(),
            fixture._home.path().join("task-sessions"),
        )
        .expect("reopen durable workflow task registry")
        .complete(
            task_id.as_str(),
            "worker completed before actor reaped the outcome".to_string(),
        )
        .expect("persist completed-before-reap workflow outcome");
        let resumed_host = RuntimeHost::start_with_executor(Arc::new(PanicExecutor))
            .expect("start cold recovery runtime");
        let resumed = resumed_host
            .start_thread(
                surface_test_config(resume_cwd, HistoryMode::Resume(session_id)),
                "recover prepared workflow cancellation",
            )
            .expect("resume prepared workflow cancellation");
        let snapshot = fresh_surface_attachment_with_capabilities(
            &resumed.surface(),
            BTreeSet::from([surface::SurfaceCapability::ReadSnapshot]),
        )
        .baseline
        .snapshot;
        let operation = snapshot
            .foreground_operation
            .iter()
            .chain(snapshot.queued_operations.iter())
            .chain(snapshot.operation_history.iter())
            .find(|operation| operation.operation_id == operation_id)
            .expect("cold recovery must retain the workflow operation");
        assert!(matches!(
            operation
                .terminal
                .as_ref()
                .map(|terminal| &terminal.terminal),
            Some(surface::OperationTerminal::Cancelled {
                reason: surface::CancelReason::User
            })
        ));
        assert!(snapshot.tasks.iter().any(|task| {
            task.task_id == task_id && task.status == surface::SurfaceTaskStatus::Stopped
        }));
        assert!(snapshot.workflows.iter().any(|workflow| {
            workflow.workflow_run_id == workflow_run_id
                && workflow.status == surface::SurfaceWorkflowStatus::Stopped
        }));
        let recovered =
            surface::JsonlSurfaceCommitLedger::new(transcript_path, prepared.cursor_before.clone())
                .recover_batches()
                .expect("read cold-recovered workflow cancellation");
        assert!(recovered.prepared.is_none());
        let exact = recovered
            .committed
            .iter()
            .filter(|batch| {
                batch.commit_class == prepared.commit_class
                    && batch.batch_digest == prepared.batch_digest
            })
            .collect::<Vec<_>>();
        assert_eq!(exact.len(), 1);
        assert_eq!(exact[0].cursor_before, prepared.cursor_before);
        assert_eq!(exact[0].cursor_after, prepared.cursor_after);
        resumed_host
            .shutdown()
            .expect("shutdown cold recovery runtime");
    }

    #[test]
    fn typed_manual_compaction_history_failure_keeps_conversation_and_context_recoverable() {
        let cwd = tempfile::tempdir().unwrap();
        let config = surface_test_config(cwd.path().to_path_buf(), HistoryMode::Record);
        let host = RuntimeHost::start().expect("start runtime host");
        let thread = host
            .start_thread(config.clone(), "fail manual compaction history")
            .expect("start recorded runtime thread");
        let thread_id = thread.thread_id().to_string();
        let transcript = SessionStore::new()
            .load_session(&thread_id)
            .expect("load runtime transcript");
        let before_messages = transcript.messages.clone();
        crate::thread_store::SessionWriter::inject_manual_compaction_snapshot_failure_once(
            transcript.path,
        );
        let surface = thread.surface();
        let attachment = fresh_surface_attachment(&surface);
        let output = committed_surface_value(
            attachment
                .client
                .manual_compact(
                    surface_request_id(),
                    attachment.baseline.snapshot.context.revision,
                )
                .expect("start typed manual compaction"),
        );
        let terminal = attachment
            .client
            .wait_operation_terminal(surface_request_id(), output.operation_id)
            .expect("wait failed manual compaction terminal");
        assert!(matches!(
            terminal,
            surface::WaitOperationTerminalResult::Terminal { value }
                if matches!(value.terminal, surface::OperationTerminal::Failed { .. })
        ));
        let settled = fresh_surface_attachment(&surface);
        assert!(matches!(
            settled.baseline.snapshot.context.compaction,
            surface::CompactionState::Idle
        ));
        thread
            .shutdown()
            .expect("shutdown failed compaction thread");
        host.shutdown().expect("shutdown failed compaction host");

        let recovered = SessionStore::new()
            .load_session(&thread_id)
            .expect("reload failed compaction transcript");
        assert_eq!(
            format!("{:?}", recovered.messages),
            format!("{before_messages:?}")
        );
        let resumed_host = RuntimeHost::start().expect("start recovery host");
        let resumed = resumed_host
            .start_thread(
                RunConfig {
                    history_mode: HistoryMode::Resume(thread_id),
                    ..config
                },
                "recover failed manual compaction",
            )
            .expect("resume failed manual compaction thread");
        assert_eq!(
            resumed
                .snapshot()
                .expect("read recovered runtime snapshot")
                .messages()
                .len(),
            before_messages.len()
        );
        resumed.shutdown().expect("shutdown recovered thread");
        resumed_host.shutdown().expect("shutdown recovered host");
    }

    #[test]
    fn suspended_surface_operation_resumes_same_identity_after_durable_barriers() {
        let cwd = tempfile::tempdir().unwrap();
        let (entered_tx, entered_rx) = mpsc::sync_channel(2);
        let host = RuntimeHost::start_with_executor(Arc::new(SuspendThenResumeExecutor {
            calls: AtomicUsize::new(0),
            entered: entered_tx,
        }))
        .expect("start runtime host");
        let thread = host
            .start_thread(
                surface_test_config(cwd.path().to_path_buf(), HistoryMode::Record),
                "resume suspended typed operation",
            )
            .expect("start recorded runtime thread");
        let transcript_path = SessionStore::new()
            .load_session(thread.thread_id())
            .expect("load recorded suspended operation")
            .path;
        let surface = thread.surface();
        let attachment = fresh_surface_attachment(&surface);
        let reserved = committed_surface_value(
            attachment
                .client
                .reserve_operation(
                    surface_request_id(),
                    surface_user_turn_intent(
                        &attachment.baseline.snapshot,
                        "resume the same operation",
                    ),
                )
                .expect("reserve typed operation"),
        );
        let operation_id = reserved.operation_id.clone();
        let admitted = committed_surface_value(
            attachment
                .client
                .admit_reserved(
                    surface_request_id(),
                    operation_id.clone(),
                    reserved.lease.lease_id,
                )
                .expect("admit typed operation"),
        );
        let surface::AdmissionOutput::Admitted { .. } = admitted else {
            panic!("operation was queued instead of admitted");
        };
        assert_eq!(entered_rx.recv_timeout(SURFACE_TEST_TIMEOUT).unwrap(), 0);
        thread
            .suspend_surface_operation_for_test(operation_id.clone())
            .expect("suspend typed operation");

        let suspended_snapshot = fresh_surface_attachment_with_capabilities(
            &surface,
            BTreeSet::from([surface::SurfaceCapability::ReadSnapshot]),
        )
        .baseline
        .snapshot;
        let recovery = suspended_snapshot
            .recoverable_user_operation()
            .expect("suspended operation is publicly recoverable");
        assert_eq!(recovery.operation_id(), &operation_id);
        surface::JsonlSurfaceCommitLedger::inject_generation_append_failure_once(transcript_path);
        let retry_deadline = Instant::now() + SURFACE_TEST_TIMEOUT;
        let rebased = loop {
            let current = fresh_surface_attachment_with_capabilities(
                &surface,
                BTreeSet::from([surface::SurfaceCapability::ReadSnapshot]),
            )
            .baseline
            .snapshot;
            let recovery = current
                .recoverable_user_operation()
                .expect("suspended operation remains publicly recoverable");
            assert_eq!(
                attachment
                    .client
                    .resume_recoverable(surface_request_id(), recovery)
                    .err(),
                Some(surface::SurfaceClientCommandError::RuntimeUnavailable)
            );
            let rebased = fresh_surface_attachment_with_capabilities(
                &surface,
                BTreeSet::from([surface::SurfaceCapability::ReadSnapshot]),
            )
            .baseline
            .snapshot;
            let rebased_operation = rebased
                .foreground_operation
                .as_ref()
                .filter(|operation| operation.operation_id == operation_id)
                .expect("failed resume remains a recoverable foreground operation");
            if matches!(
                rebased_operation.phase,
                surface::OperationPhase::Suspended {
                    cause: surface::SuspensionCause::RecoveryRequired { .. }
                }
            ) {
                break rebased;
            }
            assert!(
                matches!(
                    rebased_operation.phase,
                    surface::OperationPhase::Suspended {
                        cause: surface::SuspensionCause::Interrupted { .. }
                    }
                ),
                "resume before generation join changed durable state: {rebased_operation:#?}"
            );
            assert!(
                Instant::now() < retry_deadline,
                "generation did not settle before resume retry deadline"
            );
            std::thread::yield_now();
        };
        let rebased_operation = rebased
            .foreground_operation
            .as_ref()
            .filter(|operation| operation.operation_id == operation_id)
            .expect("failed resume remains a recoverable foreground operation");
        assert!(
            matches!(
                rebased_operation.phase,
                surface::OperationPhase::Suspended {
                    cause: surface::SuspensionCause::RecoveryRequired { .. }
                }
            ),
            "failed resume state: {rebased_operation:#?}"
        );
        assert!(rebased_operation.pending_control.is_none());
        assert_eq!(rebased_operation.generations.len(), 2);
        assert!(matches!(
            rebased_operation.generations[1].stop_reason,
            Some(surface::GenerationStopReason::NotStarted {
                reason: surface::NotStartedReason::RuntimeRestart,
            })
        ));
        let recovery = rebased
            .recoverable_user_operation()
            .expect("failed resume is publicly recoverable again");
        let resumed = committed_surface_value(
            attachment
                .client
                .resume_recoverable(surface_request_id(), recovery)
                .expect("retry rebased typed operation"),
        );
        assert_eq!(resumed.operation_id, operation_id);
        assert_eq!(resumed.generation.generation_id.get(), 2);
        assert_eq!(
            resumed.resume_starting.role,
            surface::ResumeTransitionRole::ResumeStarting
        );
        assert_eq!(
            resumed.generation_reserved.role,
            surface::ResumeTransitionRole::GenerationReserved
        );
        assert_eq!(
            resumed.generation_started.role,
            surface::ResumeTransitionRole::GenerationStarted
        );
        assert_eq!(entered_rx.recv_timeout(SURFACE_TEST_TIMEOUT).unwrap(), 1);
        let terminal = attachment
            .client
            .wait_operation_terminal(surface_request_id(), operation_id.clone())
            .expect("wait resumed operation terminal");
        let snapshot = fresh_surface_attachment_with_capabilities(
            &surface,
            BTreeSet::from([surface::SurfaceCapability::ReadSnapshot]),
        )
        .baseline
        .snapshot;
        host.shutdown().expect("shutdown runtime host");

        assert!(matches!(
            terminal,
            surface::WaitOperationTerminalResult::Terminal { value }
                if value.operation_id == operation_id
                    && matches!(value.terminal, surface::OperationTerminal::Succeeded { .. })
        ));
        let operation = snapshot
            .foreground_operation
            .iter()
            .chain(snapshot.queued_operations.iter())
            .chain(snapshot.operation_history.iter())
            .find(|operation| operation.operation_id == operation_id)
            .expect("resumed operation reached history");
        assert_eq!(operation.generations.len(), 3);
        assert!(matches!(
            operation.generations[2].attempt,
            surface::GenerationAttempt::RecoveryReplacement
        ));
    }

    type SuspendedOperationFixture = (
        String,
        surface::SurfaceOperationId,
        surface::SurfaceGenerationId,
        surface::Sha256Digest,
    );

    fn suspended_operation_fixture_path() -> PathBuf {
        PathBuf::from(std::env::var_os("ORCA_HOME").expect("ORCA_HOME for recovery child"))
            .join("suspended-operation-recovery.json")
    }

    fn run_suspended_operation_seed_child() -> ! {
        let cwd = tempfile::tempdir().unwrap();
        let (entered_tx, entered_rx) = mpsc::sync_channel(1);
        let host = RuntimeHost::start_with_executor(Arc::new(SuspendThenResumeExecutor {
            calls: AtomicUsize::new(0),
            entered: entered_tx,
        }))
        .expect("start suspended-operation seed host");
        let thread = host
            .start_thread(
                surface_test_config(cwd.path().to_path_buf(), HistoryMode::Record),
                "seed suspended operation",
            )
            .expect("start suspended-operation seed thread");
        let surface = thread.surface();
        let attachment = fresh_surface_attachment(&surface);
        let reserved = committed_surface_value(
            attachment
                .client
                .reserve_operation(
                    surface_request_id(),
                    surface_user_turn_intent(
                        &attachment.baseline.snapshot,
                        "recover this operation after restart",
                    ),
                )
                .expect("reserve suspended-operation fixture"),
        );
        let operation_id = reserved.operation_id.clone();
        let admitted = committed_surface_value(
            attachment
                .client
                .admit_reserved(
                    surface_request_id(),
                    operation_id.clone(),
                    reserved.lease.lease_id,
                )
                .expect("admit suspended-operation fixture"),
        );
        let surface::AdmissionOutput::Admitted {
            first_generation, ..
        } = admitted
        else {
            panic!("fixture operation was queued");
        };
        entered_rx
            .recv_timeout(SURFACE_TEST_TIMEOUT)
            .expect("fixture executor did not start");
        thread
            .suspend_surface_operation_for_test(operation_id.clone())
            .expect("durably suspend fixture operation");
        let snapshot = fresh_surface_attachment_with_capabilities(
            &surface,
            BTreeSet::from([surface::SurfaceCapability::ReadSnapshot]),
        )
        .baseline
        .snapshot;
        let operation = snapshot
            .foreground_operation
            .as_ref()
            .filter(|operation| operation.operation_id == operation_id)
            .expect("fixture operation remains suspended");
        let fixture: SuspendedOperationFixture = (
            thread.thread_id().to_string(),
            operation_id,
            first_generation.generation_id,
            surface::canonical_replayability_digest(&operation.intent.initial_replayability),
        );
        std::fs::write(
            suspended_operation_fixture_path(),
            serde_json::to_vec(&fixture).unwrap(),
        )
        .expect("write suspended operation fixture");
        std::mem::forget(host);
        std::process::exit(0)
    }

    fn run_suspended_operation_recovery_child(resume: bool) -> ! {
        let (thread_id, operation_id, _generation_id, _replayability_digest):
            SuspendedOperationFixture = serde_json::from_slice(
            &std::fs::read(suspended_operation_fixture_path())
                .expect("read suspended operation fixture"),
        )
        .unwrap();
        let cwd = tempfile::tempdir().unwrap();
        let (entered_tx, entered_rx) = mpsc::sync_channel(1);
        let executor = SuspendThenResumeExecutor {
            calls: AtomicUsize::new(1),
            entered: entered_tx,
        };
        let host = RuntimeHost::start_with_executor(Arc::new(executor))
            .expect("start suspended-operation recovery host");
        let thread = host
            .start_thread(
                surface_test_config(cwd.path().to_path_buf(), HistoryMode::Resume(thread_id)),
                "recover suspended operation",
            )
            .expect("resume suspended-operation thread");
        let surface = thread.surface();
        let attachment = fresh_surface_attachment(&surface);
        let operation = attachment
            .baseline
            .snapshot
            .foreground_operation
            .as_ref()
            .filter(|operation| operation.operation_id == operation_id)
            .expect("cold-recovered operation remains visible");
        assert!(matches!(
            operation.phase,
            surface::OperationPhase::Suspended { .. }
        ));

        if resume {
            let recovery = attachment
                .baseline
                .snapshot
                .recoverable_user_operation()
                .expect("cold-recovered operation is publicly recoverable");
            assert_eq!(recovery.operation_id(), &operation_id);
            let resumed = committed_surface_value(
                attachment
                    .client
                    .resume_recoverable(surface_request_id(), recovery)
                    .expect("resume cold-recovered operation"),
            );
            assert_eq!(resumed.operation_id, operation_id);
            assert_eq!(entered_rx.recv_timeout(SURFACE_TEST_TIMEOUT).unwrap(), 1);
            let terminal = attachment
                .client
                .wait_operation_terminal(surface_request_id(), operation_id)
                .expect("wait resumed cold-recovered operation");
            assert!(matches!(
                terminal,
                surface::WaitOperationTerminalResult::Terminal { value }
                    if matches!(value.terminal, surface::OperationTerminal::Succeeded { .. })
            ));
        } else {
            let cancelled = committed_surface_value(
                attachment
                    .client
                    .cancel_operation(surface_request_id(), operation_id.clone())
                    .expect("cancel cold-recovered operation"),
            );
            assert!(matches!(
                cancelled,
                surface::CancelOperationOutput::Accepted { .. }
            ));
            let terminal = attachment
                .client
                .wait_operation_terminal(surface_request_id(), operation_id)
                .expect("wait cancelled cold-recovered operation");
            assert!(matches!(
                terminal,
                surface::WaitOperationTerminalResult::Terminal { value }
                    if matches!(
                        value.terminal,
                        surface::OperationTerminal::Cancelled {
                            reason: surface::CancelReason::User,
                        }
                    )
            ));
            assert!(entered_rx.try_recv().is_err());
        }
        host.shutdown().expect("shutdown recovery host");
        std::process::exit(0)
    }

    #[test]
    fn cold_restart_exposes_exact_resume_and_cancel_for_suspended_operation() {
        if let Some(phase) = std::env::var_os(SUSPENDED_OPERATION_RECOVERY_CHILD_ENV) {
            match phase.to_string_lossy().as_ref() {
                "seed" => run_suspended_operation_seed_child(),
                "resume" => run_suspended_operation_recovery_child(true),
                "cancel" => run_suspended_operation_recovery_child(false),
                phase => panic!("unknown suspended-operation recovery phase: {phase}"),
            }
        }

        let home = tempfile::tempdir().unwrap();
        for recovery in ["resume", "cancel"] {
            for phase in ["seed", recovery] {
                let status = Command::new(std::env::current_exe().unwrap())
                    .arg("--exact")
                    .arg(
                        "runtime_host::tests::cold_restart_exposes_exact_resume_and_cancel_for_suspended_operation",
                    )
                    .arg("--nocapture")
                    .arg("--test-threads=1")
                    .env(SUSPENDED_OPERATION_RECOVERY_CHILD_ENV, phase)
                    .env("ORCA_HOME", home.path())
                    .status()
                    .expect("start suspended-operation recovery child");
                assert!(
                    status.success(),
                    "suspended-operation recovery child failed during {phase}"
                );
            }
        }
    }

    #[test]
